(** Earlier declarations override later declarations, as in [lookup_kind]. *)
Definition database_kinds (ds : list decl) : PTrieCode.t output :=
  fold_right (fun d kinds => PTrieCode.set (name d) (out d) kinds) PTrieCode.empty ds.
TimeFun database_kinds.

Definition database_max_name (ds : list decl) : positive :=
  fold_right (fun d bound => Pos.max (name d) bound) 1%positive ds.
TimeFun database_max_name.

(** Adding an earlier declaration preserves the presence of every already-declared name. *)
Lemma database_declaration_cons_nonempty : forall ds d f,
  lookup_kind ds f <> None -> lookup_kind (d :: ds) f <> None.
Proof.
  intros ds d f Hpresent. cbn [lookup_kind].
  destruct (Pos.eqb (name d) f); [discriminate | exact Hpresent].
Qed.

(** The stored name maximum is either the constant base or an actual declared name. *)
Lemma database_max_name_attained : forall ds,
  database_max_name ds = 1%positive \/ lookup_kind ds (database_max_name ds) <> None.
Proof.
  induction ds as [| d ds IH]; [now left |].
  assert (Htail : database_max_name ds = 1%positive \/
    lookup_kind (d :: ds) (database_max_name ds) <> None).
  { destruct IH as [Hbase | Hpresent]; [now left |].
    right. now apply database_declaration_cons_nonempty. }
  change (Pos.max (name d) (database_max_name ds) = 1%positive \/
    lookup_kind (d :: ds) (Pos.max (name d) (database_max_name ds)) <> None).
  unfold Pos.max. destruct (Pos.compare (name d) (database_max_name ds)); try exact Htail.
  right. cbn [lookup_kind]. rewrite Pos.eqb_refl. discriminate.
Qed.

Fixpoint database_slot_groups (next : N) (prepared : list (positive * database_slot_layout))
    (groups : PTrieCode.t (list (N * database_slot_layout)))
    : PTrieCode.t (list (N * database_slot_layout)) :=
  match prepared with
  | [] => groups
  | (f, layout) :: rest =>
    let previous := match PTrieCode.get f groups with Some slots => slots | None => [] end in
    database_slot_groups (N.succ next) rest (PTrieCode.set f ((next, layout) :: previous) groups)
  end.
TimeFun database_slot_groups.

(** The first slot of a function fixes its group rank and later slots get offsets. *)
Fixpoint database_rank_slots_from (kinds : PTrieCode.t output) (s : N)
    (groups : PTrieCode.t (N * N)) (sl : list (positive * list nat))
    : list (bool * N * N) :=
  match sl with
  | [] => []
  | (f, _) :: rest =>
    let declared := match PTrieCode.get f kinds with Some _ => true | None => false end in
    let place := match PTrieCode.get f groups with
      | Some position => position
      | None => (s, 0%N)
      end in
    (declared, fst place, snd place) ::
      database_rank_slots_from kinds (N.succ s)
        (PTrieCode.set f (fst place, N.succ (snd place)) groups) rest
  end.
TimeFun database_rank_slots_from.

Definition database_rank_slots (ds : list decl) (sl : list (positive * list nat))
    : list (bool * N * N) :=
  database_rank_slots_from (database_kinds ds) 0%N PTrieCode.empty sl.
TimeFun database_rank_slots.

Lemma database_rank_slots_from_length : forall kinds start groups sl,
  length (database_rank_slots_from kinds start groups sl) = length sl.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[f perm] rest IH]; intros start groups;
    cbn [database_rank_slots_from length]; [reflexivity |].
  now rewrite IH.
Qed.

Lemma database_rank_slots_from_flag : forall kinds start groups sl n f perm d g j,
  nth_error sl n = Some (f, perm) ->
  nth_error (database_rank_slots_from kinds start groups sl) n = Some (d, g, j) ->
  d = match PTrieCode.get f kinds with Some _ => true | None => false end.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH]; intros start groups n f perm d g j Hslot Hrank;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from] in Hslot, Hrank;
    try discriminate.
  - injection Hslot as <- <-. injection Hrank as <- _ _.
    reflexivity.
  - eapply IH; eassumption.
Qed.

Definition database_rank_groups_bounded (start : N)
    (groups : PTrieCode.t (N * N)) : Prop :=
  forall f g j, PTrieCode.get f groups = Some (g, j) ->
    (g <= start)%N /\ (j <= start)%N.

Lemma database_rank_groups_bounded_empty :
  database_rank_groups_bounded 0%N PTrieCode.empty.
Proof.
  intros f g j Hget. rewrite PTrie.get_empty in Hget. discriminate.
Qed.

Lemma database_rank_groups_bounded_step : forall start groups f,
  database_rank_groups_bounded start groups ->
  let place := match PTrieCode.get f groups with
    | Some position => position | None => (start, 0%N) end in
  database_rank_groups_bounded (N.succ start)
    (PTrieCode.set f (fst place, N.succ (snd place)) groups).
Proof.
  intros start groups f Hbounded place h g j Hget.
  destruct (Pos.eq_dec h f) as [-> | Hne].
  - rewrite PTrie.get_set_same in Hget.
    injection Hget as <- <-. unfold place.
    destruct (PTrieCode.get f groups) as [[rank count] |] eqn:Hprior;
      cbn [fst snd].
    + destruct (Hbounded f rank count Hprior). lia.
    + lia.
  - rewrite PTrie.get_set_other in Hget by exact Hne.
    destruct (Hbounded h g j Hget). lia.
Qed.

Definition database_rank_groups_fresh (start : N)
    (groups : PTrieCode.t (N * N)) : Prop :=
  forall f g j, PTrieCode.get f groups = Some (g, j) -> (g < start)%N.

Lemma database_rank_groups_fresh_empty :
  database_rank_groups_fresh 0%N PTrieCode.empty.
Proof.
  intros f g j Hget. rewrite PTrie.get_empty in Hget. discriminate.
Qed.

Lemma database_rank_groups_fresh_step : forall start groups f,
  database_rank_groups_fresh start groups ->
  let place := match PTrieCode.get f groups with
    | Some position => position | None => (start, 0%N) end in
  database_rank_groups_fresh (N.succ start)
    (PTrieCode.set f (fst place, N.succ (snd place)) groups).
Proof.
  intros start groups f Hfresh place h g j Hget.
  destruct (Pos.eq_dec h f) as [-> | Hne].
  - rewrite PTrie.get_set_same in Hget. injection Hget as <- <-.
    unfold place. destruct (PTrieCode.get f groups) as [[rank offset] |] eqn:Hprior;
      cbn [fst snd].
    + pose proof (Hfresh f rank offset Hprior). lia.
    + lia.
  - rewrite PTrie.get_set_other in Hget by exact Hne.
    pose proof (Hfresh h g j Hget). lia.
Qed.

Definition database_rank_groups_unique (groups : PTrieCode.t (N * N)) : Prop :=
  forall f h g j k, PTrieCode.get f groups = Some (g, j) ->
    PTrieCode.get h groups = Some (g, k) -> f = h.

Lemma database_rank_groups_unique_empty :
  database_rank_groups_unique PTrieCode.empty.
Proof.
  intros f h g j k Hget _. rewrite PTrie.get_empty in Hget. discriminate.
Qed.

Lemma database_rank_groups_unique_step : forall start groups f,
  database_rank_groups_fresh start groups -> database_rank_groups_unique groups ->
  let place := match PTrieCode.get f groups with
    | Some position => position | None => (start, 0%N) end in
  database_rank_groups_unique
    (PTrieCode.set f (fst place, N.succ (snd place)) groups).
Proof.
  intros start groups f Hfresh Hunique place h k g j l Hh Hk.
  destruct (Pos.eq_dec h f) as [-> | Hhf];
    destruct (Pos.eq_dec k f) as [-> | Hkf]; [reflexivity | | |].
  - rewrite PTrie.get_set_same in Hh.
    rewrite PTrie.get_set_other in Hk by exact Hkf.
    injection Hh as Hrank _. unfold place in Hrank.
    destruct (PTrieCode.get f groups) as [[rank offset] |] eqn:Hprior;
      cbn [fst] in Hrank.
    + subst g. exact (Hunique f k rank offset l Hprior Hk).
    + subst g. pose proof (Hfresh k start l Hk). lia.
  - rewrite PTrie.get_set_other in Hh by exact Hhf.
    rewrite PTrie.get_set_same in Hk.
    injection Hk as Hrank _. unfold place in Hrank.
    destruct (PTrieCode.get f groups) as [[rank offset] |] eqn:Hprior;
      cbn [fst] in Hrank.
    + subst g. exact (Hunique h f rank j offset Hh Hprior).
    + subst g. pose proof (Hfresh h start j Hh). lia.
  - rewrite PTrie.get_set_other in Hh by exact Hhf.
    rewrite PTrie.get_set_other in Hk by exact Hkf.
    exact (Hunique h k g j l Hh Hk).
Qed.

Lemma database_rank_slots_from_owner : forall kinds start groups sl,
  database_rank_groups_fresh start groups -> database_rank_groups_unique groups ->
  forall f g j, PTrieCode.get f groups = Some (g, j) ->
  forall n h perm d offset,
    nth_error sl n = Some (h, perm) ->
    nth_error (database_rank_slots_from kinds start groups sl) n =
      Some (d, g, offset) -> h = f.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups Hfresh Hunique f g j Howner n h perm d offset Hslot Hrank;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from] in Hslot, Hrank;
    try discriminate.
  - injection Hslot as <- <-.
    destruct (PTrieCode.get head groups) as [[rank count] |] eqn:Hhead.
    + injection Hrank as _ Hrank _.
      cbn [fst] in Hrank. subst rank.
      symmetry. eapply Hunique; [exact Howner | exact Hhead].
    + injection Hrank as _ Hrank _.
      cbn [fst] in Hrank. subst g.
      pose proof (Hfresh f start j Howner). lia.
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head
      (fst place, N.succ (snd place)) groups).
    assert (Hupdated : exists count, PTrieCode.get f updated = Some (g, count)).
    { destruct (Pos.eq_dec f head) as [-> | Hne].
      - exists (N.succ j). unfold updated, place.
        rewrite PTrie.get_set_same, Howner. reflexivity.
      - exists j. unfold updated.
        rewrite PTrie.get_set_other by exact Hne. exact Howner. }
    destruct Hupdated as [count Hupdated].
    eapply IH with (start := N.succ start) (groups := updated) (j := count).
    + unfold updated, place. now apply database_rank_groups_fresh_step.
    + unfold updated, place. now apply database_rank_groups_unique_step.
    + exact Hupdated.
    + exact Hslot.
    + exact Hrank.
Qed.

Lemma database_rank_slots_from_same_rank : forall kinds start groups sl,
  database_rank_groups_fresh start groups -> database_rank_groups_unique groups ->
  forall n m f h first second d e g j k,
    nth_error sl n = Some (f, first) ->
    nth_error sl m = Some (h, second) ->
    nth_error (database_rank_slots_from kinds start groups sl) n = Some (d, g, j) ->
    nth_error (database_rank_slots_from kinds start groups sl) m = Some (e, g, k) ->
    f = h.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups Hfresh Hunique n m f h first second d e g j k
      Hslot_f Hslot_h Hrank_f Hrank_h;
    destruct n as [|n]; destruct m as [|m];
    cbn [nth_error database_rank_slots_from] in *; try discriminate.
  - injection Hslot_f as <- <-. injection Hslot_h as <- <-. reflexivity.
  - injection Hslot_f as <- <-.
    set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head
      (fst place, N.succ (snd place)) groups).
    assert (Howner : PTrieCode.get head updated = Some (g, N.succ (snd place))).
    { unfold updated, place. rewrite PTrie.get_set_same.
      injection Hrank_f as _ Hgroup _. now rewrite Hgroup. }
    symmetry. eapply database_rank_slots_from_owner with
      (start := N.succ start) (groups := updated) (j := N.succ (snd place))
      (n := m) (perm := second) (d := e) (offset := k).
    + unfold updated, place. now apply database_rank_groups_fresh_step.
    + unfold updated, place. now apply database_rank_groups_unique_step.
    + exact Howner.
    + exact Hslot_h.
    + exact Hrank_h.
  - injection Hslot_h as <- <-.
    set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head
      (fst place, N.succ (snd place)) groups).
    assert (Howner : PTrieCode.get head updated = Some (g, N.succ (snd place))).
    { unfold updated, place. rewrite PTrie.get_set_same.
      injection Hrank_h as _ Hgroup _. now rewrite Hgroup. }
    eapply database_rank_slots_from_owner with
      (start := N.succ start) (groups := updated) (j := N.succ (snd place))
      (n := n) (perm := first) (d := d) (offset := j).
    + unfold updated, place. now apply database_rank_groups_fresh_step.
    + unfold updated, place. now apply database_rank_groups_unique_step.
    + exact Howner.
    + exact Hslot_f.
    + exact Hrank_f.
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head
      (fst place, N.succ (snd place)) groups).
    eapply IH with (start := N.succ start) (groups := updated);
      [unfold updated, place; now apply database_rank_groups_fresh_step |
       unfold updated, place; now apply database_rank_groups_unique_step |
       exact Hslot_f | exact Hslot_h | exact Hrank_f | exact Hrank_h].
Qed.

Lemma database_rank_slots_from_current_rank : forall kinds start groups sl f g j,
  PTrieCode.get f groups = Some (g, j) ->
  forall n perm d rank offset,
    nth_error sl n = Some (f, perm) ->
    nth_error (database_rank_slots_from kinds start groups sl) n =
      Some (d, rank, offset) -> rank = g.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups f g j Hcurrent n perm d rank offset Hslot Hplace;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from] in Hslot, Hplace;
    try discriminate.
  - injection Hslot as <- <-. rewrite Hcurrent in Hplace.
    injection Hplace as _ Hrank _. symmetry. exact Hrank.
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    assert (Hupdated : exists count, PTrieCode.get f updated = Some (g, count)).
    { destruct (Pos.eq_dec f head) as [-> | Hne].
      - exists (N.succ j). unfold updated, place.
        rewrite PTrie.get_set_same, Hcurrent. reflexivity.
      - exists j. unfold updated.
        rewrite PTrie.get_set_other by exact Hne. exact Hcurrent. }
    destruct Hupdated as [count Hupdated].
    eapply IH; eassumption.
Qed.

Lemma database_rank_slots_from_same_function : forall kinds start groups sl,
  forall n m f first second d e g rank j k,
    nth_error sl n = Some (f, first) ->
    nth_error sl m = Some (f, second) ->
    nth_error (database_rank_slots_from kinds start groups sl) n = Some (d, g, j) ->
    nth_error (database_rank_slots_from kinds start groups sl) m = Some (e, rank, k) ->
    g = rank.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups n m f first second d e g rank j k
      Hslot_first Hslot_second Hrank_first Hrank_second;
    destruct n as [|n]; destruct m as [|m];
    cbn [nth_error database_rank_slots_from] in *; try discriminate.
  - injection Hrank_first as _ Hrank_a _.
    injection Hrank_second as _ Hrank_b _. congruence.
  - injection Hslot_first as <- <-.
    set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    assert (Hcurrent : PTrieCode.get head updated = Some (g, N.succ (snd place))).
    { unfold updated, place. rewrite PTrie.get_set_same.
      injection Hrank_first as _ Hgroup _. now rewrite Hgroup. }
    symmetry. eapply database_rank_slots_from_current_rank with
      (start := N.succ start) (groups := updated) (j := N.succ (snd place))
      (n := m) (perm := second) (d := e) (offset := k);
      [exact Hcurrent | exact Hslot_second | exact Hrank_second].
  - injection Hslot_second as <- <-.
    set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    assert (Hcurrent : PTrieCode.get head updated = Some (rank, N.succ (snd place))).
    { unfold updated, place. rewrite PTrie.get_set_same.
      injection Hrank_second as _ Hgroup _. now rewrite Hgroup. }
    eapply database_rank_slots_from_current_rank with
      (start := N.succ start) (groups := updated) (j := N.succ (snd place))
      (n := n) (perm := first) (d := d) (offset := j);
      [exact Hcurrent | exact Hslot_first | exact Hrank_first].
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    eapply IH with (start := N.succ start) (groups := updated);
      [exact Hslot_first | exact Hslot_second | exact Hrank_first | exact Hrank_second].
Qed.

Lemma database_rank_slots_from_bound : forall kinds start groups sl,
  database_rank_groups_bounded start groups ->
  forall n d g j, nth_error (database_rank_slots_from kinds start groups sl) n =
    Some (d, g, j) ->
    (g <= start + N.of_nat n)%N /\ (j <= start + N.of_nat n)%N.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[f perm] rest IH]; intros start groups Hbounded n d g j Hentry;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from] in Hentry;
    try discriminate.
  - destruct (PTrieCode.get f groups) as [[rank offset] |] eqn:Hprior.
    + injection Hentry as <- <- <-. cbn [fst snd].
      destruct (Hbounded f rank offset Hprior). lia.
    + injection Hentry as <- <- <-. cbn [fst snd]. lia.
  - specialize (IH (N.succ start)
      (PTrieCode.set f
        (fst (match PTrieCode.get f groups with Some p => p | None => (start, 0%N) end),
         N.succ (snd (match PTrieCode.get f groups with
           Some p => p | None => (start, 0%N) end))) groups)).
    specialize (IH (database_rank_groups_bounded_step start groups f Hbounded)).
    specialize (IH n d g j Hentry). rewrite Nat2N.inj_succ. lia.
Qed.

Definition database_rank_offset (groups : PTrieCode.t (N * N)) (f : positive) : N :=
  match PTrieCode.get f groups with Some (_, j) => j | None => 0%N end.

Lemma database_rank_offset_step : forall groups head start f,
  let place := match PTrieCode.get head groups with
    | Some position => position | None => (start, 0%N) end in
  database_rank_offset
    (PTrieCode.set head (fst place, N.succ (snd place)) groups) f =
    if Pos.eqb head f then N.succ (database_rank_offset groups f)
    else database_rank_offset groups f.
Proof.
  intros groups head start f place.
  unfold database_rank_offset.
  destruct (Pos.eq_dec head f) as [-> | Hne].
  - rewrite Pos.eqb_refl, PTrie.get_set_same.
    unfold place. destruct (PTrieCode.get f groups) as [[rank offset] |]; reflexivity.
  - assert (Htest : Pos.eqb head f = false) by (apply Pos.eqb_neq; exact Hne).
    rewrite Htest, PTrie.get_set_other by congruence. reflexivity.
Qed.

Definition database_slot_count (f : positive) (sl : list (positive * list nat)) : nat :=
  length (filter (fun slot => Pos.eqb (fst slot) f) sl).

Lemma database_slot_count_snoc : forall f prefix head layout,
  database_slot_count f (prefix ++ [(head, layout)]) =
    if Pos.eqb head f then S (database_slot_count f prefix)
    else database_slot_count f prefix.
Proof.
  intros f prefix head layout. unfold database_slot_count.
  rewrite filter_app, length_app. cbn [filter length fst].
  destruct (Pos.eqb head f) eqn:Hsame; cbn; lia.
Qed.

Lemma database_rank_slots_from_offset : forall kinds start groups sl prefix,
  (forall f, database_rank_offset groups f = N.of_nat (database_slot_count f prefix)) ->
  forall n f perm d g j,
    nth_error sl n = Some (f, perm) ->
    nth_error (database_rank_slots_from kinds start groups sl) n = Some (d, g, j) ->
    j = N.of_nat (database_slot_count f (prefix ++ firstn n sl)).
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups prefix Hcount n f perm d g j Hslot Hrank;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from firstn] in *;
    try discriminate.
  - injection Hslot as <- <-. injection Hrank as _ _ Hoffset.
    rewrite app_nil_r. rewrite <- (Hcount head).
    unfold database_rank_offset.
    destruct (PTrieCode.get head groups) as [[rank offset] |];
      cbn [fst snd] in Hoffset |- *; lia.
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    assert (Hcount_updated : forall name,
      database_rank_offset updated name =
        N.of_nat (database_slot_count name (prefix ++ [(head, layout)]))).
    { intro name. unfold updated, place.
      rewrite database_rank_offset_step, database_slot_count_snoc.
      rewrite Hcount. destruct (Pos.eqb head name); lia. }
    specialize (IH (N.succ start) updated (prefix ++ [(head, layout)])
      Hcount_updated n f perm d g j Hslot Hrank).
    rewrite <- app_assoc in IH. exact IH.
Qed.

Lemma database_rank_slots_select : forall kinds sl n m f h first second d e g rank j k,
  nth_error sl n = Some (f, first) -> nth_error sl m = Some (h, second) ->
  nth_error (database_rank_slots_from kinds 0%N PTrieCode.empty sl) n =
    Some (d, g, j) ->
  nth_error (database_rank_slots_from kinds 0%N PTrieCode.empty sl) m =
    Some (e, rank, k) ->
  andb (Bool.eqb e d) (N.eqb rank g) = Pos.eqb h f.
Proof.
  intros kinds sl n m f h first second d e g rank j k
    Hslot_f Hslot_h Hrank_f Hrank_h.
  destruct (Pos.eq_dec h f) as [-> | Hdifferent].
  - assert (Hsame_rank : rank = g).
    { symmetry. eapply database_rank_slots_from_same_function;
        [exact Hslot_f | exact Hslot_h | exact Hrank_f | exact Hrank_h]. }
    assert (Hflag_f : d = match PTrieCode.get f kinds with
      | Some _ => true | None => false end).
    { eapply database_rank_slots_from_flag with
        (start := 0%N) (groups := PTrieCode.empty) (sl := sl)
        (n := n) (perm := first) (g := g) (j := j); eassumption. }
    assert (Hflag_h : e = match PTrieCode.get f kinds with
      | Some _ => true | None => false end).
    { eapply database_rank_slots_from_flag with
        (start := 0%N) (groups := PTrieCode.empty) (sl := sl)
        (n := m) (perm := second) (g := rank) (j := k); eassumption. }
    subst rank. rewrite Hflag_f, Hflag_h, Pos.eqb_refl, N.eqb_refl.
    destruct (PTrieCode.get f kinds); reflexivity.
  - assert (Hdifferent_rank : rank <> g).
    { intro Hequal. subst rank. apply Hdifferent. symmetry.
      eapply database_rank_slots_from_same_rank;
        [apply database_rank_groups_fresh_empty |
         apply database_rank_groups_unique_empty |
         exact Hslot_f | exact Hslot_h | exact Hrank_f | exact Hrank_h]. }
    apply N.eqb_neq in Hdifferent_rank.
    assert (Hdifferent_name : Pos.eqb h f = false).
    { apply Pos.eqb_neq. exact Hdifferent. }
    rewrite Hdifferent_rank, Hdifferent_name. destruct (Bool.eqb e d); reflexivity.
Qed.

Lemma database_filter_count_agrees : forall (A B : Type) (left : list A) (right : list B)
    (select_left : A -> bool) (select_right : B -> bool),
  length left = length right ->
  (forall n a b, nth_error left n = Some a -> nth_error right n = Some b ->
    select_left a = select_right b) ->
  length (filter select_left left) = length (filter select_right right).
Proof.
  intros A B left. induction left as [|a rest IH];
    intros right select_left select_right Hlength Hpoint;
    destruct right as [|b tail]; cbn [length] in Hlength; try discriminate.
  - reflexivity.
  - assert (Hhead : select_left a = select_right b).
    { apply (Hpoint 0%nat); reflexivity. }
    cbn [filter length]. rewrite Hhead.
    destruct (select_right b); cbn [length].
    + f_equal. apply IH with (right := tail); [lia |].
      intros n x y Hleft Hright. apply (Hpoint (S n)); assumption.
    + apply IH with (right := tail); [lia |].
      intros n x y Hleft Hright. apply (Hpoint (S n)); assumption.
Qed.

Fixpoint database_rank_credit (universe : list positive)
    (groups : PTrieCode.t (N * N)) : N :=
  match universe with
  | [] => 0%N
  | f :: rest =>
    (database_counter_credit (database_rank_offset groups f) +
      database_rank_credit rest groups)%N
  end.

Fixpoint database_rank_final (s : N) (groups : PTrieCode.t (N * N))
    (sl : list (positive * list nat)) : PTrieCode.t (N * N) :=
  match sl with
  | [] => groups
  | (f, _) :: rest =>
    let place := match PTrieCode.get f groups with
      | Some position => position | None => (s, 0%N) end in
    database_rank_final (N.succ s)
      (PTrieCode.set f (fst place, N.succ (snd place)) groups) rest
  end.

Lemma database_rank_credit_other : forall universe groups f value,
  ~ In f universe ->
  database_rank_credit universe (PTrieCode.set f value groups) =
    database_rank_credit universe groups.
Proof.
  intros universe. induction universe as [|g rest IH]; intros groups f value Hnot.
  - reflexivity.
  - cbn [database_rank_credit] in *. assert (Hdifferent : g <> f).
    { intro Heq. apply Hnot. now left. }
    unfold database_rank_offset at 1 2.
    rewrite PTrie.get_set_other by exact Hdifferent.
    f_equal. apply IH. intro Hin. apply Hnot. now right.
Qed.

Lemma database_rank_credit_step : forall universe groups f rank,
  NoDup universe -> In f universe ->
  let offset := database_rank_offset groups f in
  (database_rank_credit universe
      (PTrieCode.set f (rank, N.succ offset) groups) +
    database_counter_credit offset =
    database_rank_credit universe groups +
      database_counter_credit (N.succ offset))%N.
Proof.
  intro universe. induction universe as [|g rest IH]; intros groups f rank Hnodup Hin.
  - contradiction.
  - inversion Hnodup as [|? ? Hnot Htail]; subst.
    destruct Hin as [Heq | Hin].
    + subst g. cbn [database_rank_credit].
      unfold database_rank_offset at 1 3.
      rewrite PTrie.get_set_same.
      rewrite database_rank_credit_other by exact Hnot. cbn [snd]. lia.
    + cbn [database_rank_credit].
      assert (Hdifferent : g <> f) by (intro Heq; subst; contradiction).
      unfold database_rank_offset at 1 2.
      rewrite PTrie.get_set_other by exact Hdifferent.
      specialize (IH groups f rank Htail Hin).
      change (database_rank_credit rest
        (PTrieCode.set f (rank, N.succ (database_rank_offset groups f)) groups) +
        database_counter_credit (database_rank_offset groups f) =
        database_rank_credit rest groups +
        database_counter_credit (N.succ (database_rank_offset groups f)))%N in IH.
      change (database_counter_credit (database_rank_offset groups g) +
        database_rank_credit rest
          (PTrieCode.set f (rank, N.succ (database_rank_offset groups f)) groups) +
        database_counter_credit (database_rank_offset groups f) =
        database_counter_credit (database_rank_offset groups g) +
        database_rank_credit rest groups +
        database_counter_credit (N.succ (database_rank_offset groups f)))%N.
      lia.
Qed.

Lemma T_database_rank_slots_from_amort : forall kinds universe sl s groups,
  NoDup universe -> (forall x, In x (map fst sl) -> In x universe) ->
  (T_database_rank_slots_from kinds s groups sl +
    database_counter_credit (s + N.of_nat (length sl)) +
    database_rank_credit universe (database_rank_final s groups sl) <=
    32 * (PTrieT.c_trie + 1) *
      N.of_nat (length sl +
        fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat sl + 1)%nat +
      database_counter_credit s + database_rank_credit universe groups)%N.
Proof.
  intros kinds universe sl. induction sl as [|[f perm] rest IH];
    intros s groups Hnodup Hcover.
  - time_unfold T_database_rank_slots_from. cbn [length fold_right map
      database_rank_final]. cbn [N.of_nat Nat.add].
    cbn [Pos.of_succ_nat]. rewrite !N.add_0_r.
    rewrite N.mul_1_r.
    assert (1 <= 32 * (PTrieT.c_trie + 1))%N.
    { rewrite N.mul_add_distr_l. lia. }
    set (global := database_counter_credit s).
    set (credit := database_rank_credit universe groups).
    clearbody global credit.
    lia.
  - set (place := match PTrieCode.get f groups with
      | Some position => position | None => (s, 0%N) end).
    set (updated := PTrieCode.set f (fst place, N.succ (snd place)) groups).
    pose proof (IH (N.succ s) updated Hnodup) as Htail.
    assert (Htailcover : forall x, In x (map fst rest) -> In x universe).
    { intros x Hin. apply Hcover. cbn [map In]. now right. }
    specialize (Htail Htailcover).
    assert (Hmember : In f universe).
    { apply Hcover. cbn [map In]. now left. }
    pose proof (PTrieT.T_get_le output f kinds) as Hkind.
    pose proof (PTrieT.T_get_le (N * N) f groups) as Hget.
    pose proof (PTrieT.T_set_le (N * N) f
      (fst place, N.succ (snd place)) groups) as Hset.
    pose proof (database_counter_succ_amort s) as Hglobal.
    pose proof (database_counter_succ_amort (snd place)) as Hlocal.
    assert (Hoffset : snd place = database_rank_offset groups f).
    { unfold place, database_rank_offset. destruct (PTrieCode.get f groups) as [[a b] |];
        reflexivity. }
    rewrite Hoffset in Hlocal.
    pose proof (database_rank_credit_step universe groups f (fst place)
      Hnodup Hmember) as Hcredit.
    cbn beta in Hcredit. fold updated in Hcredit.
    assert (Hfinish : (s + N.of_nat (length ((f, perm) :: rest)))%N =
      (N.succ s + N.of_nat (length rest))%N) by (cbn [length]; lia).
    assert (Hmass : N.of_nat (length ((f, perm) :: rest) +
        fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat
          ((f, perm) :: rest) + 1)%nat =
      (N.of_nat (length rest +
        fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat rest + 1)%nat +
        N.of_nat (Pos.size_nat f + 1))%N).
    { cbn [length fold_right fst]. repeat rewrite Nat2N.inj_add. lia. }
    cbv zeta in Hcredit.
    assert (Hcredit' : (database_rank_credit universe updated +
      database_counter_credit (database_rank_offset groups f) =
      database_rank_credit universe groups +
      database_counter_credit (N.succ (database_rank_offset groups f)))%N).
    { unfold updated. rewrite Hoffset. exact Hcredit. }
    rewrite Hmass.
    rewrite Hfinish. time_unfold T_database_rank_slots_from.
    fold place updated. cbn [database_rank_final].
    replace (PTrieCode.set f
      (fst (match PTrieCode.get f groups with Some position => position | None => (s, 0%N) end),
       N.succ (snd (match PTrieCode.get f groups with
         Some position => position | None => (s, 0%N) end))) groups)
      with updated by reflexivity.
    unfold Datatypes.T_fst, Datatypes.T_snd. cbn beta zeta.
    rewrite Hoffset.
    set (trie_cost := PTrieT.c_trie) in *.
    set (bits := N.of_nat (Pos.size_nat f + 1)) in *.
    set (tailmass := N.of_nat (length rest +
      fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat rest + 1)%nat) in *.
    assert (Hbits : (1 <= bits)%N) by (unfold bits; lia).
    assert (Hbudget_step : (32 * (trie_cost + 1) * tailmass +
      3 * trie_cost * bits + 16 <=
      32 * (trie_cost + 1) * (tailmass + bits))%N).
    { rewrite N.mul_add_distr_l. nia. }
    assert (Hlocalpay : (N.T_succ (database_rank_offset groups f) +
      database_rank_credit universe updated <=
      3 + database_rank_credit universe groups)%N) by lia.
    change (PTrieCode.T_get f kinds <= trie_cost * bits)%N in Hkind.
    change (PTrieCode.T_get f groups <= trie_cost * bits)%N in Hget.
    assert (Hset' : (PTrieCode.T_set f (fst place,
      N.succ (database_rank_offset groups f)) groups <= trie_cost * bits)%N).
    { rewrite <- Hoffset. exact Hset. }
    lia.
Qed.

(** Initial ranking has no per-function carry debt. *)
Lemma database_rank_credit_empty : forall universe,
  database_rank_credit universe (PTrieCode.empty : PTrieCode.t (N * N)) = 0%N.
Proof.
  intro universe. induction universe as [|f rest IH]; [reflexivity |].
  cbn [database_rank_credit]. unfold database_rank_offset.
  rewrite PTrie.get_empty, IH. reflexivity.
Qed.

(** A declared function inherits the group of its first ranked slot. *)
Fixpoint database_group_of (f : positive) (sl : list (positive * list nat))
    (positions : list (bool * N * N)) : option N :=
  match sl, positions with
  | (g, _) :: rest, (true, rank, _) :: places =>
    if Pos.eqb f g then Some rank else database_group_of f rest places
  | _ :: rest, _ :: places => database_group_of f rest places
  | _, _ => None
  end.

Lemma database_group_of_witness : forall f sl positions g,
  database_group_of f sl positions = Some g ->
  exists n perm offset, nth_error sl n = Some (f, perm) /\
    nth_error positions n = Some (true, g, offset).
Proof.
  intros f sl. induction sl as [|[head layout] rest IH];
    intros positions g Hgroup; destruct positions as [|[[flag rank] offset] tail];
    cbn [database_group_of] in Hgroup; try discriminate.
  destruct flag.
  - destruct (Pos.eqb f head) eqn:Hsame.
    + apply Pos.eqb_eq in Hsame. subst head. injection Hgroup as <-.
      exists 0%nat, layout, offset. split; reflexivity.
    + destruct (IH tail g Hgroup) as [n [perm [j [Hslot Hposition]]]].
      exists (S n), perm, j. split; [exact Hslot | exact Hposition].
  - destruct (IH tail g Hgroup) as [n [perm [j [Hslot Hposition]]]].
    exists (S n), perm, j. split; [exact Hslot | exact Hposition].
Qed.

Lemma database_group_of_ranked : forall kinds start groups sl n f perm g j,
  nth_error sl n = Some (f, perm) ->
  nth_error (database_rank_slots_from kinds start groups sl) n = Some (true, g, j) ->
  database_group_of f sl (database_rank_slots_from kinds start groups sl) = Some g.
Proof.
  intros kinds start groups sl. revert start groups.
  induction sl as [|[head layout] rest IH];
    intros start groups n f perm g j Hslot Hrank;
    destruct n as [|n]; cbn [nth_error database_rank_slots_from] in Hslot, Hrank;
    try discriminate.
  - injection Hslot as <- <-.
    destruct (PTrieCode.get head kinds) eqn:Hkind; cbn [database_rank_slots_from] in Hrank;
      try discriminate.
    inversion Hrank; subst. cbn [database_group_of database_rank_slots_from].
    now rewrite Hkind, Pos.eqb_refl.
  - set (place := match PTrieCode.get head groups with
      | Some position => position | None => (start, 0%N) end).
    set (updated := PTrieCode.set head (fst place, N.succ (snd place)) groups).
    destruct (Pos.eq_dec f head) as [-> | Hne].
    + assert (Hdecl : PTrieCode.get head kinds <> None).
      { intro Hnone. pose proof (database_rank_slots_from_flag kinds
          (N.succ start) updated rest n head perm true g j Hslot Hrank) as Hflag.
        rewrite Hnone in Hflag. discriminate. }
      destruct (PTrieCode.get head kinds) eqn:Hkind; [|contradiction].
      assert (Hsame : fst place = g).
      { eapply database_rank_slots_from_same_function with
          (kinds := kinds) (start := start) (groups := groups) (sl := (head, layout) :: rest)
          (n := 0%nat) (m := S n) (f := head) (first := layout) (second := perm)
          (d := true) (e := true) (j := snd place) (k := j);
          [reflexivity | exact Hslot | | exact Hrank].
        cbn [nth_error database_rank_slots_from]. now rewrite Hkind. }
      cbn [database_group_of database_rank_slots_from].
      rewrite Hkind, Pos.eqb_refl. unfold place in Hsame. now rewrite Hsame.
    + assert (Hdifferent : Pos.eqb f head = false).
      { apply Pos.eqb_neq. exact Hne. }
      cbn [database_group_of].
      destruct (PTrieCode.get head kinds) eqn:Hkind;
        cbn [database_rank_slots_from database_group_of];
        rewrite Hkind.
      * rewrite Hdifferent. eapply IH; eassumption.
      * eapply IH; eassumption.
Qed.

(** A group's stored slots are listed in their original slot order. *)
Fixpoint database_group_slots (s : N) (d : bool) (g : N)
    (positions : list (bool * N * N)) : list N :=
  match positions with
  | [] => []
  | (flag, rank, _) :: rest =>
    let tail := database_group_slots (N.succ s) d g rest in
    if andb (Bool.eqb flag d) (N.eqb rank g) then s :: tail else tail
  end.

Lemma database_group_slots_lower : forall positions s d g x,
  In x (database_group_slots s d g positions) -> (s <= x)%N.
Proof.
  induction positions as [|[[flag rank] offset] rest IH];
    intros s d g x Hmember; cbn [database_group_slots] in Hmember;
    [contradiction |].
  destruct (andb (Bool.eqb flag d) (N.eqb rank g)) eqn:Hselect.
  - destruct Hmember as [-> | Htail]; [lia |].
    specialize (IH (N.succ s) d g x Htail). lia.
  - specialize (IH (N.succ s) d g x Hmember). lia.
Qed.

Lemma database_group_slots_nodup : forall positions s d g,
  NoDup (database_group_slots s d g positions).
Proof.
  induction positions as [|[[flag rank] offset] rest IH];
    intros s d g; cbn [database_group_slots]; [constructor |].
  destruct (andb (Bool.eqb flag d) (N.eqb rank g)) eqn:Hselect;
    [| apply IH].
  constructor; [| apply IH].
  intro Hmember. pose proof (database_group_slots_lower rest (N.succ s) d g s Hmember).
  lia.
Qed.

Lemma database_group_slots_member : forall positions start d g s,
  In s (database_group_slots start d g positions) <->
    exists n offset, nth_error positions n = Some (d, g, offset) /\
      s = (start + N.of_nat n)%N.
Proof.
  induction positions as [|[[flag rank] offset] rest IH];
    intros start d g s; cbn [database_group_slots].
  - split; [intros [] |]. intros [n [o [Hentry _]]]. destruct n; discriminate.
  - destruct (andb (Bool.eqb flag d) (N.eqb rank g)) eqn:Hselect.
    + apply andb_true_iff in Hselect as [Hflag Hrank].
      assert (Hflag_eq : flag = d).
      { destruct flag, d; cbn in Hflag; try discriminate; reflexivity. }
      apply N.eqb_eq in Hrank. subst d g. split.
      * intros [-> | Htail].
        -- exists 0%nat, offset. split; [reflexivity | lia].
        -- apply IH in Htail as [n [o [Hentry Hnumber]]].
           exists (S n), o. split; [exact Hentry |].
           rewrite Nat2N.inj_succ. lia.
      * intros [n [o [Hentry Hnumber]]]. destruct n as [|n].
        -- cbn [nth_error] in Hentry. injection Hentry as <-.
           left. cbn [N.of_nat] in Hnumber. lia.
        -- right. apply IH. exists n, o. split; [exact Hentry |].
           rewrite Nat2N.inj_succ in Hnumber. lia.
    + split.
      * intro Htail. apply IH in Htail as [n [o [Hentry Hnumber]]].
        exists (S n), o. split; [exact Hentry |].
        rewrite Nat2N.inj_succ. lia.
      * intros [n [o [Hentry Hnumber]]]. destruct n as [|n].
        -- cbn [nth_error] in Hentry. injection Hentry as Hflag Hrank _.
           assert (Htrue : andb (Bool.eqb flag d) (N.eqb rank g) = true).
           { apply andb_true_iff. split.
             - destruct flag, d; cbn in Hflag |- *; try discriminate; reflexivity.
             - apply N.eqb_eq. congruence. }
           congruence.
        -- apply IH. exists n, o. split; [exact Hentry |].
           rewrite Nat2N.inj_succ in Hnumber. lia.
Qed.

Lemma database_group_slots_app : forall first second start d g,
  database_group_slots start d g (first ++ second) =
    database_group_slots start d g first ++
      database_group_slots (start + N.of_nat (length first)) d g second.
Proof.
  induction first as [|[[flag rank] offset] rest IH];
    intros second start d g; cbn [app database_group_slots length].
  - now rewrite N.add_0_r.
  - rewrite IH. rewrite Nat2N.inj_succ.
    replace (N.succ start + N.of_nat (length rest))%N with
      (start + N.succ (N.of_nat (length rest)))%N by lia.
    destruct (andb (Bool.eqb flag d) (N.eqb rank g)); reflexivity.
Qed.

Lemma database_group_slots_nth : forall positions n d g offset,
  nth_error positions n = Some (d, g, offset) ->
  nth_error (database_group_slots 0%N d g positions)
    (length (database_group_slots 0%N d g (firstn n positions))) =
    Some (N.of_nat n).
Proof.
  intros positions n d g offset Hposition.
  assert (Hbelow : n < length positions).
  { apply nth_error_Some. congruence. }
  rewrite <- (firstn_skipn n positions) at 1.
  rewrite database_group_slots_app.
  rewrite nth_error_app2 by lia.
  replace (length (database_group_slots 0 d g (firstn n positions)) -
    length (database_group_slots 0 d g (firstn n positions))) with 0%nat by lia.
  rewrite firstn_length_le by lia.
  assert (Hhead : nth_error (skipn n positions) 0 = Some (d, g, offset)).
  { rewrite nth_error_skipn, Nat.add_0_r. exact Hposition. }
  destruct (skipn n positions) as [|[[flag rank] value] rest] eqn:Hskip;
    cbn [nth_error] in Hhead; [discriminate |].
  injection Hhead as <- <- <-.
  cbn [database_group_slots nth_error].
  destruct flag; cbn [Bool.eqb]; rewrite N.eqb_refl; cbn [andb nth_error].
  all: now rewrite N.add_0_l.
Qed.

Lemma database_group_slots_count : forall positions start d g,
  length (database_group_slots start d g positions) =
    length (filter (fun place =>
      andb (Bool.eqb (fst (fst place)) d) (N.eqb (snd (fst place)) g)) positions).
Proof.
  induction positions as [|[[flag rank] offset] rest IH];
    intros start d g; cbn [database_group_slots filter length fst snd];
    [reflexivity |].
  destruct (andb (Bool.eqb flag d) (N.eqb rank g));
    cbn [length]; rewrite IH; reflexivity.
Qed.

Lemma database_ranked_prefix_count : forall kinds sl n f perm d g j,
  nth_error sl n = Some (f, perm) ->
  nth_error (database_rank_slots_from kinds 0%N PTrieCode.empty sl) n =
    Some (d, g, j) ->
  length (database_group_slots 0%N d g
    (firstn n (database_rank_slots_from kinds 0%N PTrieCode.empty sl))) =
    database_slot_count f (firstn n sl).
Proof.
  intros kinds sl n f perm d g j Hslot Hrank.
  rewrite database_group_slots_count. unfold database_slot_count.
  apply database_filter_count_agrees.
  - rewrite !length_firstn, database_rank_slots_from_length. reflexivity.
  - intros m [[flag rank] offset] [h other] Hprefix_place Hprefix_slot.
    rewrite nth_error_firstn in Hprefix_slot, Hprefix_place.
    destruct (m <? n)%nat; [| discriminate].
    eapply database_rank_slots_select;
      [exact Hslot | exact Hprefix_slot | exact Hrank | exact Hprefix_place].
Qed.

(** A maximum comparison reads no more bits than its current declaration name. *)
Lemma T_database_positive_max_le : forall p q,
  (Pos.T_max p q <= N.of_nat (Pos.size_nat p) + 2)%N.
Proof.
  intros p q. time_step Pos.max.
Qed.

(** The declaration trie pays once for each declaration and each name bit. *)
Lemma T_database_kinds_le : forall ds,
  (T_database_kinds ds <= 8 * (PTrieT.c_trie + 1) *
    N.of_nat (length ds + fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds + 1))%N.
Proof.
  intro ds. induction ds as [|d ds IH].
  - time_step database_kinds; time_step.
  - pose proof (PTrieT.T_set_le output (name d) (out d) (database_kinds ds)) as Hset.
    unfold database_kinds in Hset. unfold T_database_kinds in IH.
    time_unfold T_database_kinds. time_unfold List.T_fold_right.
    revert IH. time_simpl. intro IH. time_cbn_all.
    set (trie_cost := PTrieT.c_trie) in *. clearbody trie_cost. nia.
Qed.

(** The ranking clock pays once for each declaration and named slot. *)
Lemma T_database_rank_slots_budget : forall ds sl,
  (T_database_rank_slots ds sl <=
    48 * (PTrieT.c_trie + 1) *
      N.of_nat (length ds + length sl +
        fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds +
        fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat sl + 1)%nat)%N.
Proof.
  intros ds sl.
  set (universe := nodup Pos.eq_dec (map fst sl)).
  pose proof (T_database_rank_slots_from_amort (database_kinds ds) universe sl 0%N
    PTrieCode.empty (NoDup_nodup Pos.eq_dec (map fst sl))) as Hrank.
  assert (Hcover : forall x, In x (map fst sl) -> In x universe).
  { intros x Hin. unfold universe. now apply nodup_In. }
  specialize (Hrank Hcover).
  rewrite database_rank_credit_empty in Hrank.
  cbn [database_counter_credit] in Hrank.
  pose proof (T_database_kinds_le ds) as Hkinds.
  time_unfold T_database_rank_slots.
  set (cost := (PTrieT.c_trie + 1)%N) in *.
  set (slotamount := N.of_nat (length sl +
    fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat sl + 1)%nat) in *.
  set (declamount := N.of_nat (length ds +
    fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds + 1)%nat) in *.
  set (total := N.of_nat (length ds + length sl +
    fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds +
    fold_right (fun x n => (Pos.size_nat (fst x) + n)%nat) 0%nat sl + 1)%nat) in *.
  assert (Hslot : (slotamount <= total)%N) by (unfold slotamount, total; lia).
  assert (Hdecl : (declamount <= total)%N) by (unfold declamount, total; lia).
  assert (Htotal : (1 <= total)%N) by (unfold total; lia).
  assert (Hcost : (1 <= cost)%N) by (unfold cost; lia).
  assert (Hrank' : (T_database_rank_slots_from (database_kinds ds) 0%N
      PTrieCode.empty sl <= 32 * cost * slotamount)%N) by lia.
  assert (Hslots_budget : (32 * cost * slotamount <= 32 * cost * total)%N).
  { apply N.mul_le_mono_l. exact Hslot. }
  assert (Hdecl_budget : (8 * cost * declamount <= 8 * cost * total)%N).
  { apply N.mul_le_mono_l. exact Hdecl. }
  nia.
Qed.

(** The declaration maximum charges the bit length of each name independently. *)
Lemma T_database_max_name_le : forall ds,
  (T_database_max_name ds <=
    8 * N.of_nat (length ds + fold_right (fun d n => (Pos.size_nat (name d) + n)%nat) 0%nat ds + 1))%N.
Proof.
  intro ds. induction ds as [|d ds IH].
  - time_step database_max_name; time_step.
  - pose proof (T_database_positive_max_le (name d) (database_max_name ds)) as Hmax.
    unfold database_max_name in Hmax. unfold T_database_max_name in IH.
    time_unfold T_database_max_name. time_unfold List.T_fold_right.
    revert IH. time_simpl. intro IH. time_cbn_all. lia.
Qed.

(** Dense grouping releases the carry credit accumulated by earlier slot numbers. *)
Lemma T_database_slot_groups_amort : forall prepared next groups,
  (T_database_slot_groups next prepared groups +
    database_counter_credit (next + N.of_nat (length prepared)) <=
    8 * (PTrieT.c_trie + 1) *
      N.of_nat (length prepared +
        fold_right (fun s n => (Pos.size_nat (fst s) + n)%nat) 0%nat prepared + 1) +
    database_counter_credit next)%N.
Proof.
  intro prepared. induction prepared as [|[f layout] rest IH]; intros next groups.
  - time_unfold T_database_slot_groups. cbn [length fold_right].
    rewrite !N.add_0_r. cbn [N.of_nat Nat.add]. rewrite N.mul_1_r.
    set (trie_cost := PTrieT.c_trie). clearbody trie_cost. lia.
  - set (previous := match PTrieCode.get f groups with Some slots => slots | None => [] end).
    pose proof (IH (N.succ next) (PTrieCode.set f ((next, layout) :: previous) groups)) as Htail.
    pose proof (PTrieT.T_get_le (list (N * database_slot_layout)) f groups) as Hget.
    pose proof (PTrieT.T_set_le (list (N * database_slot_layout)) f
      ((next, layout) :: previous) groups) as Hset.
    pose proof (database_counter_succ_amort next) as Hcarry.
    assert (Hfinish : (next + N.of_nat (length ((f, layout) :: rest)))%N =
      (N.succ next + N.of_nat (length rest))%N) by (cbn [length]; lia).
    rewrite Hfinish. time_unfold T_database_slot_groups. fold previous.
    cbn [length fold_right fst].
    set (trie_cost := PTrieT.c_trie) in *. clearbody trie_cost.
    time_cbn. nia.
Qed.

(** Numbering from zero has no initial carry debt. *)
Lemma T_database_slot_groups_le : forall prepared groups,
  (T_database_slot_groups 0 prepared groups <= 8 * (PTrieT.c_trie + 1) *
    N.of_nat (length prepared +
      fold_right (fun s n => (Pos.size_nat (fst s) + n)%nat) 0%nat prepared + 1))%N.
Proof.
  intros prepared groups. pose proof (T_database_slot_groups_amort prepared 0 groups).
  cbn [database_counter_credit] in H. lia.
Qed.

(** The largest declaration name fits within the sum of all name widths and the root bit. *)
Lemma database_max_name_bits : forall ds,
  Pos.size_nat (database_max_name ds) <=
    fold_right (fun d n => Pos.size_nat (name d) + n) 0 ds + 1.
Proof.
  intro ds. induction ds as [|d ds IH]; [reflexivity |].
  change (Pos.size_nat (Pos.max (name d) (database_max_name ds)) <=
    Pos.size_nat (name d) + fold_right (fun d n => Pos.size_nat (name d) + n) 0 ds + 1).
  unfold Pos.max. destruct (Pos.compare (name d) (database_max_name ds)); lia.
Qed.

(** A binary natural's bit width never exceeds its unary value. *)
Lemma database_counter_bits_value : forall n, N.size_nat n <= N.to_nat n.
Proof.
  intros [|p]; [reflexivity | apply slot_rank_bits_value].
Qed.

(** Binary maximum pays only the bit width of its first argument. *)
Lemma T_database_counter_max_le : forall n m,
  (N.T_max n m <= N.of_nat (N.size_nat n) + 3)%N.
Proof.
  intros n m. time_step N.max.
Qed.

(** Preparing layouts preserves both the slot count and the charged function-name bits. *)
Lemma database_prepared_sizes : forall sl,
  length (prepare_slot_layouts sl) = length sl /\
  fold_right (fun s n => Pos.size_nat (fst s) + n) 0 (prepare_slot_layouts sl) =
    fold_right (fun s n => Pos.size_nat (fst s) + n) 0 sl.
Proof.
  intro sl. split.
  - unfold prepare_slot_layouts. apply length_map.
  - unfold prepare_slot_layouts.
    induction sl as [|[f perm] sl IH]; cbn [map fold_right fst];
      [reflexivity | now rewrite IH].
Qed.

(** Reading a missing function group gives its empty slot list. *)
Definition database_group_entries (f : positive)
    (groups : PTrieCode.t (list (N * database_slot_layout))) : list (N * database_slot_layout) :=
  match PTrieCode.get f groups with Some slots => slots | None => [] end.

(** A prepared list entry receives its offset from the starting slot number. *)
Definition database_slot_member (next : N) (prepared : list (positive * database_slot_layout))
    (f : positive) (s : N) (layout : database_slot_layout) : Prop :=
  exists n, nth_error prepared n = Some (f, layout) /\ s = (next + N.of_nat n)%N.

(** Prepending to one function group adds exactly its new numbered layout. *)
Lemma database_group_add_member : forall f g next block groups s layout,
  In (s, layout) (database_group_entries f
    (PTrieCode.set g ((next, block) :: database_group_entries g groups) groups)) <->
  In (s, layout) (database_group_entries f groups) \/
    (f = g /\ s = next /\ layout = block).
Proof.
  intros f g next block groups s layout. unfold database_group_entries.
  destruct (Pos.eq_dec f g) as [-> | Hdifferent].
  - rewrite PTrie.get_set_same. cbn [In]. intuition congruence.
  - rewrite PTrie.get_set_other by exact Hdifferent. intuition congruence.
Qed.

(** Numbering a nonempty prepared list separates its head from the incremented tail. *)
Lemma database_slot_member_cons : forall next g block rest f s layout,
  database_slot_member next ((g, block) :: rest) f s layout <->
    (f = g /\ s = next /\ layout = block) \/
    database_slot_member (N.succ next) rest f s layout.
Proof.
  intros next g block rest f s layout. unfold database_slot_member. split.
  - intros [n [Hentry Hslot]]. destruct n as [| n].
    + cbn [nth_error] in Hentry. injection Hentry as Hfunction Hlayout.
      left. split; [congruence |]. split; [cbn in Hslot; lia | congruence].
    + right. exists n. split; [exact Hentry |]. rewrite Nat2N.inj_succ in Hslot. lia.
  - intros [[-> [-> ->]] | [n [Hentry Hslot]]].
    + exists 0. split; [reflexivity | lia].
    + exists (S n). split; [exact Hentry |]. rewrite Nat2N.inj_succ. lia.
Qed.

(** Group construction adds exactly the numbered entries of the prepared input. *)
Lemma database_slot_groups_member : forall prepared next groups f s layout,
  In (s, layout) (database_group_entries f (database_slot_groups next prepared groups)) <->
    In (s, layout) (database_group_entries f groups) \/
      database_slot_member next prepared f s layout.
Proof.
  induction prepared as [| [g block] rest IH]; intros next groups f s layout.
  - cbn [database_slot_groups]. unfold database_slot_member. split.
    + intro Hin. now left.
    + intros [Hin | [n [Hentry _]]]; [exact Hin | destruct n; discriminate].
  - cbn [database_slot_groups]. fold (database_group_entries g groups).
    rewrite IH, database_group_add_member, database_slot_member_cons. tauto.
Qed.

(** A prepared function group contains exactly the declared slots at their global numbers. *)
Lemma database_prepared_group_member : forall sl f s layout,
  In (s, layout) (database_group_entries f
    (database_slot_groups 0 (prepare_slot_layouts sl) PTrieCode.empty)) <->
  exists perm, nth_error sl (N.to_nat s) = Some (f, perm) /\
    layout = prepare_slot_layout perm.
Proof.
  intros sl f s layout. rewrite database_slot_groups_member.
  unfold database_slot_member, prepare_slot_layouts.
  unfold database_group_entries at 1. rewrite PTrie.get_empty. cbn [In]. split.
  - intros [Hfalse | [n [Hentry Hslot]]]; [contradiction |].
    rewrite nth_error_map in Hentry.
    destruct (nth_error sl n) as [[g perm] |] eqn:Hnth; [| discriminate].
    cbn [option_map fst snd] in Hentry. injection Hentry as Hfunction Hlayout.
    subst g. exists perm. split; [| congruence].
    replace s with (N.of_nat n) by lia. now rewrite Nat2N.id.
  - intros [perm [Hentry ->]]. right. exists (N.to_nat s). split.
    + rewrite nth_error_map, Hentry. reflexivity.
    + rewrite N2Nat.id. lia.
Qed.

(** Existing group numbers are distinct and lie below the next number to allocate. *)
Definition database_groups_bounded (next : N)
    (groups : PTrieCode.t (list (N * database_slot_layout))) : Prop :=
  forall f, NoDup (map fst (database_group_entries f groups)) /\
    (forall s, In s (map fst (database_group_entries f groups)) -> (s < next)%N).

(** Numbering one fresh slot preserves distinctness in every function group. *)
Lemma database_groups_bounded_add : forall next groups g block,
  database_groups_bounded next groups ->
  database_groups_bounded (N.succ next)
    (PTrieCode.set g ((next, block) :: database_group_entries g groups) groups).
Proof.
  intros next groups g block Hbounded f. destruct (Pos.eq_dec f g) as [-> | Hdifferent].
  - destruct (Hbounded g) as [Hdistinct Hbelow].
    unfold database_group_entries at 1 3. rewrite !PTrie.get_set_same.
    cbn [map fst]. split.
    + constructor; [intro Hin; specialize (Hbelow next Hin); lia | exact Hdistinct].
    + intros s [-> | Hin]; [lia | specialize (Hbelow s Hin); lia].
  - destruct (Hbounded f) as [Hdistinct Hbelow].
    unfold database_group_entries at 1 3. rewrite !PTrie.get_set_other by exact Hdifferent.
    fold (database_group_entries f groups). split; [exact Hdistinct |].
    intros s Hin. specialize (Hbelow s Hin). lia.
Qed.

(** A complete group build preserves globally fresh slot numbering. *)
Lemma database_slot_groups_bounded : forall prepared next groups,
  database_groups_bounded next groups ->
  database_groups_bounded (next + N.of_nat (length prepared))
    (database_slot_groups next prepared groups).
Proof.
  induction prepared as [| [g block] rest IH]; intros next groups Hbounded.
  - cbn [database_slot_groups length]. now rewrite N.add_0_r.
  - cbn [database_slot_groups length]. fold (database_group_entries g groups).
    rewrite Nat2N.inj_succ.
    replace (next + N.succ (N.of_nat (length rest)))%N
      with (N.succ next + N.of_nat (length rest))%N by lia.
    apply IH. now apply database_groups_bounded_add.
Qed.

(** A function's prepared list visits each global slot number at most once. *)
Lemma database_prepared_group_nodup : forall sl f,
  NoDup (map fst (database_group_entries f
    (database_slot_groups 0 (prepare_slot_layouts sl) PTrieCode.empty))).
Proof.
  intros sl f. assert (Hempty : database_groups_bounded 0 PTrieCode.empty).
  { intro g. unfold database_group_entries. rewrite PTrie.get_empty.
    split; [constructor | intros s Hin; contradiction]. }
  exact (proj1 (database_slot_groups_bounded
    (prepare_slot_layouts sl) 0 PTrieCode.empty Hempty f)).
Qed.

(** Adding one prepared entry increases exactly its function's group length. *)
Lemma database_group_add_length : forall groups f g s layout,
  length (database_group_entries f
    (PTrieCode.set g ((s, layout) :: database_group_entries g groups) groups)) =
  if Pos.eqb g f then S (length (database_group_entries f groups))
  else length (database_group_entries f groups).
Proof.
  intros groups f g s layout. destruct (Pos.eq_dec f g) as [-> | Hdifferent].
  - rewrite Pos.eqb_refl. unfold database_group_entries at 1.
    now rewrite PTrie.get_set_same.
  - assert (Htest : Pos.eqb g f = false) by (apply Pos.eqb_neq; congruence).
    rewrite Htest. unfold database_group_entries at 1.
    now rewrite PTrie.get_set_other by exact Hdifferent.
Qed.

(** A grouping pass adds one entry for each matching function in its input. *)
Lemma database_slot_groups_length : forall prepared next groups f,
  length (database_group_entries f (database_slot_groups next prepared groups)) =
  length (database_group_entries f groups) +
    length (filter (fun item => Pos.eqb (fst item) f) prepared).
Proof.
  intro prepared. induction prepared as [|[g layout] rest IH]; intros next groups f.
  - cbn [database_slot_groups filter length]. lia.
  - cbn [database_slot_groups filter fst]. fold (database_group_entries g groups).
    rewrite IH, database_group_add_length. destruct (Pos.eqb g f); cbn [length]; lia.
Qed.

(** Preparing layouts preserves the exact number of slots belonging to each function. *)
Lemma database_prepared_group_length : forall sl f,
  length (database_group_entries f
    (database_slot_groups 0 (prepare_slot_layouts sl) PTrieCode.empty)) =
  length (filter (fun item => Pos.eqb (fst item) f) sl).
Proof.
  intros sl f. rewrite database_slot_groups_length.
  unfold database_group_entries at 1. rewrite PTrie.get_empty. cbn [length Nat.add].
  unfold prepare_slot_layouts.
  induction sl as [|[g perm] rest IH]; [reflexivity |].
  cbn [map filter fst].
  destruct (Pos.eqb g f); cbn [length]; now rewrite IH.
Qed.

Definition runtime_set_rows {C X} (rows : PTrieCode.t ((positive * list C) * option C))
    (state : database_runtime C X) : database_runtime C X :=
  DatabaseRuntime (runtime_allocated state) (runtime_changed state) (runtime_declarations state) (runtime_kinds state) rows
    (runtime_slots state) (runtime_equalities state) (runtime_queue state) (runtime_all_indexes state) (runtime_new_indexes state)
    (runtime_projection_counts state) (runtime_function_slots state) (runtime_max_name state) (runtime_slot_bound state).
TimeFun runtime_set_rows.

Definition runtime_set_changed {C X} (flag : bool)
    (state : database_runtime C X) : database_runtime C X :=
  DatabaseRuntime (runtime_allocated state) flag (runtime_declarations state) (runtime_kinds state) (runtime_rows state)
    (runtime_slots state) (runtime_equalities state) (runtime_queue state) (runtime_all_indexes state) (runtime_new_indexes state)
    (runtime_projection_counts state) (runtime_function_slots state) (runtime_max_name state) (runtime_slot_bound state).
TimeFun runtime_set_changed.

Definition runtime_set_allocated {C X} (allocated : N)
    (state : database_runtime C X) : database_runtime C X :=
  DatabaseRuntime allocated (runtime_changed state) (runtime_declarations state) (runtime_kinds state) (runtime_rows state)
    (runtime_slots state) (runtime_equalities state) (runtime_queue state) (runtime_all_indexes state) (runtime_new_indexes state)
    (runtime_projection_counts state) (runtime_function_slots state) (runtime_max_name state) (runtime_slot_bound state).
TimeFun runtime_set_allocated.

Definition runtime_set_union {C X} (flag : bool) (equalities : list (positive * positive)) (queue : list positive)
    (state : database_runtime C X) : database_runtime C X :=
  DatabaseRuntime (runtime_allocated state) flag (runtime_declarations state) (runtime_kinds state) (runtime_rows state)
    (runtime_slots state) equalities queue (runtime_all_indexes state) (runtime_new_indexes state)
    (runtime_projection_counts state) (runtime_function_slots state) (runtime_max_name state) (runtime_slot_bound state).
TimeFun runtime_set_union.

Definition runtime_set_indexes {C X} (all_indexes new_indexes : PTrieCode.t X) (counts : PTrieCode.t (PTrieCode.t (list C * N)))
    (state : database_runtime C X) : database_runtime C X :=
  DatabaseRuntime (runtime_allocated state) (runtime_changed state) (runtime_declarations state) (runtime_kinds state) (runtime_rows state)
    (runtime_slots state) (runtime_equalities state) (runtime_queue state) all_indexes new_indexes
    counts (runtime_function_slots state) (runtime_max_name state) (runtime_slot_bound state).
TimeFun runtime_set_indexes.

Definition database_set_runtime {C X} (state : database_runtime C X)
    (db : database_state C X) : database_state C X :=
  DatabaseState (db_forest db) (db_nuses db) (db_npending db) (db_wmark db)
    (db_written_cells db) (db_index_counters db) (db_row_store db) (db_slot_store db) state
    (db_cache_updates db).
TimeFun database_set_runtime.

Definition database_set_forest {C X} (forest : UnionFindCode.t)
    (db : database_state C X) : database_state C X :=
  DatabaseState forest (db_nuses db) (db_npending db) (db_wmark db)
    (db_written_cells db) (db_index_counters db) (db_row_store db) (db_slot_store db) (db_runtime db)
    (db_cache_updates db).
TimeFun database_set_forest.

Definition database_set_pending {C X} (pending : N)
    (db : database_state C X) : database_state C X :=
  DatabaseState (db_forest db) (db_nuses db) pending (db_wmark db)
    (db_written_cells db) (db_index_counters db) (db_row_store db) (db_slot_store db) (db_runtime db)
    (db_cache_updates db).
TimeFun database_set_pending.

Definition database_set_nuses {C X} (count : N)
    (db : database_state C X) : database_state C X :=
  DatabaseState (db_forest db) count (db_npending db) (db_wmark db)
    (db_written_cells db) (db_index_counters db) (db_row_store db) (db_slot_store db)
    (db_runtime db) (db_cache_updates db).
TimeFun database_set_nuses.

Definition database_set_row_store {C X} (store : database_row_store C)
    (db : database_state C X) : database_state C X :=
  DatabaseState (db_forest db) (db_nuses db) (db_npending db) (db_wmark db)
    (db_written_cells db) (db_index_counters db) store (db_slot_store db)
    (db_runtime db) (db_cache_updates db).
TimeFun database_set_row_store.

Definition database_set_index_counters {C X} (counters : list positive)
    (db : database_state C X) : database_state C X :=
  DatabaseState (db_forest db) (db_nuses db) (db_npending db) (db_wmark db)
    (db_written_cells db) counters (db_row_store db) (db_slot_store db)
    (db_runtime db) (db_cache_updates db).
TimeFun database_set_index_counters.

(** Each cache call records its actual update counter, input rank, index counters and cells. *)
Definition database_record_cache {C X} (u : list C) (counters : list positive)
    (db : database_state C X) : database_state C X :=
  let next := N.succ_pos (db_cache_updates db) in
  let rank := Pos.of_succ_nat (length u) in
  DatabaseState (db_forest db) (db_nuses db) (db_npending db) (db_wmark db)
    (u ++ db_written_cells db)
    (next :: rank :: (counters ++ db_index_counters db))
    (db_row_store db) (db_slot_store db) (db_runtime db) (Npos next).
TimeFun database_record_cache.

(** Recording a cache call traverses only its new input and newly collected counters. *)
Lemma T_database_record_cache_le : forall C X (u : list C) counters (db : database_state C X),
  (T_database_record_cache u counters db <=
    32 + N.T_succ_pos (db_cache_updates db) +
      6 * N.of_nat (length u + 1) + N.of_nat (length counters + 1))%N.
Proof.
  intros C X u counters db.
  pose proof (database_of_succ_nat_amort (length u)) as Hrank.
  pose proof (Datatypes.T_length_le u) as Hlength.
  pose proof (Datatypes.T_app_le counters (db_index_counters db)) as Hcounters.
  pose proof (Datatypes.T_app_le u (db_written_cells db)) as Hcells.
  time_unfold @T_database_record_cache. time_simpl. time_cbn. lia.
Qed.

(** A ghost operation records whether a tuple was inserted or removed from an index. *)
Definition database_index_step {C X : Type} (insert remove : list C -> X -> X)
    (ix : X) (operation : bool * list C) : X :=
  if fst operation then insert (snd operation) ix else remove (snd operation) ix.

(** Cached indexes have finite construction histories over the recorded written cells. *)
Definition database_index_history {C X : Type} (empty : X)
    (insert remove : list C -> X -> X) (written : list C) (ix : X) : Prop :=
  exists operations : list (bool * list C),
    ix = fold_left (database_index_step insert remove) operations empty /\
    Forall (fun operation => fst operation = true -> incl (snd operation) written) operations.

(** The empty index has an empty construction history. *)
Lemma database_index_history_empty : forall C X (empty : X) insert remove (written : list C),
  database_index_history empty insert remove written empty.
Proof.
  intros C X empty insert remove written. exists []. split; [reflexivity | constructor].
Qed.

(** Recording more written cells retains every existing construction witness. *)
Lemma database_index_history_weaken : forall C X (empty : X) insert remove
  (before after : list C) ix,
  incl before after -> database_index_history empty insert remove before ix ->
  database_index_history empty insert remove after ix.
Proof.
  intros C X empty insert remove before after ix Hwritten [operations [Hix Hhistory]].
  exists operations. split; [exact Hix |].
  rewrite Forall_forall in Hhistory |- *. intros operation Hin Hinsert c Hcell.
  apply Hwritten. exact (Hhistory operation Hin Hinsert c Hcell).
Qed.

(** An insertion extends the ghost history when its tuple cells have been recorded. *)
Lemma database_index_history_insert : forall C X (empty : X) insert remove
  (written u : list C) ix,
  database_index_history empty insert remove written ix -> incl u written ->
  database_index_history empty insert remove written (insert u ix).
Proof.
  intros C X empty insert remove written u ix [operations [Hix Hhistory]] Hcells.
  exists (operations ++ [(true, u)]). split.
  - rewrite fold_left_app. cbn [fold_left database_index_step fst snd]. now rewrite Hix.
  - apply Forall_app. split; [exact Hhistory |]. constructor; [exact (fun _ => Hcells) | constructor].
Qed.

(** A removal extends the history without adding any written-cell requirement. *)
Lemma database_index_history_remove : forall C X (empty : X) insert remove
  (written u : list C) ix,
  database_index_history empty insert remove written ix ->
  database_index_history empty insert remove written (remove u ix).
Proof.
  intros C X empty insert remove written u ix [operations [Hix Hhistory]].
  exists (operations ++ [(false, u)]). split.
  - rewrite fold_left_app. cbn [fold_left database_index_step fst snd]. now rewrite Hix.
  - apply Forall_app. split; [exact Hhistory |]. constructor; [discriminate | constructor].
Qed.

(** Properties preserved by recorded insertions and removals hold for every ghost history. *)
Lemma database_index_history_induction : forall C X (empty : X) insert remove
  (written : list C) (P : X -> Prop),
  P empty ->
  (forall u ix, incl u written -> P ix -> P (insert u ix)) ->
  (forall u ix, P ix -> P (remove u ix)) ->
  forall ix, database_index_history empty insert remove written ix -> P ix.
Proof.
  intros C X empty insert remove written P Hempty Hinsert Hremove ix
    [operations [-> Hhistory]].
  assert (Hfold : forall operations current,
    Forall (fun operation => fst operation = true -> incl (snd operation) written) operations ->
    P current -> P (fold_left (database_index_step insert remove) operations current)).
  { intro history. induction history as [|[add u] rest IH]; intros current Hentries Hcurrent.
    - exact Hcurrent.
    - inversion Hentries as [|entry tail Hhead Htail]; subst entry tail.
      cbn [fold_left database_index_step fst snd]. apply IH; [exact Htail |].
      destruct add.
      + apply Hinsert; [exact (Hhead eq_refl) | exact Hcurrent].
      + apply Hremove. exact Hcurrent. }
  now apply Hfold.
Qed.

Module DatabaseCode (V : VALUE_OPS) (I : INDEX_OPS V) <: DATABASE_OPS V I.
  Definition t := database_state (cell V.t) I.t.

  Fixpoint id_occurrences (f : positive) (k : list (cell V.t))
      (cells : list (cell V.t)) : list (positive * (positive * list (cell V.t))) :=
    match cells with
    | [] => []
    | Id i :: rest => (i, (f, k)) :: id_occurrences f k rest
    | Val _ :: rest => id_occurrences f k rest
    end.
  TimeFun id_occurrences.

  Lemma id_occurrences_member : forall f k cells x g key,
    In (x, (g, key)) (id_occurrences f k cells) <->
      g = f /\ key = k /\ In (Id x) cells.
  Proof.
    intros f k cells. induction cells as [|[i | v] rest IH]; intros x g key;
      cbn [id_occurrences In].
    - tauto.
    - rewrite IH. split.
      + intros [Heq | [Hg [Hk Hin]]].
        * injection Heq as -> -> ->. repeat split; now left.
        * repeat split; try assumption. now right.
      + intros [Hg [Hk [Heq | Hin]]].
        * injection Heq as <-. subst g key. now left.
        * right. repeat split; assumption.
    - rewrite IH. split.
      + intros [Hg [Hk Hin]]. repeat split; try assumption. now right.
      + intros [Hg [Hk [Himpossible | Hin]]]; [discriminate |].
        repeat split; assumption.
  Qed.

  Definition db_cell_code (c : cell V.t) : positive :=
    match c with Id i => xO i | Val v => xI (V.encode v) end.
  Definition db_cell_eqb (c d : cell V.t) : bool :=
    match c, d with
    | Id i, Id j => Pos.eqb i j
    | Val v, Val w => V.eqb v w
    | _, _ => false
    end.
  Definition db_tuple_code := list_code db_cell_code.

  Definition db_row_code (f : positive) (k : list (cell V.t)) : positive :=
    pair_code (fun p => p) db_tuple_code (f, k).
  Definition row_get (f : positive) (k : list (cell V.t)) (db : t)
      : option (option (cell V.t)) :=
    option_map snd (PTrieCode.get (db_row_code f k) (runtime_rows (db_runtime db))).
  Definition kind_get (f : positive) (db : t) : option output :=
    PTrieCode.get f (runtime_kinds (db_runtime db)).
  Definition normal_cell (db : t) (c : cell V.t) : cell V.t :=
    match c with
    | Id i =>
      match N.compare (runtime_allocated (db_runtime db)) (Npos i) with
      | Lt => Id i
      | _ => Id (fst (UnionFindCode.find i (db_forest db)))
      end
    | Val v => Val v
    end.
  Definition normal_key (db : t) (k : list (cell V.t)) : list (cell V.t) :=
    map (normal_cell db) k.
  Definition output_eqb (a b : option (cell V.t)) : bool :=
    match a, b with
    | None, None => true
    | Some c, Some d => db_cell_eqb c d
    | _, _ => false
    end.
  Definition combine_output (db : t) (f : positive)
      (previous : option (option (cell V.t))) (o : option (cell V.t)) : option (cell V.t) :=
    match previous, kind_get f db, o with
    | Some (Some (Val a)), Some (OLat m), Some (Val b) => Some (Val (V.merge m a b))
    | Some old, _, _ => old
    | None, _, _ => o
    end.

  Definition slot_index_get (s : positive) (indexes : PTrieCode.t I.t) : I.t :=
    match PTrieCode.get s indexes with Some ix => ix | None => I.empty end.
  Definition projection_table_get (s : positive)
      (counts : PTrieCode.t (PTrieCode.t (list (cell V.t) * N))) :=
    match PTrieCode.get s counts with Some table => table | None => PTrieCode.empty end.

  (** Projection counts keep a shared tuple until its last contributing row is removed. *)
  Definition slot_update_one (add : bool) (s : N) (u : list (cell V.t))
      (state : database_runtime (cell V.t) I.t) :=
    let code := N.succ_pos s in
    let tuple_code := db_tuple_code u in
    let table := projection_table_get code (runtime_projection_counts state) in
    let count := match PTrieCode.get tuple_code table with
      | Some (_, n) => n | None => 0%N end in
    let all := slot_index_get code (runtime_all_indexes state) in
    let new := slot_index_get code (runtime_new_indexes state) in
    if add then
      runtime_set_indexes
        (PTrieCode.set code (I.insert u all) (runtime_all_indexes state))
        (PTrieCode.set code (I.insert u new) (runtime_new_indexes state))
        (PTrieCode.set code (PTrieCode.set tuple_code (u, N.succ count) table)
          (runtime_projection_counts state)) state
    else match count with
      | N0 => state
      | Npos xH =>
        runtime_set_indexes
          (PTrieCode.set code (I.remove u all) (runtime_all_indexes state))
          (PTrieCode.set code (I.remove u new) (runtime_new_indexes state))
          (PTrieCode.set code (PTrieCode.remove tuple_code table)
            (runtime_projection_counts state)) state
      | _ =>
        runtime_set_indexes (runtime_all_indexes state) (runtime_new_indexes state)
          (PTrieCode.set code (PTrieCode.set tuple_code (u, N.pred count) table)
            (runtime_projection_counts state)) state
      end.

  Fixpoint slot_update_many (add : bool) (u : list (cell V.t))
      (layouts : list (N * database_slot_layout))
      (state : database_runtime (cell V.t) I.t) :=
    match layouts with
    | [] => state
    | (s, layout) :: rest =>
      slot_update_many add u rest
        (slot_update_one add s (project_slot_layout layout u) state)
    end.

  (** A second group pass records the counters of the indexes produced by this cache call. *)
  Fixpoint slot_updated_counters (layouts : list (N * database_slot_layout))
      (state : database_runtime (cell V.t) I.t) : list positive :=
    match layouts with
    | [] => []
    | (s, _) :: rest =>
      let code := N.succ_pos s in
      I.next (slot_index_get code (runtime_all_indexes state)) ::
      I.next (slot_index_get code (runtime_new_indexes state)) ::
      slot_updated_counters rest state
    end.

  Definition slots_update (add : bool) (f : positive) (u : list (cell V.t)) (db : t)
      : t :=
    let layouts := match PTrieCode.get f (runtime_function_slots (db_runtime db)) with
      | None => [] | Some layouts => layouts end in
    let state := slot_update_many add u layouts (db_runtime db) in
    database_record_cache u (slot_updated_counters layouts state)
      (database_set_runtime state db).

  Definition row_write (f : positive) (k : list (cell V.t)) (o : option (cell V.t))
      (db : t) : t :=
    database_set_runtime
      (runtime_set_rows
        (PTrieCode.set (db_row_code f k) ((f, k), o) (runtime_rows (db_runtime db)))
        (runtime_set_changed true (db_runtime db))) db.

  (** A new historical key gets a stable row identifier and a current key. *)
  Definition ensure_row_identity (f : positive) (k : list (cell V.t))
      (db : t) : t :=
    let store := db_row_store db in
    match PTrieCode.get (db_row_code f k) (row_history store) with
    | Some _ => db
    | None =>
      let r := row_fresh store in
      let next := Pos.succ r in
      let updated := {|
        row_history := PTrieCode.set (db_row_code f k) ((f, k), r) (row_history store);
        row_links := row_links store;
        row_weights := PTrieCode.set r 1%N (row_weights store);
        row_keys := PTrieCode.set r k (row_keys store);
        row_fresh := next;
        row_uses := row_uses store
      |} in
      database_set_index_counters (next :: db_index_counters db)
        (database_set_row_store updated db)
    end.

  (** Resolution follows the parent links of a historical row identifier. *)
  Fixpoint row_root (fuel : nat) (r : positive)
      (store : database_row_store (cell V.t)) : positive :=
    match fuel with
    | O => r
    | S remaining =>
      match PTrieCode.get r (row_links store) with
      | None => r
      | Some parent =>
        if Pos.eqb parent r then r else row_root remaining parent store
      end
    end.

  Definition db_locate (f : positive) (k : list (cell V.t)) (db : t)
      : option (list (cell V.t)) :=
    let store := db_row_store db in
    match PTrieCode.get (db_row_code f k) (row_history store) with
    | None => None
    | Some (_, r) =>
      let depth := length k *
        (N.to_nat (N.log2 (runtime_allocated (db_runtime db))) + 1) in
      PTrieCode.get (row_root depth r store) (row_keys store)
    end.

  (** A replacement registers every identifier occurrence in its written tuple. *)
  Definition register_row_uses (f : positive) (k : list (cell V.t))
      (o : option (cell V.t)) (db : t) : t :=
    let entries := id_occurrences f k (k ++ option_list o) in
    let identified := ensure_row_identity f k db in
    let store := db_row_store identified in
    let updated := {|
      row_history := row_history store;
      row_links := row_links store;
      row_weights := row_weights store;
      row_keys := row_keys store;
      row_fresh := row_fresh store;
      row_uses := DatabaseUses.register entries (row_uses store)
    |} in
    database_set_nuses (db_nuses identified + N.of_nat (length entries))
      (database_set_row_store updated identified).

  Definition row_replace (f : positive) (k : list (cell V.t))
      (previous : option (option (cell V.t))) (o : option (cell V.t)) (db : t) : t :=
    let without := match previous with
      | None => db
      | Some before => slots_update false f (k ++ option_list before) db
      end in
    register_row_uses f k o
      (row_write f k o (slots_update true f (k ++ option_list o) without)).

  (** The row table is erased after its slot contributions have been removed. *)
  Definition row_erase (f : positive) (k : list (cell V.t)) (db : t) : t :=
    database_set_runtime
      (runtime_set_rows
        (PTrieCode.remove (db_row_code f k) (runtime_rows (db_runtime db))) (db_runtime db)) db.

  (** An absent row is unchanged; a present row releases each projected occurrence. *)
  Definition row_delete (f : positive) (k : list (cell V.t)) (db : t) : t :=
    match row_get f k db with
    | None => db
    | Some o => row_erase f k (slots_update false f (k ++ option_list o) db)
    end.
  (** Initialization stores declarations, slots, empty rows and index caches. *)
  Definition init (ds : list decl) (sl : list (positive * list nat)) : t :=
    let prepared := prepare_slot_layouts sl in
    let bound := N.of_nat (length sl) in
    DatabaseState UnionFindCode.empty 0%N 0%N
      (N.max (Npos (database_max_name ds)) (N.succ bound)) []
      (match sl with [] => [1%positive] | _ => [1%positive; N.succ_pos bound] end)
      {| row_history := PTrieCode.empty; row_links := PTrieCode.empty;
         row_weights := PTrieCode.empty; row_keys := PTrieCode.empty;
         row_fresh := 1; row_uses := DatabaseUseMap.empty |}
      {| prepared_slots := prepared;
         slot_positions := database_rank_slots ds sl;
         function_groups := []; slot_groups := [];
         projection_counts := [] |}
      (DatabaseRuntime 0%N false ds (database_kinds ds) PTrieCode.empty sl [] []
        PTrieCode.empty PTrieCode.empty PTrieCode.empty
        (database_slot_groups 0 prepared PTrieCode.empty) (database_max_name ds) bound) 0%N.
  Definition find (i : positive) (db : t) : positive * t :=
    let result := UnionFindCode.find i (db_forest db) in
    (fst result, database_set_forest (snd result) db).
  Definition lookup (f : positive) (k : list (cell V.t)) (db : t)
      : option (option (cell V.t)) * t :=
    match Pos.compare (runtime_max_name (db_runtime db)) f with
    | Lt => (None, db)
    | _ => (row_get f (normal_key db k) db, db)
    end.
  Definition union (i j : positive) (db : t) :=
    let result := UnionFindCode.union i j (db_forest db) in
    let next := database_set_forest (snd result) db in
    match fst result with
    | None => next
    | Some (_, loser) =>
      database_set_pending (N.succ (db_npending db))
        (database_set_runtime
          (runtime_set_union true ((i, j) :: runtime_equalities (db_runtime db))
            (loser :: runtime_queue (db_runtime db)) (db_runtime db)) next)
    end.
  Definition allocate_id (i : positive) (db : t) : t :=
    database_set_forest (UnionFindCode.add i (db_forest db))
      (database_set_runtime
        (runtime_set_allocated (Npos i) (runtime_set_changed true (db_runtime db))) db).
  Definition make (f : positive) (k : list (cell V.t)) (db : t) : positive * t :=
    let ck := normal_key db k in
    let previous := row_get f ck db in
    match previous with
    | Some (Some (Id j)) => (fst (UnionFindCode.find j (db_forest db)), db)
    | _ =>
      let i := N.succ_pos (runtime_allocated (db_runtime db)) in
      let fresh := allocate_id i db in
      let next := match kind_get f db with
        | Some OId => row_replace f ck previous (Some (Id i)) fresh
        | _ => fresh
        end in
      (i, next)
    end.
  Definition put (f : positive) (k : list (cell V.t)) (o : option (cell V.t))
      (db : t) : t :=
    let ck := normal_key db k in
    let co := option_map (normal_cell db) o in
    let previous := row_get f ck db in
    let updated := combine_output db f previous co in
    let next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db
      end in
    match previous with
    | Some before =>
      if output_eqb before updated then next else row_replace f ck previous updated next
    | None => row_replace f ck previous updated next
    end.

  (** A repaired row keeps its historical identifier through a size-based link. *)
  Definition move_row_identity (f : positive) (old current : list (cell V.t))
      (db : t) : t :=
    let store := db_row_store db in
    match PTrieCode.get (db_row_code f old) (row_history store),
      PTrieCode.get (db_row_code f current) (row_history store) with
    | Some (_, old_id), Some (_, current_id) =>
      let depth := length old *
        (N.to_nat (N.log2 (runtime_allocated (db_runtime db))) + 1) in
      let old_root := row_root depth old_id store in
      let current_root := row_root depth current_id store in
      let old_size := match PTrieCode.get old_root (row_weights store) with
        | Some n => n | None => 1%N end in
      let current_size := match PTrieCode.get current_root (row_weights store) with
        | Some n => n | None => 1%N end in
      let same_root := Pos.eqb old_root current_root in
      let old_loses := N.leb old_size current_size in
      let winner := if same_root then old_root else
        if old_loses then current_root else old_root in
      let loser := if old_loses then old_root else current_root in
      let updated := {|
        row_history := row_history store;
        row_links := if same_root then row_links store else
          PTrieCode.set loser winner (row_links store);
        row_weights := if same_root then row_weights store else
          PTrieCode.set winner (old_size + current_size)%N (row_weights store);
        row_keys := PTrieCode.set winner current (row_keys store);
        row_fresh := row_fresh store;
        row_uses := row_uses store
      |} in
      database_set_row_store updated db
    | _, _ => db
    end.

  (** Repair one current row, discarding its old projections before inserting its normal form. *)
  Definition repair_current (f : positive) (k : list (cell V.t)) (db : t) : t :=
    match row_get f k db with
    | None => db
    | Some o =>
      let ck := normal_key db k in
      let co := option_map (normal_cell db) o in
      if andb (Pos.eqb (db_tuple_code ck) (db_tuple_code k)) (output_eqb co o)
      then db else
        let updated := put f ck co (row_delete f k db) in
        let store := db_row_store updated in
        database_set_nuses (db_nuses db)
          (database_set_row_store
            {| row_history := row_history store;
               row_links := row_links store;
               row_weights := row_weights store;
               row_keys := row_keys store;
               row_fresh := row_fresh store;
               row_uses := row_uses (db_row_store db) |} updated)
    end.

  (** An active historical key resolves before its current row is repaired. *)
  Definition db_repair_entry (f : positive) (k : list (cell V.t)) (db : t) : t :=
    match db_locate f k db with
    | None => db
    | Some current =>
      match row_get f current db with
      | None => db
      | Some o =>
        let ck := normal_key db current in
        let co := option_map (normal_cell db) o in
        if andb (Pos.eqb (db_tuple_code ck) (db_tuple_code current)) (output_eqb co o)
        then db else move_row_identity f current ck (repair_current f current db)
      end
    end.
  (** Enumerate current rows that contain an occurrence of a queued loser. *)
  Definition db_get_uses (i : positive) (db : t) : list (positive * list (cell V.t)) :=
    DatabaseUses.bucket i (row_uses (db_row_store db)).

  (** Popping the scheduling queue leaves the represented database view unchanged. *)
  Definition db_pop_loser (db : t) : option (positive * t) :=
    match runtime_queue (db_runtime db) with
    | [] => None
    | i :: rest =>
      let store := db_row_store db in
      let root := fst (UnionFindCode.find i (db_forest db)) in
      let updated := {|
        row_history := row_history store;
        row_links := row_links store;
        row_weights := row_weights store;
        row_keys := row_keys store;
        row_fresh := row_fresh store;
        row_uses := DatabaseUses.transfer i root (row_uses store)
      |} in
      Some (i,
        database_set_pending (N.pred (db_npending db))
          (database_set_runtime
            (runtime_set_union (runtime_changed (db_runtime db))
              (runtime_equalities (db_runtime db)) rest (db_runtime db))
            (database_set_row_store updated db)))
    end.

  (** Repair active rows before taking the next pending equality. *)
  Definition db_rstep (s : t * list (positive * list (cell V.t)))
      : (t * list (positive * list (cell V.t))) + t :=
    match snd s with
    | (f, k) :: rest => inl (db_repair_entry f k (fst s), rest)
    | [] =>
      match db_pop_loser (fst s) with
      | None => inr (fst s)
      | Some (i, db) => inl (db, db_get_uses i (fst s))
      end
    end.
  Definition db_rebuild_fuel (db : t) : N :=
    ((N.size (runtime_allocated (db_runtime db)) + 2) * (db_nuses db + 1) + db_npending db + 1)%N.
  Definition rebuild (db : t) :=
    match loopN db_rstep (db_rebuild_fuel db) (db, []) with
    | inl s => fst s
    | inr result => result
    end.
  Definition index (s : N) (new : bool) (db : t) : I.t :=
    match N.compare s (runtime_slot_bound (db_runtime db)) with
    | Lt =>
      let indexes := if new then runtime_new_indexes (db_runtime db)
        else runtime_all_indexes (db_runtime db) in
      match PTrieCode.get (N.succ_pos s) indexes with Some ix => ix | None => I.empty end
    | _ => I.empty
    end.
  Definition advance (db : t) :=
    database_set_runtime
      (runtime_set_changed false
        (runtime_set_indexes (runtime_all_indexes (db_runtime db)) PTrieCode.empty
          (runtime_projection_counts (db_runtime db)) (db_runtime db))) db.
  Definition changed (db : t) := runtime_changed (db_runtime db).
  Definition ids (db : t) : N := runtime_allocated (db_runtime db).
  Definition locate := db_locate.
  Definition rank_slots := database_rank_slots.
End DatabaseCode.

Module Database (V : VALUE) (I : INDEX V) <: DATABASE V I.
  Include DatabaseCode V I.
  Include DATABASE_SPEC V I.
  Lemma db_cell_code_inj : forall c d,
    db_cell_code c = db_cell_code d -> c = d.
  Proof.
    intros [i | v] [j | w] Hcode; cbn [db_cell_code] in Hcode;
      try discriminate Hcode.
    - injection Hcode as Heq. now subst.
    - injection Hcode as Heq. f_equal. apply V.encode_inj. exact Heq.
  Qed.

  Lemma db_tuple_code_inj : forall xs ys,
    db_tuple_code xs = db_tuple_code ys -> xs = ys.
  Proof.
    intros xs. induction xs as [| x rest IH]; intros [| y tail] Hcode;
      cbn [db_tuple_code list_code] in Hcode.
    - reflexivity.
    - destruct (db_cell_code y); cbn [glue] in Hcode; discriminate Hcode.
    - destruct (db_cell_code x); cbn [glue] in Hcode; discriminate Hcode.
    - destruct (glue_inj _ _ _ _ Hcode) as [Hhead Htail].
      f_equal.
      + apply db_cell_code_inj. exact Hhead.
      + apply IH. exact Htail.
  Qed.

  (* spec: wf view repr pending old slots *)
  Definition view (db : t) : Model.view (V := V.t) :=
    {| row := fun f k o => row_get f k db = Some o;
       same := equality_log (runtime_equalities (db_runtime db));
       kind := fun f => kind_get f db |}.
  Definition repr (db : t) : positive -> positive := UnionFind.repr (db_forest db).
  Definition pending (db : t) : nat := length (runtime_queue (db_runtime db)).
  Definition old (db : t) (f : positive) (k : list (cell V.t)) := row_get f k db.
  Definition slots (db : t) : list (positive * list nat) := runtime_slots (db_runtime db).
  Definition canon (db : t) (c : cell V.t) : cell V.t :=
    match c with
    | Id i => Id (repr db i)
    | Val v => Val v
    end.
  Definition canonical (db : t) : Prop :=
    forall f k o, row (view db) f k o ->
    forall i, In (Id i) (k ++ option_list o) -> repr db i = i.
  Definition cong (db : t) := fd_congruence (view db).
  Definition combine (db : t) (f : positive) (previous : option (option (cell V.t)))
      (o : option (cell V.t)) : option (cell V.t) :=
    match previous, kind (view db) f, o with
    | Some (Some (Val a)), Some (OLat m), Some (Val b) => Some (Val (V.merge m a b))
    | Some old, _, _ => old
    | None, _, _ => o
    end.
  Definition allocated (db : t) (i : positive) : Prop := (Npos i <= ids db)%N.
  (** Slot permutations contain distinct positions within the supplied tuple. *)
  Definition slots_fit (db : t) (f : positive) (n : nat) : Prop :=
    forall perm, In (f, perm) (slots db) -> NoDup perm /\ Forall (fun i => i < n) perm.
  Definition kind_ok (db : t) (f : positive) (k : list (cell V.t))
      (o : option (cell V.t)) : Prop :=
    (forall i, In (Id i) (k ++ option_list o) -> allocated db i) /\
    slots_fit db f (length (k ++ option_list o)) /\
    match kind (view db) f, o with
    | Some ORel, None => True
    | Some OId, Some (Id _) => True
    | Some (OLat _), Some (Val _) => True
    | _, _ => False
    end.
  Definition conflict (db : t) (f : positive) (k : list (cell V.t))
      (o : option (cell V.t)) (a b : positive) : Prop :=
    old db f (map (canon db) k) = Some (Some (Id a)) /\
    option_map (canon db) o = Some (Id b).
  Definition fresh_id (db : t) (i : positive) : Prop := i = N.succ_pos (ids db).
  Definition extends_by (db db' : t) (f : positive) (k : list (cell V.t))
      (i : positive) : Prop :=
    ids db' = Npos i /\ kind (view db') = kind (view db) /\
    (forall a b, same (view db') a b <-> same (view db) a b \/ (a = i /\ b = i)) /\
    (forall f' k' o', row (view db') f' k' o' <->
      row (view db) f' k' o' \/ (f' = f /\ k' = map (canon db) k /\ o' = Some (Id i))).
  Definition slot_of (db : t) (s : N) : option (positive * list nat) :=
    nth_error (slots db) (N.to_nat s).
  Definition permute (perm : list nat) (u : list (cell V.t)) : list (cell V.t) :=
    flat_map (fun i => option_list (nth_error u i)) perm.
  Definition merged (db : t) (f : positive) (os : list (option (cell V.t)))
      : option (cell V.t) :=
    match map (option_map (canon db)) os with
    | [] => None
    | o :: rest => fold_left (fun acc o' => combine db f (Some acc) o') rest o
    end.

  Definition out_le (db : t) (f : positive) (a b : option (cell V.t)) : Prop :=
    match a, b with
    | None, _ => True
    | Some c, Some d => cell_le V.merge (view db) f c d
    | _, _ => False
    end.
  Definition present_put (w : Model.view (V := V.t)) (f : positive)
      (k : list (cell V.t)) (o : option (cell V.t)) : Prop :=
    exists d, row w f k d /\
      match o, d with
      | None, _ => True
      | Some a, Some b => cell_le V.merge w f a b
      | _, _ => False
      end.

  Module Cells := CellKey V.
  Module Tuples := ListKey Cells.
  Module RowKeys := PairKey PosKey Tuples.
  Module RowMap := TrieMap RowKeys.
  Module RowFacts := FiniteMapFacts RowKeys RowMap.
  Module ForestFacts := UnionFindFacts UnionFind.

  (** A cached projection count records how many stored rows contribute its tuple. *)
  Definition stored_projection_count (db : t) (s : N) (u : list (cell V.t)) : N :=
    match PTrieCode.get (db_tuple_code u)
      (projection_table_get (N.succ_pos s) (runtime_projection_counts (db_runtime db))) with
    | Some (_, n) => n
    | None => 0%N
    end.

  (** Counts refer to the actual finite row map, including distinct rows with one projection. *)
  Definition projection_counts_ok (db : t) : Prop :=
    forall s f perm u, slot_of db s = Some (f, perm) ->
    exists rs, NoDup rs /\
      (forall r, In r rs <->
        In r (RowMap.elements (runtime_rows (db_runtime db))) /\ fst (fst r) = f /\
        permute perm (snd (fst r) ++ option_list (snd r)) = u) /\
      N.to_nat (stored_projection_count db s u) = length rs.

  (** A slot's proof observation consists of its count table and two index cache entries. *)
  Definition slot_snapshot (state : database_runtime (cell V.t) I.t) (s : N) :=
    (PTrieCode.get (N.succ_pos s) (runtime_projection_counts state),
     PTrieCode.get (N.succ_pos s) (runtime_all_indexes state),
     PTrieCode.get (N.succ_pos s) (runtime_new_indexes state)).

  (** A runtime count observation uses the same lookup as the public database count. *)
  Definition runtime_projection_count (state : database_runtime (cell V.t) I.t)
      (s : N) (u : list (cell V.t)) : N :=
    match PTrieCode.get (db_tuple_code u)
      (projection_table_get (N.succ_pos s) (runtime_projection_counts state)) with
    | Some (_, n) => n
    | None => 0%N
    end.

  (** A runtime index observation selects one of the two stored per-slot caches. *)
  Definition runtime_slot_index (state : database_runtime (cell V.t) I.t)
      (s : N) (new : bool) : I.t :=
    slot_index_get (N.succ_pos s)
      (if new then runtime_new_indexes state else runtime_all_indexes state).

  (** Metadata records cache activity and index construction independently of the row map. *)
  Definition metadata_ok (db : t) : Prop :=
    In 1%positive (db_index_counters db) /\
    In (N.succ_pos (N.of_nat (length (slots db)))) (db_index_counters db) /\
    (forall p, db_cache_updates db = Npos p -> In p (db_index_counters db)) /\
    (forall s new, In (I.next (runtime_slot_index (db_runtime db) s new))
      (db_index_counters db)) /\
    (forall s new, database_index_history I.empty I.insert I.remove (db_written_cells db)
      (runtime_slot_index (db_runtime db) s new)) /\
    (forall s u, (runtime_projection_count (db_runtime db) s u <= db_cache_updates db)%N) /\
    (runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db)) PTrieCode.empty) /\
    runtime_slot_bound (db_runtime db) = N.of_nat (length (slots db)).

  (** These observations determine metadata validity and omit the row store and forest. *)
  Definition metadata_snapshot (db : t) :=
    (db_cache_updates db, db_written_cells db, db_index_counters db,
     runtime_slots (db_runtime db), runtime_slot_bound (db_runtime db),
     runtime_function_slots (db_runtime db), runtime_all_indexes (db_runtime db),
     runtime_new_indexes (db_runtime db), runtime_projection_counts (db_runtime db)).

  (** Equal metadata observations transfer all construction and counter witnesses. *)
  Lemma metadata_snapshot_ok : forall db db',
    metadata_snapshot db = metadata_snapshot db' -> metadata_ok db -> metadata_ok db'.
  Proof.
    intros db db' Hsame Hmetadata. unfold metadata_snapshot in Hsame.
    injection Hsame as Hupdates Hwritten Hcounters Hslots Hbound Hgroups Hall Hnew Hcounts.
    unfold metadata_ok, slots, runtime_slot_index, runtime_projection_count in *.
    now rewrite <- Hupdates, <- Hwritten, <- Hcounters, <- Hslots, <- Hbound,
      <- Hgroups, <- Hall, <- Hnew, <- Hcounts.
  Qed.

  (** Each touched slot contributes both final index counters to the recorded list. *)
  Lemma slot_updated_counters_member : forall layouts state s layout,
    In (s, layout) layouts -> forall new,
    In (I.next (runtime_slot_index state s new)) (slot_updated_counters layouts state).
  Proof.
    intro layouts. induction layouts as [|[t block] rest IH]; intros state s layout Hin new.
    - contradiction.
    - destruct Hin as [Hequal | Hin].
      + injection Hequal as -> ->. cbn [slot_updated_counters runtime_slot_index].
        destruct new; [right; now left | now left].
      + cbn [slot_updated_counters]. right. right. now apply (IH state s layout).
  Qed.

  (** Initial caches have empty histories, zero counts and their root counter recorded. *)
  Lemma metadata_init : forall ds sl, metadata_ok (init ds sl).
  Proof.
    intros ds sl.
    assert (Hempty : forall s new,
      runtime_slot_index (db_runtime (init ds sl)) s new = I.empty).
    { intros s new. unfold runtime_slot_index, slot_index_get.
      cbn [init db_runtime runtime_new_indexes runtime_all_indexes].
      destruct new; now rewrite PTrie.get_empty. }
    unfold metadata_ok. split.
    - destruct sl; now left.
    - split.
      + destruct sl; [now left | right; now left].
      + split.
        * intros p Hzero. discriminate Hzero.
        * split.
          -- intros s new. rewrite Hempty, I.next_empty. destruct sl; now left.
          -- split.
             ++ intros s new. rewrite Hempty. apply database_index_history_empty.
             ++ split.
                ** intros s u. unfold runtime_projection_count, projection_table_get.
                   cbn [init db_runtime runtime_projection_counts db_cache_updates].
                   rewrite PTrie.get_empty. cbn. rewrite PTrie.get_empty. reflexivity.
                ** split; reflexivity.
  Qed.

  (** Changing only the forest preserves all cache metadata. *)
  Lemma metadata_set_forest : forall db forest, metadata_ok db ->
    metadata_ok (database_set_forest forest db).
  Proof.
    intros db forest. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** Changing only the pending counter preserves all cache metadata. *)
  Lemma metadata_set_pending : forall db count, metadata_ok db ->
    metadata_ok (database_set_pending count db).
  Proof.
    intros db count. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** Writing the row table leaves the independently maintained cache metadata intact. *)
  Lemma metadata_row_write : forall db f k o, metadata_ok db ->
    metadata_ok (row_write f k o db).
  Proof.
    intros db f k o. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** Erasing the row table also preserves the cache metadata observations. *)
  Lemma metadata_row_erase : forall db f k, metadata_ok db ->
    metadata_ok (row_erase f k db).
  Proof.
    intros db f k. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** Allocating an identifier does not alter the cache histories or counters. *)
  Lemma metadata_allocate_id : forall db i, metadata_ok db ->
    metadata_ok (allocate_id i db).
  Proof.
    intros db i. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** Forest compression changes none of the cache metadata observations. *)
  Lemma metadata_find : forall db i, metadata_ok db -> metadata_ok (snd (find i db)).
  Proof.
    intros db i. apply metadata_snapshot_ok. reflexivity.
  Qed.

  (** A union changes its forest and queue while retaining all cache metadata. *)
  Lemma metadata_union : forall db i j, metadata_ok db -> metadata_ok (union i j db).
  Proof.
    intros db i j Hmetadata. unfold union.
    destruct (UnionFindCode.union i j (db_forest db)) as [[pair |] forest].
    - destruct pair as [winner loser].
      eapply metadata_snapshot_ok; [reflexivity | exact Hmetadata].
    - eapply metadata_snapshot_ok; [reflexivity | exact Hmetadata].
  Qed.

  (** Advancing starts an empty delta history and retains every other metadata fact. *)
  Lemma metadata_advance : forall db, metadata_ok db -> metadata_ok (advance db).
  Proof.
    intros db (Hone & Hslots & Hcounter & Hnext & Hhistory & Hcount & Hgroups & Hbound).
    unfold metadata_ok.
    split; [exact Hone |]. split; [exact Hslots |]. split; [exact Hcounter |].
    split.
    - intros s new. destruct new; [| exact (Hnext s false)].
      unfold runtime_slot_index, slot_index_get.
      cbn [advance database_set_runtime runtime_set_changed runtime_set_indexes
        db_runtime runtime_new_indexes db_index_counters].
      rewrite PTrie.get_empty, I.next_empty. exact Hone.
    - split.
      + intros s new. destruct new; [| exact (Hhistory s false)].
        unfold runtime_slot_index, slot_index_get.
        cbn [advance database_set_runtime runtime_set_changed runtime_set_indexes
          db_runtime runtime_new_indexes db_written_cells].
        rewrite PTrie.get_empty. apply database_index_history_empty.
      + split; [exact Hcount |]. split; assumption.
  Qed.

  (** Every stored row cell occurs in the concrete write history. *)
  Definition recorded_rows (db : t) : Prop :=
    forall f k o c, row (view db) f k o -> In c (k ++ option_list o) ->
      In c (db_written_cells db).

  (** The history invariant combines cache construction with coverage of current rows. *)
  Definition database_history (db : t) : Prop := metadata_ok db /\ recorded_rows db.

  (** Stored links, counters and uses have witnesses in the row history. *)
  Definition database_row_store_ok (db : t) : Prop :=
    let store := db_row_store db in
    let recorded r := In r (map (fun binding => snd (snd binding))
      (PTrieCode.elements (row_history store))) in
    let parent r := match PTrieCode.get r (row_links store) with
      | Some p => p | None => r end in
    let up d r := Nat.iter d parent r in
    let size r := match PTrieCode.get r (row_weights store) with
      | Some n => n | None => 1%N end in
    let entries := flat_map (fun binding => map (pair (fst binding)) (snd binding))
      (map (fun binding => (fst binding, snd (snd binding)))
        (PTrieCode.elements (row_uses store))) in
    (forall r p, PTrieCode.get r (row_links store) = Some p ->
      recorded r /\ recorded p /\
      (p <> r -> (1 <= size r)%N /\ (2 * size r <= size p)%N)) /\
    (forall x f k, In (f, k) (DatabaseUses.bucket x (row_uses store)) ->
      exists r, PTrieCode.get (db_row_code f k) (row_history store) = Some ((f, k), r)) /\
    N.to_nat (db_nuses db) = length entries /\
    (forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history store) = Some (key, r) ->
      (r < row_fresh store)%positive /\
      (match PTrieCode.get r (row_links store) with
       | Some parent => parent | None => r end < row_fresh store)%positive /\
      In (row_fresh store) (db_index_counters db)) /\
    (forall x f k c, In (f, k) (DatabaseUses.bucket x (row_uses store)) ->
      In c k -> In c (db_written_cells db)) /\
    (forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history store) = Some (key, r) ->
      exists d, d <= length k * (N.to_nat (N.log2 (ids db)) + 1) /\
        parent (up d r) = up d r /\
        db_locate f k db = PTrieCode.get (up d r) (row_keys store)) /\
    (forall f k key r d,
      PTrieCode.get (db_row_code f k) (row_history store) = Some (key, r) ->
      parent (up d r) = up d r ->
      (size (up d r) <= (ids db + 1) ^ N.of_nat (length k))%N) /\
    DatabaseUseMap.wf (row_uses store) /\
    (forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history store) = Some (key, r) ->
      key = (f, k)) /\
    (forall r p, PTrieCode.get r (row_links store) = Some p ->
      (r < row_fresh store)%positive /\ (p < row_fresh store)%positive).

  Definition database_row_store_depth_ok (db : t) : Prop :=
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      exists d, d <= length k * (N.to_nat (N.log2 (ids db)) + 1) /\
        (let parent current :=
          match PTrieCode.get current (row_links (db_row_store db)) with
          | Some p => p | None => current end in
         parent (Nat.iter d parent r) = Nat.iter d parent r) /\
        db_locate f k db =
          PTrieCode.get
            (Nat.iter d (fun current =>
              match PTrieCode.get current (row_links (db_row_store db)) with
              | Some p => p | None => current end) r)
            (row_keys (db_row_store db)).

  (** A historical key made of current representatives resolves to that key. *)
  Definition database_history_alignment (db : t) : Prop :=
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      (forall i, In (Id i) k -> repr db i = i) ->
      db_locate f k db = Some k.

  (** An active row's own historical identifier still resolves to that row. *)
  Definition database_active_history_coherent (db : t) : Prop :=
    forall f k o key r,
      row_get f k db = Some o ->
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      db_locate f k db = Some k.

  (** Historical row roots retain the function that created each identity. *)
  Definition database_history_root_owner (db : t) : Prop :=
    forall f k key r g args other s,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
        Some (other, s) ->
      row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) =
      row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db) -> f = g.

  Definition row_key_shape (k : list (cell V.t)) : list (option V.t) :=
    map (fun c => match c with Id _ => None | Val v => Some v end) k.

  Fixpoint history_shape_keys (n : nat) (shape : list (option V.t))
      : list (list (cell V.t)) :=
    match shape with
    | [] => [[]]
    | None :: rest =>
      flat_map (fun i => map (cons (Id (Pos.of_nat i)))
        (history_shape_keys n rest)) (seq 1 n)
    | Some v :: rest => map (cons (Val v)) (history_shape_keys n rest)
    end.

  Lemma history_shape_keys_length : forall n shape,
    length (history_shape_keys n shape) <= (S n) ^ length shape.
  Proof.
    intros n shape. induction shape as [| [v |] rest IH]; cbn [history_shape_keys length].
    - cbn [Nat.pow]. lia.
    - rewrite length_map. cbn [length Nat.pow]. nia.
    - assert (Hflat : forall xs : list nat,
        length (flat_map (fun i => map (cons (Id (Pos.of_nat i)))
          (history_shape_keys n rest)) xs) =
        length xs * length (history_shape_keys n rest)).
      { induction xs as [| i xs IHxs]; cbn; [reflexivity |].
        rewrite length_app, length_map, IHxs. lia. }
      rewrite Hflat, length_seq. cbn [length Nat.pow]. nia.
  Qed.

  Lemma history_shape_keys_member : forall n k,
    (forall i, In (Id i) k -> Pos.to_nat i <= n) ->
    In k (history_shape_keys n (row_key_shape k)).
  Proof.
    intros n k. induction k as [| c rest IH]; intro Hbounded.
    - now left.
    - destruct c as [i | v].
      + cbn [row_key_shape history_shape_keys]. apply in_flat_map.
        exists (Pos.to_nat i). split.
        * apply in_seq. split; [apply Pos2Nat.is_pos |].
          specialize (Hbounded i (or_introl eq_refl)). lia.
        * apply in_map_iff. exists rest. split.
          -- rewrite Pos2Nat.id. reflexivity.
          -- apply IH. intros j Hin. apply Hbounded. now right.
      + cbn [row_key_shape history_shape_keys]. apply in_map_iff.
        exists rest. split; [reflexivity |].
        apply IH. intros i Hin. apply Hbounded. now right.
  Qed.

  Lemma history_keys_cardinality : forall n shape keys,
    NoDup keys ->
    Forall (fun k => row_key_shape k = shape /\
      forall i, In (Id i) k -> Pos.to_nat i <= n) keys ->
    length keys <= (S n) ^ length shape.
  Proof.
    intros n shape keys Hdistinct Hbounded.
    eapply Nat.le_trans with (m := length (history_shape_keys n shape));
      [| apply history_shape_keys_length].
    apply NoDup_incl_length; [exact Hdistinct |].
    intros k Hin. apply Forall_forall with (x := k) in Hbounded;
      [| exact Hin].
    destruct Hbounded as [Hshape Hids]. subst shape.
    apply history_shape_keys_member. exact Hids.
  Qed.

  Lemma database_key_space_pow2 : forall count arity,
    ((count + 1) ^ N.of_nat arity <=
      N.of_nat (2 ^ (arity * (N.to_nat (N.log2 count) + 1))))%N.
  Proof.
    intros count arity.
    assert (Hbase :
      (count + 1 <= N.of_nat (2 ^ (N.to_nat (N.log2 count) + 1)))%N).
    { destruct count as [| p].
      - cbn. lia.
      - pose proof (proj2 (N.log2_spec (Npos p) ltac:(lia))) as Hlog.
        replace (N.succ (N.log2 (Npos p))) with
          (N.log2 (Npos p) + 1)%N in Hlog by lia.
        rewrite Nat2N.inj_pow, Nat2N.inj_add, N2Nat.id.
        lia. }
    replace (arity * (N.to_nat (N.log2 count) + 1)) with
      ((N.to_nat (N.log2 count) + 1) * arity) by lia.
    rewrite Nat.pow_mul_r, Nat2N.inj_pow.
    apply N.pow_le_mono_l. exact Hbase.
  Qed.

  Lemma database_losing_path_depth : forall count arity weight first,
    (N.of_nat (2 ^ first) <= weight)%N ->
    (2 * weight <= (count + 1) ^ N.of_nat arity)%N ->
    first < arity * (N.to_nat (N.log2 count) + 1).
  Proof.
    intros count arity weight first Hpath Hdouble.
    set (budget := arity * (N.to_nat (N.log2 count) + 1)).
    pose proof (database_key_space_pow2 count arity) as Hcapacity.
    fold budget in Hcapacity.
    assert (Hpower_positive : (0 < N.of_nat (2 ^ budget))%N).
    { pose proof (Nat.pow_nonzero 2 budget ltac:(lia)). lia. }
    destruct (Nat.lt_ge_cases first budget) as [Hsmall | Hlarge];
      [exact Hsmall |].
    assert (Hpower : (N.of_nat (2 ^ budget) <= N.of_nat (2 ^ first))%N).
    { assert (2 ^ budget <= 2 ^ first) by
        (apply Nat.pow_le_mono_r; lia). lia. }
    nia.
  Qed.

  (** Historical keys in one root component have the same value positions. *)
  Definition database_history_key_shape (db : t) : Prop :=
    forall f k key r g args other s,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
        Some (other, s) ->
      row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) =
      row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db) ->
      row_key_shape k = row_key_shape args.

  (** Each stored history code encodes the label beside it. *)
  Definition database_history_codes_valid (db : t) : Prop :=
    forall code f k id,
      PTrieCode.get code (row_history (db_row_store db)) = Some ((f, k), id) ->
      code = db_row_code f k.

  (** Every identifier in a historical key was allocated when recorded. *)
  Definition database_history_key_ids_bounded (db : t) : Prop :=
    forall code f k id,
      PTrieCode.get code (row_history (db_row_store db)) = Some ((f, k), id) ->
      forall i, In (Id i) k -> allocated db i.

  Definition database_row_weights_positive (db : t) : Prop :=
    forall r n,
      PTrieCode.get r (row_weights (db_row_store db)) = Some n -> (1 <= n)%N.

  (** A history identifier belongs to a row-link component. *)
  Definition database_history_connected (db : t) (a b : positive) : Prop :=
    clos_refl_sym_trans positive
      (fun x y => PTrieCode.get x (row_links (db_row_store db)) = Some y) a b.

  (** Each root weight is charged to distinct historical row codes in its component. *)
  Definition database_row_weight_conserved (db : t) : Prop :=
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      let root := row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) in
      exists codes : list positive,
        NoDup codes /\
        (N.to_nat (match PTrieCode.get root (row_weights (db_row_store db)) with
          | Some n => n | None => 1%N end) <= length codes)%nat /\
        Forall (fun code => exists label id,
          PTrieCode.get code (row_history (db_row_store db)) = Some (label, id) /\
          database_history_connected db id root) codes.

  Definition database_owned_ok (db : t) : Prop :=
    database_row_store_ok db /\ database_history_alignment db /\
    database_active_history_coherent db /\ database_history_root_owner db /\
    database_history_key_shape db /\ database_history_codes_valid db /\
    database_history_key_ids_bounded db /\
    database_row_weight_conserved db /\ database_row_weights_positive db.

  Lemma database_row_weight_conserved_entry : forall db,
    database_row_weight_conserved db -> forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      exists codes : list positive,
        NoDup codes /\
        (N.to_nat (match PTrieCode.get
          (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
            (db_row_store db)) (row_weights (db_row_store db)) with
          | Some n => n | None => 1%N end) <= length codes)%nat /\
        Forall (fun code => exists label id,
          PTrieCode.get code (row_history (db_row_store db)) = Some (label, id) /\
          database_history_connected db id
            (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
              (db_row_store db))) codes.
  Proof.
    exact (fun db Hconserved => Hconserved).
  Qed.

  Lemma database_history_root_owner_entry : forall db,
    database_history_root_owner db -> forall f k key r g args other s,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
        Some (other, s) ->
      row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) =
      row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db) -> f = g.
  Proof.
    exact (fun db Howner => Howner).
  Qed.

  Lemma database_history_alignment_entry : forall db,
    database_history_alignment db -> forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      (forall i, In (Id i) k -> repr db i = i) ->
      db_locate f k db = Some k.
  Proof.
    exact (fun db Halign f k key r Hentry Hcanonical =>
      Halign f k key r Hentry Hcanonical).
  Qed.

  Lemma database_row_store_labels : forall db, database_row_store_ok db ->
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      key = (f, k).
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore. tauto.
  Qed.

  Lemma database_row_store_link_range : forall db,
    database_row_store_ok db ->
    forall r p, PTrieCode.get r (row_links (db_row_store db)) = Some p ->
      (r < row_fresh (db_row_store db))%positive /\
      (p < row_fresh (db_row_store db))%positive.
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore. tauto.
  Qed.

  Lemma database_row_store_future_links : forall db,
    database_row_store_ok db ->
    forall r, (row_fresh (db_row_store db) <= r)%positive ->
      PTrieCode.get r (row_links (db_row_store db)) = None.
  Proof.
    intros db Hstore r Hfuture.
    destruct (PTrieCode.get r (row_links (db_row_store db))) as [p |] eqn:Hlink;
      [| reflexivity].
    destruct (database_row_store_link_range db Hstore r p Hlink) as [Hrange _].
    lia.
  Qed.

  Lemma database_row_store_history_range : forall db,
    database_row_store_ok db ->
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      (r < row_fresh (db_row_store db))%positive.
  Proof.
    intros db Hstore f k key r Hget.
    unfold database_row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & Hcounter & _).
    exact (proj1 (Hcounter f k key r Hget)).
  Qed.

  Lemma database_row_store_history_counter : forall db,
    database_row_store_ok db ->
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      (r < row_fresh (db_row_store db))%positive /\
      (match PTrieCode.get r (row_links (db_row_store db)) with
       | Some parent => parent | None => r end < row_fresh (db_row_store db))%positive /\
      In (row_fresh (db_row_store db)) (db_index_counters db).
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore. tauto.
  Qed.

  Lemma database_row_store_depth : forall db,
    database_row_store_ok db ->
    forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      exists d, d <= length k * (N.to_nat (N.log2 (ids db)) + 1) /\
        (let parent current :=
          match PTrieCode.get current (row_links (db_row_store db)) with
          | Some p => p | None => current end in
         parent (Nat.iter d parent r) = Nat.iter d parent r) /\
        db_locate f k db =
          PTrieCode.get
            (Nat.iter d (fun current =>
              match PTrieCode.get current (row_links (db_row_store db)) with
              | Some p => p | None => current end) r)
            (row_keys (db_row_store db)).
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & _ & _ & Hdepth & _).
    exact Hdepth.
  Qed.

  Lemma database_row_store_depth_of_store : forall db,
    database_row_store_ok db -> database_row_store_depth_ok db.
  Proof.
    intros db Hstore.
    exact (database_row_store_depth db Hstore).
  Qed.

  Lemma database_row_store_size : forall db,
    database_row_store_ok db ->
    forall f k key r d,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      (let parent current :=
        match PTrieCode.get current (row_links (db_row_store db)) with
        | Some p => p | None => current end in
       parent (Nat.iter d parent r) = Nat.iter d parent r) ->
      (match PTrieCode.get
        (Nat.iter d (fun current =>
          match PTrieCode.get current (row_links (db_row_store db)) with
          | Some p => p | None => current end) r)
        (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end <=
       (ids db + 1) ^ N.of_nat (length k))%N.
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore.
    destruct Hstore as (_ & _ & _ & _ & _ & _ & Hgroup & _).
    exact Hgroup.
  Qed.

  Lemma db_locate_same_store_ids : forall db db' f k,
    db_row_store db' = db_row_store db -> ids db' = ids db ->
    db_locate f k db' = db_locate f k db.
  Proof.
    intros db db' f k Hstore Hids. unfold db_locate.
    rewrite Hstore. unfold ids in Hids. now rewrite Hids.
  Qed.

  Lemma row_root_same_links : forall fuel r store store',
    row_links store = row_links store' ->
    row_root fuel r store = row_root fuel r store'.
  Proof.
    induction fuel as [| fuel IH]; intros r store store' Hlinks; [reflexivity |].
    cbn [row_root]. rewrite Hlinks.
    destruct (PTrieCode.get r (row_links store')) as [parent |]; [| reflexivity].
    destruct (Pos.eqb parent r); [reflexivity |].
    apply IH. exact Hlinks.
  Qed.

  Lemma db_locate_same_core : forall db db' f k,
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    row_keys (db_row_store db') = row_keys (db_row_store db) ->
    ids db' = ids db -> db_locate f k db' = db_locate f k db.
  Proof.
    intros db db' f k Hhistory Hlinks Hkeys Hids.
    unfold db_locate. rewrite Hhistory.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |]; [| reflexivity].
    unfold ids in Hids. rewrite Hids.
    rewrite (row_root_same_links _ _ _ _ Hlinks). now rewrite Hkeys.
  Qed.

  Lemma database_history_alignment_transport : forall db db',
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    row_keys (db_row_store db') = row_keys (db_row_store db) ->
    ids db' = ids db -> db_forest db' = db_forest db ->
    database_history_alignment db -> database_history_alignment db'.
  Proof.
    intros db db' Hhistory Hlinks Hkeys Hids Hforest Halign.
    intros f k key r Hentry Hcanonical.
    rewrite (db_locate_same_core db db' f k Hhistory Hlinks Hkeys Hids).
    apply (database_history_alignment_entry db Halign f k key r).
    - now rewrite <- Hhistory.
    - intros i Hin. specialize (Hcanonical i Hin).
      unfold repr in Hcanonical |- *. now rewrite Hforest in Hcanonical.
  Qed.

  Lemma database_row_store_ok_transport : forall db db',
    db_row_store db' = db_row_store db ->
    db_nuses db' = db_nuses db ->
    ids db' = ids db ->
    incl (db_index_counters db) (db_index_counters db') ->
    incl (db_written_cells db) (db_written_cells db') ->
    database_row_store_ok db -> database_row_store_ok db'.
  Proof.
    intros db db' Hstore Hnuses Hids Hcounters Hwritten Hbase.
    unfold database_row_store_ok in Hbase |- *.
    destruct Hbase as
      (Hlinks & Huses & Hcount & Hcounter & Hcells & Hdepth & Hsize &
        Hmap & Hlabels & Hrange).
    rewrite Hstore, Hnuses, Hids.
    split; [exact Hlinks |]. split; [exact Huses |]. split; [exact Hcount |].
    split.
    - intros f k key r Hget.
      destruct (Hcounter f k key r Hget) as [Hrow [Hparent Hfresh]].
      repeat split; try assumption. now apply Hcounters.
    - split.
      + intros x f k c Huse Hcell. apply Hwritten.
        exact (Hcells x f k c Huse Hcell).
      + split.
        * intros f k key r Hget.
          destruct (Hdepth f k key r Hget) as [d [Hbound [Hroot Hcurrent]]].
          exists d. split; [exact Hbound |]. split; [exact Hroot |].
          rewrite (db_locate_same_store_ids db db' f k Hstore Hids).
          exact Hcurrent.
        * split; [exact Hsize |]. split; [exact Hmap |].
          split; [exact Hlabels | exact Hrange].
  Qed.

  Lemma database_row_store_uses_history : forall db,
    database_row_store_ok db ->
    forall x f k, In (f, k) (DatabaseUses.bucket x (row_uses (db_row_store db))) ->
      exists r, PTrieCode.get (db_row_code f k)
        (row_history (db_row_store db)) = Some ((f, k), r).
  Proof.
    intros db Hstore. unfold database_row_store_ok in Hstore. tauto.
  Qed.

  Lemma ensure_row_identity_labels : forall db f k,
    database_row_store_ok db ->
    forall g args key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r) ->
      key = (g, args).
  Proof.
    intros db f k Hstore g args key r Hget.
    pose proof (database_row_store_labels db Hstore) as Hlabels.
    unfold ensure_row_identity in Hget.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [old |] eqn:Hprior.
    - exact (Hlabels g args key r Hget).
    - cbn [database_set_index_counters database_set_row_store db_row_store
        row_history] in Hget.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
      + change (RowKeys.encode (g, args) = RowKeys.encode (f, k)) in Hsame.
        apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
        rewrite PTrie.get_set_same in Hget. injection Hget as <- _. reflexivity.
      + rewrite PTrie.get_set_other in Hget by exact Hother.
        exact (Hlabels g args key r Hget).
  Qed.

  Lemma ensure_row_identity_history_old : forall db f k g args key r,
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
      Some (key, r) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r).
  Proof.
    intros db f k g args key r Hget.
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [old |] eqn:Hprior; [exact Hget |].
    cbn [database_set_index_counters database_set_row_store db_row_store row_history].
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
    - rewrite Hsame in Hget. congruence.
    - rewrite PTrie.get_set_other by exact Hother. exact Hget.
  Qed.

  Lemma ensure_row_identity_history_other : forall db f k g args,
    (g, args) <> (f, k) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (ensure_row_identity f k db))) =
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)).
  Proof.
    intros db f k g args Hother. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |]; [reflexivity |].
    cbn [database_set_index_counters database_set_row_store db_row_store row_history].
    rewrite PTrie.get_set_other; [reflexivity |].
    intro Hcode. apply Hother. apply RowKeys.encode_inj. exact Hcode.
  Qed.

  Lemma ensure_row_identity_raw_history_old : forall db f k code key r,
    PTrieCode.get code (row_history (db_row_store db)) = Some (key, r) ->
    PTrieCode.get code
      (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r).
  Proof.
    intros db f k code key r Hget.
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior; [exact Hget |].
    cbn [database_set_index_counters database_set_row_store db_row_store row_history].
    destruct (Pos.eq_dec code (db_row_code f k)) as [Hsame | Hother].
    - rewrite Hsame in Hget. congruence.
    - rewrite PTrie.get_set_other by exact Hother. exact Hget.
  Qed.

  Lemma ensure_row_identity_recorded_old : forall db f k r,
    In r (map (fun binding => snd (snd binding))
      (PTrieCode.elements (row_history (db_row_store db)))) ->
    In r (map (fun binding => snd (snd binding))
      (PTrieCode.elements (row_history (db_row_store (ensure_row_identity f k db))))).
  Proof.
    intros db f k r Hin.
    apply in_map_iff in Hin as [[code [key prior]] [Heq Helem]].
    cbn [snd] in Heq. subst prior.
    apply PTrie.elements_spec in Helem.
    apply in_map_iff. exists (code, (key, r)). split; [reflexivity |].
    apply PTrie.elements_spec.
    now apply ensure_row_identity_raw_history_old.
  Qed.

  Lemma ensure_row_identity_history_new : forall db f k,
    database_row_store_ok db ->
    exists r, PTrieCode.get (db_row_code f k)
      (row_history (db_row_store (ensure_row_identity f k db))) = Some ((f, k), r).
  Proof.
    intros db f k Hstore.
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hprior.
    - pose proof (database_row_store_labels db Hstore f k key r Hprior) as ->.
      exists r. exact Hprior.
    - exists (row_fresh (db_row_store db)).
      cbn [database_set_index_counters database_set_row_store db_row_store row_history].
      now rewrite PTrie.get_set_same.
  Qed.

  Lemma ensure_row_identity_history_range : forall db f k,
    database_row_store_ok db ->
    forall g args key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r) ->
      (r < row_fresh (db_row_store (ensure_row_identity f k db)))%positive.
  Proof.
    intros db f k Hstore g args key r Hget.
    unfold ensure_row_identity in Hget |- *.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior.
    - exact (database_row_store_history_range db Hstore g args key r Hget).
    - cbn [database_set_index_counters database_set_row_store db_row_store
        row_history row_fresh] in Hget |- *.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
      + rewrite Hsame, PTrie.get_set_same in Hget. inversion Hget; subst. lia.
      + rewrite PTrie.get_set_other in Hget by exact Hother.
        pose proof (database_row_store_history_range db Hstore g args key r Hget).
        lia.
  Qed.

  Lemma ensure_row_identity_history_counter : forall db f k,
    database_row_store_ok db ->
    forall g args key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r) ->
      let store := db_row_store (ensure_row_identity f k db) in
      (r < row_fresh store)%positive /\
      (match PTrieCode.get r (row_links store) with
       | Some parent => parent | None => r end < row_fresh store)%positive /\
      In (row_fresh store) (db_index_counters (ensure_row_identity f k db)).
  Proof.
    intros db f k Hstore g args key r Hget.
    unfold ensure_row_identity in Hget |- *.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior.
    - exact (database_row_store_history_counter db Hstore g args key r Hget).
    - cbn [database_set_index_counters database_set_row_store db_row_store
        row_history row_links row_fresh db_index_counters] in Hget |- *.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
      + rewrite Hsame, PTrie.get_set_same in Hget. inversion Hget; subst.
        split; [lia |]. split.
        * rewrite (database_row_store_future_links db Hstore) by apply Pos.le_refl.
          lia.
        * now left.
      + rewrite PTrie.get_set_other in Hget by exact Hother.
        destruct (database_row_store_history_counter db Hstore g args key r Hget)
          as [Hid [Hparent Hcounter]].
        split; [lia |]. split; [lia | now left].
  Qed.

  Lemma register_row_uses_history : forall db f k o g args,
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (register_row_uses f k o db))) =
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (ensure_row_identity f k db))).
  Proof.
    intros db f k o g args.
    unfold register_row_uses.
    reflexivity.
  Qed.

  Lemma register_row_uses_fresh : forall db f k o,
    row_fresh (db_row_store (register_row_uses f k o db)) =
      row_fresh (db_row_store (ensure_row_identity f k db)).
