  (** Repointing a root preserves a lookup when both affected labels agree. *)
  Lemma row_root_link_lookup : forall fuel r store store' loser winner ck k,
    row_links store' = PTrieCode.set loser winner (row_links store) ->
    row_keys store' = PTrieCode.set winner ck (row_keys store) ->
    loser <> winner ->
    (match PTrieCode.get loser (row_links store) with
     | Some parent => parent | None => loser end) = loser ->
    (match PTrieCode.get winner (row_links store') with
     | Some parent => parent | None => winner end) = winner ->
    PTrieCode.get (row_root fuel r store) (row_keys store) = Some k ->
    (row_root fuel r store = loser \/ row_root fuel r store = winner -> k = ck) ->
    PTrieCode.get (row_root fuel r store') (row_keys store') = Some k.
  Proof.
    intros fuel r store store' loser winner ck k Hlinks Hkeys Hneq Hloser Hwinner
      Hlookup Haffected.
    destruct (Pos.eq_dec (row_root fuel r store) loser) as [Hsource | Hsource].
    - assert (Hkey : k = ck) by (apply Haffected; now left). subst k.
      destruct (row_root_link_two_roots fuel r store store' loser winner
        Hlinks Hneq Hloser Hwinner Hsource) as [Hroot | Hroot];
        rewrite Hroot, Hkeys.
      + rewrite PTrie.get_set_other by exact Hneq.
        rewrite Hsource in Hlookup. exact Hlookup.
      + apply PTrie.get_set_same.
    - assert (Hdifferent : loser <> row_root fuel r store).
      { intro Heq. apply Hsource. symmetry. exact Heq. }
      rewrite (row_root_link_unaffected fuel r store store' loser winner
        (row_root fuel r store) Hlinks Hdifferent Hloser eq_refl).
      rewrite Hkeys.
      destruct (Pos.eq_dec (row_root fuel r store) winner) as [Htarget | Htarget].
      + rewrite Htarget, PTrie.get_set_same.
        f_equal. symmetry. apply Haffected. now right.
      + rewrite PTrie.get_set_other by exact Htarget. exact Hlookup.
  Qed.

  Lemma row_root_relabel_lookup : forall fuel r store store' root ck k,
    row_links store' = row_links store ->
    row_keys store' = PTrieCode.set root ck (row_keys store) ->
    PTrieCode.get (row_root fuel r store) (row_keys store) = Some k ->
    (row_root fuel r store = root -> k = ck) ->
    PTrieCode.get (row_root fuel r store') (row_keys store') = Some k.
  Proof.
    intros fuel r store store' root ck k Hlinks Hkeys Hlookup Haffected.
    rewrite (row_root_same_links fuel r store' store Hlinks), Hkeys.
    destruct (Pos.eq_dec (row_root fuel r store) root) as [Heq | Hneq].
    - rewrite Heq, PTrie.get_set_same. now rewrite (Haffected Heq).
    - rewrite PTrie.get_set_other by exact Hneq. exact Hlookup.
  Qed.

  (** A recorded key's full lookup reaches a fixed row root. *)
  Lemma database_history_root_fixed : forall db f k key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
      Some (key, r) ->
    (match PTrieCode.get
       (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
         (db_row_store db)) (row_links (db_row_store db)) with
     | Some parent => parent
     | None => row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
         (db_row_store db)
     end) = row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
       (db_row_store db).
  Proof.
    intros db f k key r Hstore Hentry.
    destruct (database_row_store_depth db Hstore f k key r Hentry)
      as [d [Hbound [Hfixed _]]].
    rewrite (row_root_after_fixed _ d r (db_row_store db) Hbound Hfixed).
    exact Hfixed.
  Qed.
  Lemma database_two_root_weight_cardinality :
    forall db f old ck old_key old_id ck_key ck_id,
      database_row_store_ok db -> database_history_root_owner db ->
      database_history_key_shape db -> database_history_codes_valid db ->
      database_history_key_ids_bounded db ->
      database_row_weight_conserved db ->
      PTrieCode.get (db_row_code f old) (row_history (db_row_store db)) =
        Some (old_key, old_id) ->
      PTrieCode.get (db_row_code f ck) (row_history (db_row_store db)) =
        Some (ck_key, ck_id) ->
      row_key_shape old = row_key_shape ck ->
      let source_root := row_root
        (length old * (N.to_nat (N.log2 (ids db)) + 1)) old_id
        (db_row_store db) in
      let dest_root := row_root
        (length ck * (N.to_nat (N.log2 (ids db)) + 1)) ck_id
        (db_row_store db) in
      source_root <> dest_root ->
      (match PTrieCode.get source_root (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end +
       match PTrieCode.get dest_root (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end <=
       (ids db + 1) ^ N.of_nat (length old))%N.
  Proof.
    intros db f old ck old_key old_id ck_key ck_id Hstore Howner Hshape
      Hvalid Hbounded Hconserved Hsource Hdest Hbridge source_root dest_root
      Hdifferent.
    destruct (Hconserved f old old_key old_id Hsource) as
      [source_codes [Hsource_distinct [Hsource_count Hsource_members]]].
    destruct (Hconserved f ck ck_key ck_id Hdest) as
      [dest_codes [Hdest_distinct [Hdest_count Hdest_members]]].
    assert (Hsource_fixed :
      (match PTrieCode.get source_root (row_links (db_row_store db)) with
       | Some p => p | None => source_root end) = source_root).
    { exact (database_history_root_fixed db f old old_key old_id
        Hstore Hsource). }
    assert (Hdest_fixed :
      (match PTrieCode.get dest_root (row_links (db_row_store db)) with
       | Some p => p | None => dest_root end) = dest_root).
    { exact (database_history_root_fixed db f ck ck_key ck_id
        Hstore Hdest). }
    assert (Hdisjoint : forall code, In code source_codes ->
      ~ In code dest_codes).
    { eapply database_row_weight_codes_disjoint; eassumption. }
    assert (Hmerged_distinct : NoDup (source_codes ++ dest_codes)).
    { clear Hsource_count Hdest_count.
      revert Hsource_members Hdisjoint.
      induction Hsource_distinct as [|code rest Hnotin Hdistinct IH];
        intros Hmembers Hdisjoint; simpl; [exact Hdest_distinct |].
      constructor.
      - rewrite in_app_iff. intros [Hin | Hin].
        + exact (Hnotin Hin).
        + exact (Hdisjoint code (or_introl eq_refl) Hin).
      - apply IH.
        + exact (Forall_inv_tail Hmembers).
        + intros other Hin. apply Hdisjoint. now right. }
    assert (Hmerged_members : Forall (fun code => exists label r,
        PTrieCode.get code (row_history (db_row_store db)) = Some (label, r) /\
        (database_history_connected db r source_root \/
         database_history_connected db r dest_root))
      (source_codes ++ dest_codes)).
    { rewrite Forall_app. split;
        apply Forall_forall; intros code Hin.
      - apply Forall_forall with (x := code) in Hsource_members;
          [| exact Hin].
        destruct Hsource_members as [label [r [Hentry Hconnected]]].
        exists label, r. split; [exact Hentry | now left].
      - apply Forall_forall with (x := code) in Hdest_members;
          [| exact Hin].
        destruct Hdest_members as [label [r [Hentry Hconnected]]].
        exists label, r. split; [exact Hentry | now right]. }
    pose proof (database_history_two_components_cardinality db f old ck
      old_key old_id ck_key ck_id (source_codes ++ dest_codes)
      (database_row_store_depth_of_store db Hstore) Howner Hshape Hvalid
      Hbounded Hsource Hdest Hbridge Hmerged_distinct Hmerged_members)
      as Hcapacity.
    rewrite length_app in Hcapacity.
    rewrite <- (N2Nat.id
      ((match PTrieCode.get source_root (row_weights (db_row_store db)) with
        | Some n => n | None => 1%N end) +
       (match PTrieCode.get dest_root (row_weights (db_row_store db)) with
        | Some n => n | None => 1%N end)))%N.
    rewrite N2Nat.inj_add.
    replace ((ids db + 1) ^ N.of_nat (length old))%N with
      (N.of_nat ((S (N.to_nat (ids db))) ^ length old)).
    - subst source_root dest_root. apply time_of_nat_le. lia.
    - rewrite Nat2N.inj_pow, Nat2N.inj_succ, N2Nat.id.
      now rewrite N.add_1_r.
  Qed.


  Lemma database_losing_component_short :
    forall db f losing other losing_key losing_id other_key other_id
      g args key id,
      database_row_store_ok db -> database_row_weights_positive db ->
      database_history_root_owner db -> database_history_key_shape db ->
      database_history_codes_valid db ->
      database_history_key_ids_bounded db ->
      database_row_weight_conserved db ->
      PTrieCode.get (db_row_code f losing) (row_history (db_row_store db)) =
        Some (losing_key, losing_id) ->
      PTrieCode.get (db_row_code f other) (row_history (db_row_store db)) =
        Some (other_key, other_id) ->
      PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) =
        Some (key, id) ->
      row_key_shape losing = row_key_shape other ->
      let losing_root := row_root
        (length losing * (N.to_nat (N.log2 (ids db)) + 1)) losing_id
        (db_row_store db) in
      let other_root := row_root
        (length other * (N.to_nat (N.log2 (ids db)) + 1)) other_id
        (db_row_store db) in
      losing_root <> other_root ->
      (match PTrieCode.get losing_root (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end <=
       match PTrieCode.get other_root (row_weights (db_row_store db)) with
       | Some n => n | None => 1%N end)%N ->
      row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) id
        (db_row_store db) = losing_root ->
      exists first,
        first < length args * (N.to_nat (N.log2 (ids db)) + 1) /\
        row_root first id (db_row_store db) = losing_root.
  Proof.
    intros db f losing other losing_key losing_id other_key other_id
      g args key id Hstore Hpositive Howner Hshape Hvalid Hbounded
      Hconserved Hlosing Hother Hentry Hbridge losing_root other_root
      Hdifferent Horder Hsame.
    destruct (database_history_root_path_weight db g args key id Hstore
      Hpositive Hentry) as [first [_ [Hroot Hpower]]].
    rewrite Hsame in Hroot, Hpower.
    assert (Hlength : length losing = length args).
    { pose proof (Hshape f losing losing_key losing_id g args key id
        Hlosing Hentry (eq_sym Hsame)) as Hkey_shape.
      unfold row_key_shape in Hkey_shape.
      apply (f_equal (@length _)) in Hkey_shape.
      now repeat rewrite length_map in Hkey_shape. }
    pose proof (database_two_root_weight_cardinality db f losing other
      losing_key losing_id other_key other_id Hstore Howner Hshape Hvalid
      Hbounded Hconserved Hlosing Hother Hbridge Hdifferent) as Hsum.
    assert (Htwice :
      (2 * (match PTrieCode.get losing_root
        (row_weights (db_row_store db)) with
        | Some n => n | None => 1%N end) <=
       (ids db + 1) ^ N.of_nat (length losing))%N).
    { subst losing_root other_root. nia. }
    rewrite Hlength in Htwice.
    exists first. split.
    - eapply database_losing_path_depth; eassumption.
    - exact Hroot.
  Qed.

  Lemma database_row_store_depth_link : forall db db' loser winner,
    database_row_store_ok db ->
    ids db' = ids db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') =
      PTrieCode.set loser winner (row_links (db_row_store db)) ->
    loser <> winner ->
    (match PTrieCode.get loser (row_links (db_row_store db)) with
     | Some p => p | None => loser end) = loser ->
    (match PTrieCode.get winner (row_links (db_row_store db')) with
     | Some p => p | None => winner end) = winner ->
    (forall f k key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) ->
      row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) = loser ->
      exists first,
        first < length k * (N.to_nat (N.log2 (ids db)) + 1) /\
        row_root first r (db_row_store db) = loser) ->
    database_row_store_depth_ok db'.
  Proof.
    intros db db' loser winner Hstore Hids Hhistory Hlinks Hdifferent
      Hloser_fixed Hwinner_fixed Hshort f k key r Hentry_new.
    rewrite Hhistory in Hentry_new.
    set (fuel := length k * (N.to_nat (N.log2 (ids db)) + 1)).
    set (old_root := row_root fuel r (db_row_store db)).
    assert (Hold_fixed :
      (match PTrieCode.get old_root (row_links (db_row_store db)) with
       | Some p => p | None => old_root end) = old_root).
    { subst old_root fuel.
      exact (database_history_root_fixed db f k key r Hstore Hentry_new). }
    assert (Hnew_fixed :
      (let parent current :=
        match PTrieCode.get current (row_links (db_row_store db')) with
        | Some p => p | None => current end in
       parent (row_root fuel r (db_row_store db')) =
         row_root fuel r (db_row_store db'))).
    { destruct (Pos.eq_dec old_root loser) as [Hloses | Hother].
      - destruct (Hshort f k key r Hentry_new Hloses) as
          [first [Hfirst Hroot]].
        assert (Hnew_root : row_root fuel r (db_row_store db') = winner).
        { eapply row_root_link_after_fixed;
            [exact Hlinks | exact Hdifferent | exact Hwinner_fixed |
             exact Hroot | lia]. }
        now rewrite Hnew_root.
      - assert (Hother_direction : loser <> old_root) by congruence.
        rewrite (row_root_link_unaffected fuel r (db_row_store db)
          (db_row_store db') loser winner old_root Hlinks
          Hother_direction Hloser_fixed eq_refl).
        rewrite Hlinks.
        change (match PTrieCode.get old_root
          (PTrieCode.set loser winner (row_links (db_row_store db))) with
          | Some p => p | None => old_root end = old_root).
        rewrite PTrie.get_set_other by exact Hother.
        exact Hold_fixed. }
    exists fuel. split; [rewrite Hids; lia |].
    split.
    - cbv zeta. rewrite <- row_root_parent_iter. exact Hnew_fixed.
    - unfold ids in Hids. unfold db_locate.
      rewrite Hhistory, Hentry_new, Hids.
      now rewrite row_root_parent_iter.
  Qed.

  Lemma database_row_links_merge_ok : forall (db db' : t) loser winner,
    database_row_store_ok db -> database_row_weights_positive db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') =
      PTrieCode.set loser winner (row_links (db_row_store db)) ->
    row_weights (db_row_store db') =
      PTrieCode.set winner
        ((match PTrieCode.get loser (row_weights (db_row_store db)) with
          | Some n => n | None => 1%N end) +
         (match PTrieCode.get winner (row_weights (db_row_store db)) with
          | Some n => n | None => 1%N end))%N
        (row_weights (db_row_store db)) ->
    loser <> winner ->
    (match PTrieCode.get loser (row_links (db_row_store db)) with
     | Some p => p | None => loser end) = loser ->
    (match PTrieCode.get winner (row_links (db_row_store db)) with
     | Some p => p | None => winner end) = winner ->
    In loser (map (fun binding => snd (snd binding))
      (PTrieCode.elements (row_history (db_row_store db)))) ->
    In winner (map (fun binding => snd (snd binding))
      (PTrieCode.elements (row_history (db_row_store db)))) ->
    (match PTrieCode.get loser (row_weights (db_row_store db)) with
     | Some n => n | None => 1%N end <=
     match PTrieCode.get winner (row_weights (db_row_store db)) with
     | Some n => n | None => 1%N end)%N ->
    forall r p, PTrieCode.get r (row_links (db_row_store db')) = Some p ->
      In r (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store db')))) /\
      In p (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store db')))) /\
      (p <> r ->
        (1 <= match PTrieCode.get r (row_weights (db_row_store db')) with
         | Some n => n | None => 1%N end)%N /\
        (2 * match PTrieCode.get r (row_weights (db_row_store db')) with
         | Some n => n | None => 1%N end <=
         match PTrieCode.get p (row_weights (db_row_store db')) with
         | Some n => n | None => 1%N end)%N).
  Proof.
    intros db db' loser winner Hstore Hpositive Hhistory Hlinks Hweights
      Hdifferent Hloser_fixed Hwinner_fixed Hloser_recorded
      Hwinner_recorded Horder r p Hlink.
    unfold database_row_store_ok in Hstore.
    destruct Hstore as [Hbase_links _].
    rewrite Hlinks in Hlink.
    destruct (Pos.eq_dec r loser) as [-> | Hother].
    - rewrite PTrie.get_set_same in Hlink. injection Hlink as <-.
      rewrite Hhistory. split; [exact Hloser_recorded |].
      split; [exact Hwinner_recorded |].
      intro Hdistinct. rewrite Hweights.
      rewrite PTrie.get_set_other by exact Hdifferent.
      rewrite PTrie.get_set_same.
      assert (Hone : (1 <= match PTrieCode.get loser
        (row_weights (db_row_store db)) with
        | Some n => n | None => 1%N end)%N).
      { destruct (PTrieCode.get loser (row_weights (db_row_store db)))
          as [n |] eqn:Hget; [apply (Hpositive loser n Hget) | lia]. }
      split; nia.
    - rewrite PTrie.get_set_other in Hlink by exact Hother.
      destruct (Hbase_links r p Hlink) as [Hrecorded_r
        [Hrecorded_p Hbase_weight]].
      rewrite Hhistory. split; [exact Hrecorded_r |].
      split; [exact Hrecorded_p |].
      intro Hdistinct.
      destruct (Hbase_weight Hdistinct) as [Hone Hdouble].
      assert (Hnot_winner : r <> winner).
      { intro Heq. subst r. rewrite Hlink in Hwinner_fixed.
        cbn in Hwinner_fixed. congruence. }
      rewrite Hweights, PTrie.get_set_other by exact Hnot_winner.
      destruct (Pos.eq_dec p winner) as [-> | Hnot_parent_winner].
      + rewrite PTrie.get_set_same. split; [exact Hone | nia].
      + rewrite PTrie.get_set_other by exact Hnot_parent_winner.
        split; assumption.
  Qed.

  Lemma database_row_links_merge_range : forall (db db' : t) loser winner,
    database_row_store_ok db ->
    row_fresh (db_row_store db') = row_fresh (db_row_store db) ->
    row_links (db_row_store db') =
      PTrieCode.set loser winner (row_links (db_row_store db)) ->
    (loser < row_fresh (db_row_store db))%positive ->
    (winner < row_fresh (db_row_store db))%positive ->
    forall r p, PTrieCode.get r (row_links (db_row_store db')) = Some p ->
      (r < row_fresh (db_row_store db'))%positive /\
      (p < row_fresh (db_row_store db'))%positive.
  Proof.
    intros db db' loser winner Hstore Hfresh Hlinks Hloser Hwinner
      r p Hget.
    rewrite Hlinks in Hget. rewrite Hfresh.
    destruct (Pos.eq_dec r loser) as [-> | Hother].
    - rewrite PTrie.get_set_same in Hget. injection Hget as <-.
      split; assumption.
    - rewrite PTrie.get_set_other in Hget by exact Hother.
      exact (database_row_store_link_range db Hstore r p Hget).
  Qed.

  Lemma database_row_store_depth_same_links : forall db db',
    database_row_store_ok db -> ids db' = ids db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    database_row_store_depth_ok db'.
  Proof.
    intros db db' Hstore Hids Hhistory Hlinks f k key r Hentry.
    rewrite Hhistory in Hentry.
    set (fuel := length k * (N.to_nat (N.log2 (ids db)) + 1)).
    assert (Hfixed :
      (let parent current :=
        match PTrieCode.get current (row_links (db_row_store db')) with
        | Some p => p | None => current end in
       parent (row_root fuel r (db_row_store db')) =
         row_root fuel r (db_row_store db'))).
    { rewrite (row_root_same_links fuel r (db_row_store db')
        (db_row_store db) Hlinks), Hlinks.
      exact (database_history_root_fixed db f k key r Hstore Hentry). }
    exists fuel. split; [rewrite Hids; lia |]. split.
    - cbv zeta. rewrite <- row_root_parent_iter. exact Hfixed.
    - unfold ids in Hids. unfold db_locate.
      rewrite Hhistory, Hentry, Hids.
      now rewrite row_root_parent_iter.
  Qed.

  Lemma row_lookup_depth_mono : forall before after (k : list (cell V.t)),
    (before <= after)%N ->
    length k * (N.to_nat (N.log2 before) + 1) <=
      length k * (N.to_nat (N.log2 after) + 1).
  Proof.
    intros before after k Hbound.
    pose proof (N.log2_le_mono _ _ Hbound) as Hlog.
    apply Nat.mul_le_mono_l. nia.
  Qed.

  Lemma db_locate_ids_mono : forall db db',
    database_row_store_ok db ->
    db_row_store db' = db_row_store db ->
    (ids db <= ids db')%N ->
    forall f k, db_locate f k db' = db_locate f k db.
  Proof.
    intros db db' Hstore Hsame Hids f k.
    unfold db_locate. rewrite Hsame.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hentry; [| reflexivity].
    change (PTrieCode.get
      (row_root (length k * (N.to_nat (N.log2 (ids db')) + 1)) r (db_row_store db))
      (row_keys (db_row_store db)) =
      PTrieCode.get
        (row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r (db_row_store db))
        (row_keys (db_row_store db))).
    destruct (database_row_store_depth db Hstore f k key r Hentry)
      as [d [Hdepth [Hfixed _]]].
    assert (Hnew_depth :
      d <= length k * (N.to_nat (N.log2 (ids db')) + 1)).
    { eapply Nat.le_trans; [exact Hdepth |].
      apply row_lookup_depth_mono. exact Hids. }
    rewrite (row_root_after_fixed _ d r (db_row_store db) Hnew_depth Hfixed).
    rewrite (row_root_after_fixed _ d r (db_row_store db) Hdepth Hfixed).
    reflexivity.
  Qed.

  Lemma database_history_root_owner_ids_mono : forall db db',
    database_row_store_ok db -> database_history_root_owner db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    (ids db <= ids db')%N -> database_history_root_owner db'.
  Proof.
    intros db db' Hstore Howner Hhistory Hlinks Hids
      f k key r g args other s Hfirst Hsecond Hroots.
    rewrite Hhistory in Hfirst, Hsecond.
    assert (Hsame_root : forall name tuple label id,
      PTrieCode.get (db_row_code name tuple)
        (row_history (db_row_store db)) = Some (label, id) ->
      row_root (length tuple * (N.to_nat (N.log2 (ids db')) + 1)) id
        (db_row_store db') =
      row_root (length tuple * (N.to_nat (N.log2 (ids db)) + 1)) id
        (db_row_store db)).
    { intros name tuple label id Hentry.
      rewrite (row_root_same_links _ id (db_row_store db')
        (db_row_store db) Hlinks).
      destruct (database_row_store_depth db Hstore name tuple label id Hentry)
        as [d [Hbound [Hfixed _]]].
      assert (Hnew_bound : d <=
        length tuple * (N.to_nat (N.log2 (ids db')) + 1)).
      { eapply Nat.le_trans; [exact Hbound |].
        apply row_lookup_depth_mono. exact Hids. }
      rewrite (row_root_after_fixed _ d id (db_row_store db)
        Hnew_bound Hfixed).
      rewrite (row_root_after_fixed _ d id (db_row_store db)
        Hbound Hfixed). reflexivity. }
    rewrite (Hsame_root f k key r Hfirst) in Hroots.
    rewrite (Hsame_root g args other s Hsecond) in Hroots.
    exact (Howner f k key r g args other s Hfirst Hsecond Hroots).
  Qed.

  Lemma database_history_key_shape_ids_mono : forall db db',
    database_row_store_ok db -> database_history_key_shape db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    (ids db <= ids db')%N -> database_history_key_shape db'.
  Proof.
    intros db db' Hstore Hshape Hhistory Hlinks Hids
      f k key r g args other s Hfirst Hsecond Hroots.
    rewrite Hhistory in Hfirst, Hsecond.
    assert (Hsame_root : forall name tuple label id,
      PTrieCode.get (db_row_code name tuple)
        (row_history (db_row_store db)) = Some (label, id) ->
      row_root (length tuple * (N.to_nat (N.log2 (ids db')) + 1)) id
        (db_row_store db') =
      row_root (length tuple * (N.to_nat (N.log2 (ids db)) + 1)) id
        (db_row_store db)).
    { intros name tuple label id Hentry.
      rewrite (row_root_same_links _ id (db_row_store db')
        (db_row_store db) Hlinks).
      destruct (database_row_store_depth db Hstore name tuple label id Hentry)
        as [d [Hbound [Hfixed _]]].
      assert (Hnew_bound : d <=
        length tuple * (N.to_nat (N.log2 (ids db')) + 1)).
      { eapply Nat.le_trans; [exact Hbound |].
        apply row_lookup_depth_mono. exact Hids. }
      rewrite (row_root_after_fixed _ d id (db_row_store db)
        Hnew_bound Hfixed).
      rewrite (row_root_after_fixed _ d id (db_row_store db)
        Hbound Hfixed). reflexivity. }
    rewrite (Hsame_root f k key r Hfirst) in Hroots.
    rewrite (Hsame_root g args other s Hsecond) in Hroots.
    exact (Hshape f k key r g args other s Hfirst Hsecond Hroots).
  Qed.

  Lemma database_history_root_owner_allocate_next : forall db,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hstore Howner.
    eapply database_history_root_owner_ids_mono;
      try exact Hstore; try exact Howner; try reflexivity.
    rewrite allocate_next_ids. lia.
  Qed.

  Lemma database_history_key_shape_allocate_next : forall db,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hstore Hshape.
    eapply database_history_key_shape_ids_mono;
      try exact Hstore; try exact Hshape; try reflexivity.
    rewrite allocate_next_ids. lia.
  Qed.

  Lemma database_history_key_ids_bounded_allocate_next : forall db,
    database_history_key_ids_bounded db ->
    database_history_key_ids_bounded (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hbounded.
    eapply database_history_key_ids_bounded_transport with (db := db).
    - reflexivity.
    - rewrite allocate_next_ids. lia.
    - exact Hbounded.
  Qed.

  Lemma database_row_weight_conserved_ids_mono : forall db db',
    database_row_store_ok db -> database_row_weight_conserved db ->
    row_history (db_row_store db') = row_history (db_row_store db) ->
    row_links (db_row_store db') = row_links (db_row_store db) ->
    row_weights (db_row_store db') = row_weights (db_row_store db) ->
    (ids db <= ids db')%N -> database_row_weight_conserved db'.
  Proof.
    intros db db' Hstore Hconserved Hhistory Hlinks Hweights Hids
      f k key r Hentry.
    rewrite Hhistory in Hentry.
    destruct (Hconserved f k key r Hentry)
      as [codes [Hdistinct [Hcount Hmembers]]].
    destruct (database_row_store_depth db Hstore f k key r Hentry)
      as [d [Hbound [Hfixed _]]].
    assert (Hnew_bound : d <= length k * (N.to_nat (N.log2 (ids db')) + 1)).
    { eapply Nat.le_trans; [exact Hbound |].
      apply row_lookup_depth_mono. exact Hids. }
    assert (Hroot : row_root
      (length k * (N.to_nat (N.log2 (ids db')) + 1)) r (db_row_store db') =
      row_root (length k * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db)).
    { rewrite (row_root_same_links _ r (db_row_store db')
        (db_row_store db) Hlinks).
      rewrite (row_root_after_fixed _ d r (db_row_store db)
        Hnew_bound Hfixed).
      rewrite (row_root_after_fixed _ d r (db_row_store db)
        Hbound Hfixed). reflexivity. }
    exists codes. split; [exact Hdistinct |]. split.
    - rewrite Hroot, Hweights. exact Hcount.
    - rewrite Hroot. apply Forall_forall. intros code Hin.
      apply Forall_forall with (x := code) in Hmembers; [| exact Hin].
      destruct Hmembers as [label [id [Hget Hconnected]]].
      exists label, id. split.
      + now rewrite Hhistory.
      + eapply database_history_connected_transport; eassumption.
  Qed.

  Lemma database_row_weight_conserved_allocate_next : forall db,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hstore Hconserved.
    eapply database_row_weight_conserved_ids_mono;
      try exact Hstore; try exact Hconserved; try reflexivity.
    rewrite allocate_next_ids. lia.
  Qed.

  Lemma database_row_store_ok_ids_mono : forall db db',
    database_row_store_ok db ->
    db_row_store db' = db_row_store db -> db_nuses db' = db_nuses db ->
    (ids db <= ids db')%N ->
    incl (db_index_counters db) (db_index_counters db') ->
    incl (db_written_cells db) (db_written_cells db') ->
    database_row_store_ok db'.
  Proof.
    intros db db' Hbase Hstore Hnuses Hids Hcounters Hwritten.
    pose proof Hbase as Hsaved.
    unfold database_row_store_ok in Hbase |- *.
    destruct Hbase as
      (Hlinks & Huses & Hcount & Hcounter & Hcells & Hdepth & Hsize &
        Hmap & Hlabels & Hrange).
    rewrite Hstore, Hnuses.
    split; [exact Hlinks |]. split; [exact Huses |]. split; [exact Hcount |].
    split.
    - intros f k key r Hget.
      destruct (Hcounter f k key r Hget) as [Hrow [Hparent Hfresh]].
      repeat split; try assumption. now apply Hcounters.
    - split.
      + intros x f k c Huse Hcell. apply Hwritten.
        exact (Hcells x f k c Huse Hcell).
      + split.
        * intros f k key r Hget.
          destruct (Hdepth f k key r Hget) as [d [Hbound [Hroot Hcurrent]]].
          exists d. split.
          -- eapply Nat.le_trans; [exact Hbound |].
             apply row_lookup_depth_mono. exact Hids.
          -- split; [exact Hroot |].
             rewrite (db_locate_ids_mono db db' Hsaved Hstore Hids).
             exact Hcurrent.
        * split.
          -- intros f k key r d Hget Hroot.
             eapply N.le_trans.
             ++ exact (Hsize f k key r d Hget Hroot).
             ++ apply N.pow_le_mono_l. lia.
          -- split; [exact Hmap |].
             split; [exact Hlabels | exact Hrange].
  Qed.

  Lemma database_row_store_ok_allocate_next : forall db,
    database_row_store_ok db ->
    database_row_store_ok (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hstore.
    eapply (database_row_store_ok_ids_mono db _); try reflexivity.
    - exact Hstore.
    - rewrite allocate_next_ids. lia.
    - unfold incl. auto.
    - unfold incl. auto.
  Qed.

  Lemma database_active_history_coherent_allocate_next : forall db,
    database_row_store_ok db -> database_active_history_coherent db ->
    database_active_history_coherent (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hstore Hcoherent f k o key r Hrow Hentry.
    rewrite (db_locate_ids_mono db (allocate_id (N.succ_pos (ids db)) db)
      Hstore) by (try reflexivity; rewrite allocate_next_ids; lia).
    exact (Hcoherent f k o key r Hrow Hentry).
  Qed.

  Lemma database_history_alignment_allocate_next : forall db,
    database_wf db -> database_row_store_ok db -> database_history_alignment db ->
    database_history_alignment (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hwf Hstore Halign f k key r Hentry Hcanonical.
    rewrite (db_locate_ids_mono db (allocate_id (N.succ_pos (ids db)) db))
      by (try exact Hstore; try reflexivity; rewrite allocate_next_ids; lia).
    apply (database_history_alignment_entry db Halign f k key r).
    - exact Hentry.
    - intros i Hin. rewrite <- (allocate_next_repr db Hwf i).
      exact (Hcanonical i Hin).
  Qed.

  (** Fresh allocation retains every owned row and history invariant. *)
  Lemma database_owned_ok_allocate_next : forall db,
    database_wf db -> database_owned_ok db ->
    database_owned_ok (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hwf Howned.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive).
    unfold database_owned_ok.
    split; [apply database_row_store_ok_allocate_next; exact Hstore |].
    split; [eapply database_history_alignment_allocate_next; eassumption |].
    split; [apply database_active_history_coherent_allocate_next; assumption |].
    split; [apply database_history_root_owner_allocate_next; assumption |].
    split; [apply database_history_key_shape_allocate_next; assumption |].
    split.
    { eapply database_history_codes_valid_transport with (db := db);
        [reflexivity | exact Hvalid]. }
    split; [apply database_history_key_ids_bounded_allocate_next; exact Hbounded |].
    split; [apply database_row_weight_conserved_allocate_next; assumption |].
    apply database_row_weights_positive_allocate_next. exact Hpositive.
  Qed.

  Lemma database_one_le_pow : forall base d,
    (1 <= base)%N -> (1 <= base ^ N.of_nat d)%N.
  Proof.
    intros base d Hbase. induction d as [|remaining IH].
    - cbn. lia.
    - rewrite Nat2N.inj_succ, N.pow_succ_r by lia. nia.
  Qed.

  Lemma ensure_row_identity_ids : forall db f k,
    ids (ensure_row_identity f k db) = ids db.
  Proof.
    intros db f k. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      reflexivity.
  Qed.

  Lemma ensure_row_identity_links : forall db f k,
    row_links (db_row_store (ensure_row_identity f k db)) =
      row_links (db_row_store db).
  Proof.
    intros db f k. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      reflexivity.
  Qed.

  Lemma ensure_row_identity_uses : forall db f k,
    row_uses (db_row_store (ensure_row_identity f k db)) =
      row_uses (db_row_store db).
  Proof.
    intros db f k. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      reflexivity.
  Qed.

  Lemma ensure_row_identity_nuses : forall db f k,
    db_nuses (ensure_row_identity f k db) = db_nuses db.
  Proof.
    intros db f k. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      reflexivity.
  Qed.

  Lemma ensure_row_identity_written : forall db f k,
    db_written_cells (ensure_row_identity f k db) = db_written_cells db.
  Proof.
    intros db f k. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)));
      reflexivity.
  Qed.

  Lemma ensure_row_identity_old_root_key : forall db f k root,
    (root < row_fresh (db_row_store db))%positive ->
    PTrieCode.get root (row_keys (db_row_store (ensure_row_identity f k db))) =
      PTrieCode.get root (row_keys (db_row_store db)).
  Proof.
    intros db f k root Hbelow. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior; [reflexivity |].
    cbn [database_set_index_counters database_set_row_store db_row_store row_keys].
    apply PTrie.get_set_other. lia.
  Qed.

  Lemma ensure_row_identity_old_root_weight : forall db f k root,
    (root < row_fresh (db_row_store db))%positive ->
    PTrieCode.get root (row_weights (db_row_store (ensure_row_identity f k db))) =
      PTrieCode.get root (row_weights (db_row_store db)).
  Proof.
    intros db f k root Hbelow. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior; [reflexivity |].
    cbn [database_set_index_counters database_set_row_store db_row_store row_weights].
    apply PTrie.get_set_other. lia.
  Qed.

  Lemma ensure_row_identity_links_ok : forall db f k,
    database_row_store_ok db ->
    forall r p,
      PTrieCode.get r (row_links (db_row_store (ensure_row_identity f k db))) = Some p ->
      In r (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store (ensure_row_identity f k db))))) /\
      In p (map (fun binding => snd (snd binding))
        (PTrieCode.elements (row_history (db_row_store (ensure_row_identity f k db))))) /\
      (p <> r ->
        (1 <= match PTrieCode.get r
          (row_weights (db_row_store (ensure_row_identity f k db))) with
          | Some n => n | None => 1%N end)%N /\
        (2 * match PTrieCode.get r
          (row_weights (db_row_store (ensure_row_identity f k db))) with
          | Some n => n | None => 1%N end <=
          match PTrieCode.get p
            (row_weights (db_row_store (ensure_row_identity f k db))) with
          | Some n => n | None => 1%N end)%N).
  Proof.
    intros db f k Hstore r p Hlink.
    rewrite ensure_row_identity_links in Hlink.
    destruct (database_row_store_link_range db Hstore r p Hlink) as [Hr Hp].
    unfold database_row_store_ok in Hstore.
    destruct Hstore as [Hlinks _].
    destruct (Hlinks r p Hlink) as [Hrecorded_r [Hrecorded_p Hweights]].
    split; [now apply ensure_row_identity_recorded_old |].
    split; [now apply ensure_row_identity_recorded_old |].
    intros Hdistinct. destruct (Hweights Hdistinct) as [Hone Hdouble].
    rewrite (ensure_row_identity_old_root_weight db f k r Hr).
    rewrite (ensure_row_identity_old_root_weight db f k p Hp).
    split; assumption.
  Qed.

  Lemma ensure_row_identity_old_locate : forall db f k g args key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) = Some (key, r) ->
    db_locate g args (ensure_row_identity f k db) = db_locate g args db.
  Proof.
    intros db f k g args key r Hstore Hget.
    unfold db_locate.
    rewrite (ensure_row_identity_history_old db f k g args key r Hget), Hget.
    pose proof (ensure_row_identity_ids db f k) as Hids.
    unfold ids in Hids. rewrite Hids.
    rewrite (row_root_same_links _ r
      (db_row_store (ensure_row_identity f k db)) (db_row_store db))
      by apply ensure_row_identity_links.
    apply ensure_row_identity_old_root_key.
    apply row_root_below_fresh; [exact Hstore |].
    exact (database_row_store_history_range db Hstore g args key r Hget).
  Qed.

  Lemma ensure_row_identity_old_depth : forall db f k g args key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) = Some (key, r) ->
    exists d,
      d <= length args * (N.to_nat (N.log2 (ids (ensure_row_identity f k db))) + 1) /\
      (let parent current :=
        match PTrieCode.get current
          (row_links (db_row_store (ensure_row_identity f k db))) with
        | Some p => p | None => current end in
       parent (Nat.iter d parent r) = Nat.iter d parent r) /\
      db_locate g args (ensure_row_identity f k db) =
        PTrieCode.get
          (Nat.iter d (fun current =>
            match PTrieCode.get current
              (row_links (db_row_store (ensure_row_identity f k db))) with
            | Some p => p | None => current end) r)
          (row_keys (db_row_store (ensure_row_identity f k db))).
  Proof.
    intros db f k g args key r Hstore Hget.
    destruct (database_row_store_depth db Hstore g args key r Hget)
      as [d [Hbound [Hroot Hcurrent]]].
    exists d. rewrite ensure_row_identity_ids. split; [exact Hbound |].
    rewrite ensure_row_identity_links. split; [exact Hroot |].
    rewrite (ensure_row_identity_old_locate db f k g args key r Hstore Hget).
    rewrite ensure_row_identity_old_root_key.
    - exact Hcurrent.
    - apply row_parent_iter_below_fresh; [exact Hstore |].
      exact (database_row_store_history_range db Hstore g args key r Hget).
  Qed.

  Lemma ensure_row_identity_old_size : forall db f k g args key r d,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) = Some (key, r) ->
    (let parent current :=
      match PTrieCode.get current
        (row_links (db_row_store (ensure_row_identity f k db))) with
      | Some p => p | None => current end in
     parent (Nat.iter d parent r) = Nat.iter d parent r) ->
    (match PTrieCode.get
      (Nat.iter d (fun current =>
        match PTrieCode.get current
          (row_links (db_row_store (ensure_row_identity f k db))) with
        | Some p => p | None => current end) r)
      (row_weights (db_row_store (ensure_row_identity f k db))) with
     | Some n => n | None => 1%N end <=
     (ids (ensure_row_identity f k db) + 1) ^ N.of_nat (length args))%N.
  Proof.
    intros db f k g args key r d Hstore Hget Hroot.
    rewrite ensure_row_identity_links in Hroot |- *.
    rewrite ensure_row_identity_ids.
    rewrite ensure_row_identity_old_root_weight.
    - exact (database_row_store_size db Hstore g args key r d Hget Hroot).
    - apply row_parent_iter_below_fresh; [exact Hstore |].
      exact (database_row_store_history_range db Hstore g args key r Hget).
  Qed.

  Lemma ensure_row_identity_fresh_iter : forall db f k d,
    database_row_store_ok db ->
    Nat.iter d (fun current =>
      match PTrieCode.get current
        (row_links (db_row_store (ensure_row_identity f k db))) with
      | Some p => p | None => current end) (row_fresh (db_row_store db)) =
      row_fresh (db_row_store db).
  Proof.
    intros db f k d Hstore. apply row_parent_iter_fixed.
    rewrite ensure_row_identity_links.
    rewrite (database_row_store_future_links db Hstore) by apply Pos.le_refl.
    reflexivity.
  Qed.

  Lemma database_history_root_owner_ensure : forall db f k,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (ensure_row_identity f k db).
  Proof.
    intros db f k Hstore Howner.
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[prior prior_id] |] eqn:Hprior; [exact Howner |].
    set (fresh := row_fresh (db_row_store db)).
    set (updated := {| row_history :=
      PTrieCode.set (db_row_code f k) ((f, k), fresh)
        (row_history (db_row_store db));
      row_links := row_links (db_row_store db);
      row_weights := PTrieCode.set fresh 1%N (row_weights (db_row_store db));
      row_keys := PTrieCode.set fresh k (row_keys (db_row_store db));
      row_fresh := Pos.succ fresh;
      row_uses := row_uses (db_row_store db) |}).
    intros g args key r h other other_key s Hfirst Hsecond Hroots.
    subst updated.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history row_links ids db_runtime runtime_allocated] in *.
    rewrite (row_root_same_links _ r _ (db_row_store db)) in Hroots
      by reflexivity.
    rewrite (row_root_same_links _ s _ (db_row_store db)) in Hroots
      by reflexivity.
    unfold ids in Hroots.
    cbn [database_set_index_counters database_set_row_store db_runtime
      runtime_allocated] in Hroots.
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
      as [Hfirst_new | Hfirst_old];
      destruct (Pos.eq_dec (db_row_code h other) (db_row_code f k))
      as [Hsecond_new | Hsecond_old].
    - apply RowKeys.encode_inj in Hfirst_new.
      apply RowKeys.encode_inj in Hsecond_new.
      injection Hfirst_new as -> ->. injection Hsecond_new as -> ->.
      reflexivity.
    - apply RowKeys.encode_inj in Hfirst_new.
      injection Hfirst_new as -> ->.
      rewrite PTrie.get_set_same in Hfirst.
      injection Hfirst as _ <-.
      rewrite PTrie.get_set_other in Hsecond by exact Hsecond_old.
      rewrite (row_root_no_link _ fresh (db_row_store db)) in Hroots.
      2: { subst fresh. apply database_row_store_future_links;
           [exact Hstore | apply Pos.le_refl]. }
      exfalso.
      pose proof (database_row_store_history_range db Hstore h other
        other_key s Hsecond) as Hbelow.
      pose proof (row_root_below_fresh db
        (length other * (N.to_nat (N.log2 (ids db)) + 1)) s Hstore Hbelow)
        as Hroot_below.
      change (fresh = row_root
        (length other * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db)) in Hroots.
      subst fresh. lia.
    - apply RowKeys.encode_inj in Hsecond_new.
      injection Hsecond_new as -> ->.
      rewrite PTrie.get_set_other in Hfirst by exact Hfirst_old.
      rewrite PTrie.get_set_same in Hsecond.
      injection Hsecond as _ <-.
      rewrite (row_root_no_link _ fresh (db_row_store db)) in Hroots.
      2: { subst fresh. apply database_row_store_future_links;
           [exact Hstore | apply Pos.le_refl]. }
      exfalso.
      pose proof (database_row_store_history_range db Hstore g args
        key r Hfirst) as Hbelow.
      pose proof (row_root_below_fresh db
        (length args * (N.to_nat (N.log2 (ids db)) + 1)) r Hstore Hbelow)
        as Hroot_below.
      change (row_root
        (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) = fresh) in Hroots.
      subst fresh. lia.
    - rewrite PTrie.get_set_other in Hfirst by exact Hfirst_old.
      rewrite PTrie.get_set_other in Hsecond by exact Hsecond_old.
      exact (Howner g args key r h other other_key s Hfirst Hsecond Hroots).
  Qed.

  Lemma database_history_key_shape_ensure : forall db f k,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape (ensure_row_identity f k db).
  Proof.
    intros db f k Hstore Hshape.
    unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[prior prior_id] |] eqn:Hprior; [exact Hshape |].
    set (fresh := row_fresh (db_row_store db)).
    set (updated := {| row_history :=
      PTrieCode.set (db_row_code f k) ((f, k), fresh)
        (row_history (db_row_store db));
      row_links := row_links (db_row_store db);
      row_weights := PTrieCode.set fresh 1%N (row_weights (db_row_store db));
      row_keys := PTrieCode.set fresh k (row_keys (db_row_store db));
      row_fresh := Pos.succ fresh;
      row_uses := row_uses (db_row_store db) |}).
    intros g args key r h other other_key s Hfirst Hsecond Hroots.
    subst updated.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history row_links ids db_runtime runtime_allocated] in *.
    rewrite (row_root_same_links _ r _ (db_row_store db)) in Hroots
      by reflexivity.
    rewrite (row_root_same_links _ s _ (db_row_store db)) in Hroots
      by reflexivity.
    unfold ids in Hroots.
    cbn [database_set_index_counters database_set_row_store db_runtime
      runtime_allocated] in Hroots.
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
      as [Hfirst_new | Hfirst_old];
      destruct (Pos.eq_dec (db_row_code h other) (db_row_code f k))
      as [Hsecond_new | Hsecond_old].
    - apply RowKeys.encode_inj in Hfirst_new.
      apply RowKeys.encode_inj in Hsecond_new.
      injection Hfirst_new as -> ->. injection Hsecond_new as -> ->.
      reflexivity.
    - apply RowKeys.encode_inj in Hfirst_new.
      injection Hfirst_new as -> ->.
      rewrite PTrie.get_set_same in Hfirst.
      injection Hfirst as _ <-.
      rewrite PTrie.get_set_other in Hsecond by exact Hsecond_old.
      rewrite (row_root_no_link _ fresh (db_row_store db)) in Hroots.
      2: { subst fresh. apply database_row_store_future_links;
           [exact Hstore | apply Pos.le_refl]. }
      exfalso.
      pose proof (database_row_store_history_range db Hstore h other
        other_key s Hsecond) as Hbelow.
      pose proof (row_root_below_fresh db
        (length other * (N.to_nat (N.log2 (ids db)) + 1)) s Hstore Hbelow)
        as Hroot_below.
      change (fresh = row_root
        (length other * (N.to_nat (N.log2 (ids db)) + 1)) s
        (db_row_store db)) in Hroots.
      subst fresh. lia.
    - apply RowKeys.encode_inj in Hsecond_new.
      injection Hsecond_new as -> ->.
      rewrite PTrie.get_set_other in Hfirst by exact Hfirst_old.
      rewrite PTrie.get_set_same in Hsecond.
      injection Hsecond as _ <-.
      rewrite (row_root_no_link _ fresh (db_row_store db)) in Hroots.
      2: { subst fresh. apply database_row_store_future_links;
           [exact Hstore | apply Pos.le_refl]. }
      exfalso.
      pose proof (database_row_store_history_range db Hstore g args
        key r Hfirst) as Hbelow.
      pose proof (row_root_below_fresh db
        (length args * (N.to_nat (N.log2 (ids db)) + 1)) r Hstore Hbelow)
        as Hroot_below.
      change (row_root
        (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
        (db_row_store db) = fresh) in Hroots.
      subst fresh. lia.
    - rewrite PTrie.get_set_other in Hfirst by exact Hfirst_old.
      rewrite PTrie.get_set_other in Hsecond by exact Hsecond_old.
      exact (Hshape g args key r h other other_key s Hfirst Hsecond Hroots).
  Qed.

  Lemma database_history_codes_valid_ensure : forall db f k,
    database_history_codes_valid db ->
    database_history_codes_valid (ensure_row_identity f k db).
  Proof.
    intros db f k Hvalid. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[label id] |] eqn:Hprior; [exact Hvalid |].
    intros code g args r Hentry.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history] in Hentry.
    destruct (Pos.eq_dec code (db_row_code f k)) as [Heq | Hother].
    - subst code. rewrite PTrie.get_set_same in Hentry.
      inversion Hentry. subst. reflexivity.
    - rewrite PTrie.get_set_other in Hentry by exact Hother.
      exact (Hvalid code g args r Hentry).
  Qed.

  Lemma database_row_weights_positive_ensure : forall db f k,
    database_row_weights_positive db ->
    database_row_weights_positive (ensure_row_identity f k db).
  Proof.
    intros db f k Hpositive. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[label id] |]; [exact Hpositive |].
    intros r n Hentry.
    cbn [database_set_index_counters database_set_row_store db_row_store row_weights]
      in Hentry.
    destruct (Pos.eq_dec r (row_fresh (db_row_store db))) as [Heq | Hneq].
    - subst r. rewrite PTrie.get_set_same in Hentry.
      injection Hentry as <-. lia.
    - rewrite PTrie.get_set_other in Hentry by exact Hneq.
      exact (Hpositive r n Hentry).
  Qed.

  Lemma database_row_weights_positive_register : forall db f k o,
    database_row_weights_positive db ->
    database_row_weights_positive (register_row_uses f k o db).
  Proof.
    intros db f k o Hpositive.
    eapply database_row_weights_positive_transport with
      (db := ensure_row_identity f k db).
    - apply register_row_uses_weights.
    - apply database_row_weights_positive_ensure. exact Hpositive.
  Qed.

  Lemma database_row_weights_positive_row_replace : forall db f k previous o,
    database_row_weights_positive db ->
    database_row_weights_positive (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hpositive; unfold row_replace;
      apply database_row_weights_positive_register;
      apply database_row_weights_positive_row_write;
      repeat apply database_row_weights_positive_slots_update;
      exact Hpositive.
  Qed.

  Lemma database_history_key_ids_bounded_ensure : forall db f k,
    database_history_key_ids_bounded db ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_history_key_ids_bounded (ensure_row_identity f k db).
  Proof.
    intros db f k Hbounded Hinput. unfold ensure_row_identity.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[label id] |] eqn:Hprior; [exact Hbounded |].
    intros code g args r Hentry i Hin.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history ids db_runtime runtime_allocated] in Hentry |- *.
    destruct (Pos.eq_dec code (db_row_code f k)) as [Heq | Hother].
    - subst code. rewrite PTrie.get_set_same in Hentry.
      inversion Hentry. subst. apply Hinput. exact Hin.
    - rewrite PTrie.get_set_other in Hentry by exact Hother.
      exact (Hbounded code g args r Hentry i Hin).
  Qed.

  Lemma database_row_weight_conserved_ensure : forall db f k,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (ensure_row_identity f k db).
  Proof.
    intros db f k Hstore Hconserved.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[prior prior_id] |] eqn:Hprior.
    - unfold ensure_row_identity. now rewrite Hprior.
    - intros g args key r Hentry.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
        as [Hsame | Hother].
      + apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
        unfold ensure_row_identity in Hentry |- *. rewrite Hprior in Hentry |- *.
        cbn [database_set_index_counters database_set_row_store db_row_store
          row_history row_links row_weights ids db_runtime runtime_allocated]
          in Hentry |- *.
        rewrite PTrie.get_set_same in Hentry.
        injection Hentry as _ <-.
        rewrite (row_root_same_links _ (row_fresh (db_row_store db)) _
          (db_row_store db)) by reflexivity.
        rewrite (row_root_no_link _ (row_fresh (db_row_store db))
          (db_row_store db)).
        2: { apply database_row_store_future_links;
             [exact Hstore | apply Pos.le_refl]. }
        rewrite PTrie.get_set_same.
        exists [db_row_code f k]. split; [constructor; [simpl; tauto | constructor] |].
        split; [cbn; lia |]. constructor; [| constructor].
        exists (f, k), (row_fresh (db_row_store db)). split.
        * apply PTrie.get_set_same.
        * unfold database_history_connected. apply rst_refl.
      + assert (Hold : PTrieCode.get (db_row_code g args)
          (row_history (db_row_store db)) = Some (key, r)).
        { rewrite <- (ensure_row_identity_history_other db f k g args).
          - exact Hentry.
          - intro Heq. inversion Heq; subst. contradiction. }
        destruct (Hconserved g args key r Hold)
          as [codes [Hdistinct [Hcount Hmembers]]].
        exists codes. split; [exact Hdistinct |].
        assert (Hroot : row_root
          (length args * (N.to_nat (N.log2 (ids (ensure_row_identity f k db))) + 1))
          r (db_row_store (ensure_row_identity f k db)) =
          row_root (length args * (N.to_nat (N.log2 (ids db)) + 1)) r
            (db_row_store db)).
        { rewrite ensure_row_identity_ids.
          apply row_root_same_links. apply ensure_row_identity_links. }
        split.
        * rewrite Hroot.
          rewrite (ensure_row_identity_old_root_weight db f k _).
          -- exact Hcount.
          -- apply row_root_below_fresh; [exact Hstore |].
             exact (database_row_store_history_range db Hstore g args key r Hold).
        * rewrite Hroot. apply Forall_forall. intros code Hin.
          apply Forall_forall with (x := code) in Hmembers; [| exact Hin].
          destruct Hmembers as [label [id [Hget Hconnected]]].
          exists label, id. split.
          -- apply ensure_row_identity_raw_history_old. exact Hget.
          -- eapply database_history_connected_transport;
               [apply ensure_row_identity_links | exact Hconnected].
  Qed.

  Lemma database_history_root_owner_slots_update : forall db add f cells,
    database_history_root_owner db ->
    database_history_root_owner (slots_update add f cells db).
  Proof.
    intros db add f cells Howner.
    eapply database_history_root_owner_transport with (db := db).
    - now rewrite slots_update_row_store.
    - now rewrite slots_update_row_store.
    - apply slots_update_ids.
    - exact Howner.
  Qed.

