  Lemma database_history_root_owner_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hstore Howner; unfold row_replace.
    - apply database_history_root_owner_register.
      + apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok.
        exact Hstore.
      + apply database_history_root_owner_row_write.
        apply database_history_root_owner_slots_update.
        apply database_history_root_owner_slots_update. exact Howner.
    - apply database_history_root_owner_register.
      + apply row_write_row_store_ok, slots_update_row_store_ok. exact Hstore.
      + apply database_history_root_owner_row_write.
        apply database_history_root_owner_slots_update. exact Howner.
  Qed.

  Lemma database_history_key_shape_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hstore Hshape; unfold row_replace.
    - apply database_history_key_shape_register.
      + apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok.
        exact Hstore.
      + apply database_history_key_shape_row_write.
        apply database_history_key_shape_slots_update.
        apply database_history_key_shape_slots_update. exact Hshape.
    - apply database_history_key_shape_register.
      + apply row_write_row_store_ok, slots_update_row_store_ok. exact Hstore.
      + apply database_history_key_shape_row_write.
        apply database_history_key_shape_slots_update. exact Hshape.
  Qed.

  Lemma database_history_codes_valid_row_replace : forall db f k previous o,
    database_history_codes_valid db ->
    database_history_codes_valid (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hvalid; unfold row_replace;
      apply database_history_codes_valid_register;
      apply database_history_codes_valid_row_write;
      repeat apply database_history_codes_valid_slots_update; exact Hvalid.
  Qed.

  Lemma database_history_key_ids_bounded_row_replace : forall db f k previous o,
    database_history_key_ids_bounded db ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_history_key_ids_bounded (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hbounded Hinput; unfold row_replace;
      apply database_history_key_ids_bounded_register.
    - apply database_history_key_ids_bounded_row_write.
      repeat apply database_history_key_ids_bounded_slots_update.
      exact Hbounded.
    - intros i Hin. unfold allocated. rewrite row_write_ids, !slots_update_ids.
      exact (Hinput i Hin).
    - apply database_history_key_ids_bounded_row_write.
      apply database_history_key_ids_bounded_slots_update. exact Hbounded.
    - intros i Hin. unfold allocated. rewrite row_write_ids, slots_update_ids.
      exact (Hinput i Hin).
  Qed.

  Lemma database_row_weight_conserved_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hstore Hconserved; unfold row_replace.
    - apply database_row_weight_conserved_register.
      + apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok.
        exact Hstore.
      + apply database_row_weight_conserved_row_write.
        apply database_row_weight_conserved_slots_update.
        apply database_row_weight_conserved_slots_update. exact Hconserved.
    - apply database_row_weight_conserved_register.
      + apply row_write_row_store_ok, slots_update_row_store_ok. exact Hstore.
      + apply database_row_weight_conserved_row_write.
        apply database_row_weight_conserved_slots_update. exact Hconserved.
  Qed.

  Lemma database_history_root_owner_row_delete : forall db f k,
    database_history_root_owner db ->
    database_history_root_owner (row_delete f k db).
  Proof.
    intros db f k Howner.
    eapply database_history_root_owner_transport with (db := db).
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - apply row_delete_ids.
    - exact Howner.
  Qed.

  Lemma database_history_key_shape_row_delete : forall db f k,
    database_history_key_shape db ->
    database_history_key_shape (row_delete f k db).
  Proof.
    intros db f k Hshape.
    eapply database_history_key_shape_transport with (db := db).
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - apply row_delete_ids.
    - exact Hshape.
  Qed.

  Lemma database_history_codes_valid_row_delete : forall db f k,
    database_history_codes_valid db ->
    database_history_codes_valid (row_delete f k db).
  Proof.
    intros db f k Hvalid.
    eapply database_history_codes_valid_transport with (db := db).
    - now rewrite row_delete_row_store.
    - exact Hvalid.
  Qed.

  Lemma database_history_key_ids_bounded_row_delete : forall db f k,
    database_history_key_ids_bounded db ->
    database_history_key_ids_bounded (row_delete f k db).
  Proof.
    intros db f k Hbounded.
    eapply database_history_key_ids_bounded_transport with (db := db).
    - now rewrite row_delete_row_store.
    - rewrite row_delete_ids. reflexivity.
    - exact Hbounded.
  Qed.

  Lemma database_row_weight_conserved_row_delete : forall db f k,
    database_row_weight_conserved db ->
    database_row_weight_conserved (row_delete f k db).
  Proof.
    intros db f k Hconserved.
    eapply database_row_weight_conserved_transport with (db := db).
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - apply row_delete_ids.
    - exact Hconserved.
  Qed.

  Lemma ensure_row_identity_new_size : forall db f k d,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = None ->
    (match PTrieCode.get
      (Nat.iter d (fun current =>
        match PTrieCode.get current
          (row_links (db_row_store (ensure_row_identity f k db))) with
        | Some p => p | None => current end) (row_fresh (db_row_store db)))
      (row_weights (db_row_store (ensure_row_identity f k db))) with
     | Some n => n | None => 1%N end <=
     (ids (ensure_row_identity f k db) + 1) ^ N.of_nat (length k))%N.
  Proof.
    intros db f k d Hstore Hnone.
    rewrite (ensure_row_identity_fresh_iter db f k d Hstore).
    unfold ensure_row_identity. rewrite Hnone.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_weights ids db_runtime runtime_allocated].
    rewrite PTrie.get_set_same.
    apply database_one_le_pow. lia.
  Qed.

  Lemma ensure_row_identity_size : forall db f k,
    database_row_store_ok db ->
    forall g args key r d,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r) ->
      (let parent current :=
        match PTrieCode.get current
          (row_links (db_row_store (ensure_row_identity f k db))) with
        | Some p => p | None => current end in
       parent (Nat.iter d parent r) = Nat.iter d parent r) ->
      (match PTrieCode.get
        (Nat.iter d (fun current =>
          match PTrieCode.get current
            (row_links (db_row_store (ensure_row_identity f k db))) with
          | Some p => p | None => current end) r)
        (row_weights (db_row_store (ensure_row_identity f k db))) with
       | Some n => n | None => 1%N end <=
       (ids (ensure_row_identity f k db) + 1) ^ N.of_nat (length args))%N.
  Proof.
    intros db f k Hstore g args key r d Hget Hroot.
    unfold ensure_row_identity in Hget.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior.
    - exact (ensure_row_identity_old_size db f k g args key r d Hstore Hget Hroot).
    - cbn [database_set_index_counters database_set_row_store db_row_store row_history]
        in Hget.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
      + change (RowKeys.encode (g, args) = RowKeys.encode (f, k)) in Hsame.
        apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
        rewrite PTrie.get_set_same in Hget. injection Hget as <- <-.
        exact (ensure_row_identity_new_size db f k d Hstore Hprior).
      + rewrite PTrie.get_set_other in Hget by exact Hother.
        exact (ensure_row_identity_old_size db f k g args key r d Hstore Hget Hroot).
  Qed.

  Lemma ensure_row_identity_new_locate : forall db f k,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = None ->
    db_locate f k (ensure_row_identity f k db) = Some k.
  Proof.
    intros db f k Hstore Hnone.
    unfold db_locate, ensure_row_identity. rewrite Hnone.
    cbn [database_set_index_counters database_set_row_store db_row_store
      row_history row_links row_keys db_runtime runtime_allocated].
    rewrite PTrie.get_set_same.
    rewrite row_root_no_link.
    - now rewrite PTrie.get_set_same.
    - apply (database_row_store_future_links db Hstore).
      apply Pos.le_refl.
  Qed.

  Lemma ensure_row_identity_new_depth : forall db f k,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = None ->
    exists d,
      d <= length k * (N.to_nat (N.log2 (ids (ensure_row_identity f k db))) + 1) /\
      (let parent current :=
        match PTrieCode.get current
          (row_links (db_row_store (ensure_row_identity f k db))) with
        | Some p => p | None => current end in
       parent (Nat.iter d parent (row_fresh (db_row_store db))) =
         Nat.iter d parent (row_fresh (db_row_store db))) /\
      db_locate f k (ensure_row_identity f k db) =
        PTrieCode.get
          (Nat.iter d (fun current =>
            match PTrieCode.get current
              (row_links (db_row_store (ensure_row_identity f k db))) with
            | Some p => p | None => current end) (row_fresh (db_row_store db)))
          (row_keys (db_row_store (ensure_row_identity f k db))).
  Proof.
    intros db f k Hstore Hnone. exists 0.
    split; [lia |]. split.
    - cbn [Nat.iter]. rewrite ensure_row_identity_links.
      rewrite (database_row_store_future_links db Hstore) by apply Pos.le_refl.
      reflexivity.
    - rewrite (ensure_row_identity_new_locate db f k Hstore Hnone).
      cbn [Nat.iter]. unfold ensure_row_identity. rewrite Hnone.
      cbn [database_set_index_counters database_set_row_store db_row_store row_keys].
      now rewrite PTrie.get_set_same.
  Qed.

  Lemma ensure_row_identity_depth : forall db f k,
    database_row_store_ok db ->
    forall g args key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (ensure_row_identity f k db))) = Some (key, r) ->
      exists d,
        d <= length args * (N.to_nat (N.log2 (ids (ensure_row_identity f k db))) + 1) /\
        (let parent current :=
          match PTrieCode.get current
            (row_links (db_row_store (ensure_row_identity f k db))) with
          | Some p => p | None => current end in
         parent (Nat.iter d parent r) = Nat.iter d parent r) /\
        db_locate g args (ensure_row_identity f k db) =
          PTrieCode.get
            (Nat.iter d (fun current =>
              match PTrieCode.get current
                (row_links (db_row_store (ensure_row_identity f k db))) with
              | Some p => p | None => current end) r)
            (row_keys (db_row_store (ensure_row_identity f k db))).
  Proof.
    intros db f k Hstore g args key r Hget.
    unfold ensure_row_identity in Hget.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [prior |] eqn:Hprior.
    - exact (ensure_row_identity_old_depth db f k g args key r Hstore Hget).
    - cbn [database_set_index_counters database_set_row_store db_row_store row_history]
        in Hget.
      destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k)) as [Hsame | Hother].
      + change (RowKeys.encode (g, args) = RowKeys.encode (f, k)) in Hsame.
        apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
        rewrite PTrie.get_set_same in Hget. injection Hget as <- <-.
        exact (ensure_row_identity_new_depth db f k Hstore Hprior).
      + rewrite PTrie.get_set_other in Hget by exact Hother.
        exact (ensure_row_identity_old_depth db f k g args key r Hstore Hget).
  Qed.

  Lemma database_row_store_ok_ensure : forall db f k,
    database_row_store_ok db -> database_row_store_ok (ensure_row_identity f k db).
  Proof.
    intros db f k Hstore.
    pose proof Hstore as Hbase.
    unfold database_row_store_ok in Hbase.
    destruct Hbase as
      (_ & Huses & Hcount & _ & Hcells & _ & _ & Hmap & _ & _).
    unfold database_row_store_ok.
    split; [apply ensure_row_identity_links_ok; exact Hstore |].
    split.
    - intros x g args Huse. rewrite ensure_row_identity_uses in Huse.
      destruct (Huses x g args Huse) as [r Hget].
      exists r. now apply ensure_row_identity_history_old.
    - split.
      + rewrite ensure_row_identity_nuses, ensure_row_identity_uses. exact Hcount.
      + split; [apply ensure_row_identity_history_counter; exact Hstore |].
        split.
        * intros x g args c Huse Hcell.
          rewrite ensure_row_identity_uses in Huse.
          rewrite ensure_row_identity_written.
          exact (Hcells x g args c Huse Hcell).
        * split; [apply ensure_row_identity_depth; exact Hstore |].
          split; [apply ensure_row_identity_size; exact Hstore |].
          split.
          -- rewrite ensure_row_identity_uses. exact Hmap.
          -- split; [apply ensure_row_identity_labels; exact Hstore |].
             apply ensure_row_identity_link_range. exact Hstore.
  Qed.

  Lemma register_row_uses_depth : forall db f k o,
    database_row_store_ok db ->
    forall g args key r,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (register_row_uses f k o db))) = Some (key, r) ->
      exists d,
        d <= length args * (N.to_nat (N.log2 (ids (register_row_uses f k o db))) + 1) /\
        (let parent current :=
          match PTrieCode.get current
            (row_links (db_row_store (register_row_uses f k o db))) with
          | Some p => p | None => current end in
         parent (Nat.iter d parent r) = Nat.iter d parent r) /\
        db_locate g args (register_row_uses f k o db) =
          PTrieCode.get
            (Nat.iter d (fun current =>
              match PTrieCode.get current
                (row_links (db_row_store (register_row_uses f k o db))) with
              | Some p => p | None => current end) r)
            (row_keys (db_row_store (register_row_uses f k o db))).
  Proof.
    intros db f k o Hstore g args key r Hget.
    rewrite register_row_uses_history_map in Hget.
    pose proof (database_row_store_ok_ensure db f k Hstore) as Hidentified.
    destruct (database_row_store_depth _ Hidentified g args key r Hget)
      as [d [Hbound [Hroot Hcurrent]]].
    exists d. rewrite register_row_uses_ids. split; [exact Hbound |].
    rewrite register_row_uses_links. split; [exact Hroot |].
    rewrite register_row_uses_locate, register_row_uses_keys.
    exact Hcurrent.
  Qed.

  Lemma register_row_uses_size : forall db f k o,
    database_row_store_ok db ->
    forall g args key r d,
      PTrieCode.get (db_row_code g args)
        (row_history (db_row_store (register_row_uses f k o db))) = Some (key, r) ->
      (let parent current :=
        match PTrieCode.get current
          (row_links (db_row_store (register_row_uses f k o db))) with
        | Some p => p | None => current end in
       parent (Nat.iter d parent r) = Nat.iter d parent r) ->
      (match PTrieCode.get
        (Nat.iter d (fun current =>
          match PTrieCode.get current
            (row_links (db_row_store (register_row_uses f k o db))) with
          | Some p => p | None => current end) r)
        (row_weights (db_row_store (register_row_uses f k o db))) with
       | Some n => n | None => 1%N end <=
       (ids (register_row_uses f k o db) + 1) ^ N.of_nat (length args))%N.
  Proof.
    intros db f k o Hstore g args key r d Hget Hroot.
    rewrite register_row_uses_history_map in Hget.
    rewrite register_row_uses_links in Hroot |- *.
    rewrite register_row_uses_weights, register_row_uses_ids.
    apply (database_row_store_size _ (database_row_store_ok_ensure db f k Hstore)
      g args key r d Hget Hroot).
  Qed.

  Lemma database_row_store_ok_register : forall db f k o,
    database_row_store_ok db ->
    (forall c, In c k -> In c (db_written_cells db)) ->
    database_row_store_ok (register_row_uses f k o db).
  Proof.
    intros db f k o Hstore Hkey.
    pose proof (database_row_store_ok_ensure db f k Hstore) as Hidentified.
    pose proof Hstore as Hbase.
    unfold database_row_store_ok in Hbase.
    destruct Hbase as (_ & _ & Hcount & _ & Hcells & _ & _ & Hmap & _ & _).
    unfold database_row_store_ok.
    split.
    - rewrite register_row_uses_history_map, register_row_uses_links,
        register_row_uses_weights.
      exact (proj1 Hidentified).
    - split; [apply register_row_uses_history_coverage; exact Hstore |].
      split.
      + change (N.to_nat (db_nuses (register_row_uses f k o db)) =
          length (uses_entries (register_row_uses f k o db))).
        apply register_row_uses_count; assumption.
      + split; [apply register_row_uses_history_counter; exact Hstore |].
        split.
        * apply register_row_uses_written_coverage; assumption.
        * split; [apply register_row_uses_depth; exact Hstore |].
          split; [apply register_row_uses_size; exact Hstore |].
          split; [apply register_row_uses_map_wf; exact Hmap |].
          split; [apply register_row_uses_labels; exact Hstore |].
          apply register_row_uses_link_range. exact Hstore.
  Qed.

  Lemma row_replace_uses_entries : forall db f k previous o x g args,
    DatabaseUseMap.wf (row_uses (db_row_store db)) ->
    (In (x, (g, args)) (uses_entries (row_replace f k previous o db)) <->
      In (x, (g, args)) (uses_entries db) \/
      In (x, (g, args)) (id_occurrences f k (k ++ option_list o))).
  Proof.
    intros db f k [before |] o x g args Hmap; unfold row_replace.
    - set (prepared := row_write f k o
        (slots_update true f (k ++ option_list o)
          (slots_update false f (k ++ option_list before) db))).
      assert (Hstore : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, !slots_update_row_store. }
      rewrite (register_row_uses_entries prepared f k o x g args).
      + unfold uses_entries. now rewrite Hstore.
      + now rewrite Hstore.
    - set (prepared := row_write f k o (slots_update true f (k ++ option_list o) db)).
      assert (Hstore : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, slots_update_row_store. }
      rewrite (register_row_uses_entries prepared f k o x g args).
      + unfold uses_entries. now rewrite Hstore.
      + now rewrite Hstore.
  Qed.

  Lemma row_replace_uses_old : forall db f k previous o x g args,
    DatabaseUseMap.wf (row_uses (db_row_store db)) ->
    uses db x (g, args) ->
    uses (row_replace f k previous o db) x (g, args).
  Proof.
    intros db f k previous o x g args Hmap Huse.
    unfold uses in *. apply (proj2
      (row_replace_uses_entries db f k previous o x g args Hmap)).
    now left.
  Qed.

  Lemma row_replace_uses_new : forall db f k previous o i,
    DatabaseUseMap.wf (row_uses (db_row_store db)) ->
    In (Id i) (k ++ option_list o) ->
    uses (row_replace f k previous o db) i (f, k).
  Proof.
    intros db f k previous o i Hmap Hin.
    unfold uses. apply (proj2
      (row_replace_uses_entries db f k previous o i f k Hmap)).
    right. apply (proj2 (id_occurrences_member f k
      (k ++ option_list o) i f k)).
    repeat split; try reflexivity. exact Hin.
  Qed.

  Lemma database_uses_history : forall db x f k,
    database_row_store_ok db -> uses db x (f, k) ->
    exists r, PTrieCode.get (db_row_code f k)
      (row_history (db_row_store db)) = Some ((f, k), r).
  Proof.
    intros db x f k Hstore Huse.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold database_row_store_ok in Hstore. tauto. }
    unfold uses in Huse. rewrite uses_entries_facts in Huse by exact Hmap.
    apply (proj1 (DatabaseUsesFacts.entries_member _ x (f, k) Hmap))
      in Huse.
    exact (database_row_store_uses_history db Hstore x f k Huse).
  Qed.

  Lemma row_replace_queue : forall db f k previous o,
    queue (row_replace f k previous o db) = queue db.
  Proof.
    intros db f k previous o. unfold queue.
    exact (row_replace_preserves _ (@runtime_queue (cell V.t) I.t)
      (fun rows state => eq_refl) (fun flag state => eq_refl)
      (fun all new counts state => eq_refl) f k previous o db).
  Qed.

  Lemma row_replace_old_locate : forall db f k previous o g args key r,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)) = Some (key, r) ->
    db_locate g args (row_replace f k previous o db) = db_locate g args db.
  Proof.
    intros db f k [before |] o g args key r Hstore Hget; unfold row_replace.
    - set (prepared := row_write f k o
        (slots_update true f (k ++ option_list o)
          (slots_update false f (k ++ option_list before) db))).
      assert (Hstore' : database_row_store_ok prepared).
      { subst prepared. apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok. exact Hstore. }
      assert (Hsame : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, !slots_update_row_store. }
      assert (Hids : ids prepared = ids db).
      { subst prepared. now rewrite row_write_ids, !slots_update_ids. }
      rewrite register_row_uses_locate.
      rewrite (ensure_row_identity_old_locate prepared f k g args key r Hstore')
        by (rewrite Hsame; exact Hget).
      apply db_locate_same_store_ids; assumption.
    - set (prepared := row_write f k o (slots_update true f (k ++ option_list o) db)).
      assert (Hstore' : database_row_store_ok prepared).
      { subst prepared. apply row_write_row_store_ok, slots_update_row_store_ok.
        exact Hstore. }
      assert (Hsame : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, slots_update_row_store. }
      assert (Hids : ids prepared = ids db).
      { subst prepared. now rewrite row_write_ids, slots_update_ids. }
      rewrite register_row_uses_locate.
      rewrite (ensure_row_identity_old_locate prepared f k g args key r Hstore')
        by (rewrite Hsame; exact Hget).
      apply db_locate_same_store_ids; assumption.
  Qed.

  Lemma row_replace_history_other : forall db f k previous o g args,
    (g, args) <> (f, k) ->
    PTrieCode.get (db_row_code g args)
      (row_history (db_row_store (row_replace f k previous o db))) =
    PTrieCode.get (db_row_code g args) (row_history (db_row_store db)).
  Proof.
    intros db f k [before |] o g args Hother; unfold row_replace.
    - rewrite register_row_uses_history_map.
      rewrite ensure_row_identity_history_other by exact Hother.
      now rewrite row_write_row_store, !slots_update_row_store.
    - rewrite register_row_uses_history_map.
      rewrite ensure_row_identity_history_other by exact Hother.
      now rewrite row_write_row_store, slots_update_row_store.
  Qed.

  Lemma row_replace_history_old : forall db f k previous o code key r,
    PTrieCode.get code (row_history (db_row_store db)) = Some (key, r) ->
    PTrieCode.get code
      (row_history (db_row_store (row_replace f k previous o db))) = Some (key, r).
  Proof.
    intros db f k [before |] o code key r Hentry; unfold row_replace;
      rewrite register_row_uses_history_map;
      apply ensure_row_identity_raw_history_old.
    - now rewrite row_write_row_store, !slots_update_row_store.
    - now rewrite row_write_row_store, slots_update_row_store.
  Qed.

  Lemma row_replace_new_locate : forall db f k previous o,
    database_row_store_ok db ->
    PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = None ->
    db_locate f k (row_replace f k previous o db) = Some k.
  Proof.
    intros db f k [before |] o Hstore Hnone; unfold row_replace.
    - set (prepared := row_write f k o
        (slots_update true f (k ++ option_list o)
          (slots_update false f (k ++ option_list before) db))).
      assert (Hstore' : database_row_store_ok prepared).
      { subst prepared. apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok. exact Hstore. }
      assert (Hsame : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, !slots_update_row_store. }
      rewrite register_row_uses_locate.
      apply ensure_row_identity_new_locate; [exact Hstore' |].
      now rewrite Hsame.
    - set (prepared := row_write f k o (slots_update true f (k ++ option_list o) db)).
      assert (Hstore' : database_row_store_ok prepared).
      { subst prepared. apply row_write_row_store_ok, slots_update_row_store_ok.
        exact Hstore. }
      assert (Hsame : db_row_store prepared = db_row_store db).
      { subst prepared. now rewrite row_write_row_store, slots_update_row_store. }
      rewrite register_row_uses_locate.
      apply ensure_row_identity_new_locate; [exact Hstore' |].
      now rewrite Hsame.
  Qed.

  Lemma row_replace_new_locate_from_alignment : forall db f k previous o,
    database_row_store_ok db ->
    (forall key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) = Some (key, r) ->
      db_locate f k db = Some k) ->
    db_locate f k (row_replace f k previous o db) = Some k.
  Proof.
    intros db f k previous o Hstore Haligned.
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |] eqn:Hprior.
    - specialize (Haligned key r eq_refl).
      rewrite (row_replace_old_locate db f k previous o f k key r Hstore Hprior).
      exact Haligned.
    - exact (row_replace_new_locate db f k previous o Hstore Hprior).
  Qed.

  Lemma database_history_alignment_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_history_alignment db ->
    database_history_alignment (row_replace f k previous o db).
  Proof.
    intros db f k previous o Hstore Halign g args key r Hentry Hcanonical.
    assert (Hcanonical_old : forall i, In (Id i) args -> repr db i = i).
    { intros i Hin. specialize (Hcanonical i Hin).
      unfold repr in Hcanonical |- *. now rewrite row_replace_forest in Hcanonical. }
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
      as [Hsame | Hother].
    - apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
      apply row_replace_new_locate_from_alignment; [exact Hstore |].
      intros old_key old_id Hold.
      exact (database_history_alignment_entry db Halign f k old_key old_id
        Hold Hcanonical_old).
    - assert (Hkeys : (g, args) <> (f, k)).
      { intro Heq. inversion Heq; subst. apply Hother. reflexivity. }
      rewrite (row_replace_history_other db f k previous o g args Hkeys) in Hentry.
      rewrite (row_replace_old_locate db f k previous o g args key r Hstore Hentry).
      exact (database_history_alignment_entry db Halign g args key r
        Hentry Hcanonical_old).
  Qed.

  Lemma database_active_history_coherent_row_replace : forall db f k previous o,
    database_row_store_ok db -> database_active_history_coherent db ->
    (forall key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store db)) =
        Some (key, r) -> db_locate f k db = Some k) ->
    database_active_history_coherent (row_replace f k previous o db).
  Proof.
    intros db f k previous o Hstore Hcoherent Hself
      g args output key r Hrow Hentry.
    destruct (Pos.eq_dec (db_row_code g args) (db_row_code f k))
      as [Hsame | Hother].
    - apply RowKeys.encode_inj in Hsame. injection Hsame as -> ->.
      apply row_replace_new_locate_from_alignment; [exact Hstore |].
      intros old_key old_id Hold.
      exact (Hself old_key old_id Hold).
    - assert (Hdifferent : (g, args) <> (f, k)).
      { intro Heq. inversion Heq; subst. apply Hother. reflexivity. }
      change (row (view (row_replace f k previous o db)) g args output) in Hrow.
      apply row_replace_binding in Hrow as [[Hrow _] | [Heq _]];
        [| contradiction].
      rewrite (row_replace_history_other db f k previous o g args Hdifferent)
        in Hentry.
      rewrite (row_replace_old_locate db f k previous o g args key r
        Hstore Hentry).
      exact (Hcoherent g args output key r Hrow Hentry).
  Qed.

  Lemma database_history_alignment_make : forall db f k,
    database_wf db -> database_row_store_ok db -> database_history_alignment db ->
    database_history_alignment (snd (make f k db)).
  Proof.
    intros db f k Hwf Hstore Halign.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_history_alignment_allocate_next db Hwf Hstore Halign)
      as Hfresh_align.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Halign;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_align;
      (apply database_history_alignment_row_replace;
        [exact Hfresh_store | exact Hfresh_align]).
  Qed.

  Lemma database_active_history_coherent_make : forall db f k,
    database_wf db -> database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db ->
    database_active_history_coherent (snd (make f k db)).
  Proof.
    intros db f k Hwf Hstore Halign Hcoherent.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_active_history_coherent_allocate_next db Hstore Hcoherent)
      as Hfresh_coherent.
    assert (Hfresh_loc : forall key r,
      PTrieCode.get (db_row_code f (normal_key db k))
        (row_history (db_row_store (allocate_id (N.succ_pos (ids db)) db))) =
        Some (key, r) ->
      db_locate f (normal_key db k) (allocate_id (N.succ_pos (ids db)) db) =
        Some (normal_key db k)).
    { intros key r Hentry.
      rewrite (db_locate_ids_mono db (allocate_id (N.succ_pos (ids db)) db)
        Hstore) by (try reflexivity; rewrite allocate_next_ids; lia).
      apply (database_history_alignment_entry db Halign f (normal_key db k)
        key r Hentry).
      rewrite normal_key_correct by exact Hwf.
      apply canon_key_fixed. exact Hwf. }
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hcoherent;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_coherent;
      (apply database_active_history_coherent_row_replace;
        [exact Hfresh_store | exact Hfresh_coherent | exact Hfresh_loc]).
  Qed.

  Lemma database_history_root_owner_make : forall db f k,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (snd (make f k db)).
  Proof.
    intros db f k Hstore Howner.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_history_root_owner_allocate_next db Hstore Howner)
      as Hfresh_owner.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Howner;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_owner;
      (apply database_history_root_owner_row_replace;
        [exact Hfresh_store | exact Hfresh_owner]).
  Qed.

  Lemma database_history_key_shape_make : forall db f k,
    database_row_store_ok db -> database_history_key_shape db ->
    database_history_key_shape (snd (make f k db)).
  Proof.
    intros db f k Hstore Hshape.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_history_key_shape_allocate_next db Hstore Hshape)
      as Hfresh_shape.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hshape;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_shape;
      (apply database_history_key_shape_row_replace;
        [exact Hfresh_store | exact Hfresh_shape]).
  Qed.

  Lemma database_history_codes_valid_make : forall db f k,
    database_history_codes_valid db ->
    database_history_codes_valid (snd (make f k db)).
  Proof.
    intros db f k Hvalid. unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hvalid;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try (eapply database_history_codes_valid_transport with (db := db);
        [reflexivity | exact Hvalid]);
      (apply database_history_codes_valid_row_replace;
        eapply database_history_codes_valid_transport with (db := db);
        [reflexivity | exact Hvalid]).
  Qed.

  Lemma database_history_key_ids_bounded_make : forall db f k,
    database_wf db -> database_history_key_ids_bounded db ->
    (forall i, In (Id i) k -> allocated db i) ->
    database_history_key_ids_bounded (snd (make f k db)).
  Proof.
    intros db f k Hwf Hbounded Hinput.
    assert (Hck : forall i, In (Id i) (normal_key db k) -> allocated db i).
    { rewrite normal_key_correct by exact Hwf.
      intros i Hin. exact (canon_key_allocated db k Hwf Hinput i Hin). }
    pose proof (database_history_key_ids_bounded_allocate_next db Hbounded)
      as Hfresh_bounded.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hbounded;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_bounded;
      (apply database_history_key_ids_bounded_row_replace;
        [exact Hfresh_bounded |]).
    all: intros i Hin; apply allocate_next_monotone; exact (Hck i Hin).
  Qed.

  Lemma database_row_weights_positive_make : forall db f k,
    database_row_weights_positive db ->
    database_row_weights_positive (snd (make f k db)).
  Proof.
    intros db f k Hpositive. unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hpositive;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try (apply database_row_weights_positive_allocate_next; exact Hpositive);
      apply database_row_weights_positive_row_replace;
      apply database_row_weights_positive_allocate_next; exact Hpositive.
  Qed.

  Lemma database_row_weight_conserved_make : forall db f k,
    database_row_store_ok db -> database_row_weight_conserved db ->
    database_row_weight_conserved (snd (make f k db)).
  Proof.
    intros db f k Hstore Hconserved.
    pose proof (database_row_store_ok_allocate_next db Hstore) as Hfresh_store.
    pose proof (database_row_weight_conserved_allocate_next db Hstore Hconserved)
      as Hfresh_conserved.
    unfold make.
    destruct (row_get f (normal_key db k) db) as [[[j | v] |] |];
      cbn [snd]; try exact Hconserved;
      destruct (kind_get f db) as [[| |m] |]; cbn [snd];
      try exact Hfresh_conserved;
      (apply database_row_weight_conserved_row_replace;
        [exact Hfresh_store | exact Hfresh_conserved]).
  Qed.

  Lemma database_row_store_ok_row_replace : forall db f k previous o,
    database_row_store_ok db ->
    database_row_store_ok (row_replace f k previous o db).
  Proof.
    intros db f k [before |] o Hstore; unfold row_replace.
    - apply database_row_store_ok_register.
      + apply row_write_row_store_ok.
        apply slots_update_row_store_ok, slots_update_row_store_ok.
        exact Hstore.
      + intros c Hin. rewrite row_write_written_cells, slots_update_written_cells.
        apply in_or_app. left. apply in_or_app. now left.
    - apply database_row_store_ok_register.
      + apply row_write_row_store_ok, slots_update_row_store_ok. exact Hstore.
      + intros c Hin. rewrite row_write_written_cells, slots_update_written_cells.
        apply in_or_app. left. apply in_or_app. now left.
  Qed.

  Lemma pop_loser_locate : forall db x db' f k,
    db_pop_loser db = Some (x, db') -> db_locate f k db' = db_locate f k db.
  Proof.
    intros db x db' f k Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest]; [discriminate |].
    injection Hpop as Hname Hstate. subst x db'.
    unfold db_locate.
    cbn [database_set_pending database_set_runtime runtime_set_union
      database_set_row_store db_row_store row_history row_links row_keys
      db_runtime runtime_allocated].
    destruct (PTrieCode.get (db_row_code f k) (row_history (db_row_store db)))
      as [[key r] |]; [| reflexivity].
    f_equal. apply row_root_same_links. reflexivity.
  Qed.

  Lemma pop_loser_row_store_ok : forall db x db', row_store_ok db ->
    db_pop_loser db = Some (x, db') -> row_store_ok db'.
  Proof.
    intros db x db' Hstore Hpop.
    assert (Hlocate : forall f k, db_locate f k db' = db_locate f k db).
    { intros f k. eapply pop_loser_locate. exact Hpop. }
    pose proof (proj1 (proj2 (db_pop_loser_layout db x db' Hpop))) as Hids.
    unfold row_store_ok, database_row_store_ok in Hstore.
    destruct Hstore as
      (Hlinks & Hhistory & Hcount & Hcounter & Hcells & Hdepth & Hgroup &
        Hmap & Hlabels & Hrange).
    assert (Hcountnew : N.to_nat (db_nuses db') = length (uses_entries db')).
    { eapply pop_loser_nuses_count; [exact Hmap | exact Hcount | exact Hpop]. }
    unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest]; [discriminate |].
    injection Hpop as Hname Hstate. subst x db'.
    unfold row_store_ok, database_row_store_ok.
    cbn [database_set_pending database_set_runtime database_set_row_store
      db_row_store row_history row_links row_weights row_keys row_fresh row_uses
      db_nuses db_index_counters db_written_cells ids db_runtime runtime_allocated].
    split; [exact Hlinks |].
    split.
    - intros y f k Huse. apply DatabaseUsesFacts.bucket_transfer_member in Huse.
      destruct Huse as [[Hold _] | [_ Hsource]].
      + exact (Hhistory y f k Hold).
      + exact (Hhistory i f k Hsource).
    - split; [exact Hcountnew |].
      split; [exact Hcounter |].
      split.
      + intros y f k c Huse Hcell.
        apply DatabaseUsesFacts.bucket_transfer_member in Huse.
        destruct Huse as [[Hold _] | [_ Hsource]].
        * exact (Hcells y f k c Hold Hcell).
        * exact (Hcells i f k c Hsource Hcell).
      + split.
        * intros f k key r Hget.
          destruct (Hdepth f k key r Hget) as [d [Hbound [Hroot Hcurrent]]].
          exists d. split; [rewrite Hids; exact Hbound |].
          split; [exact Hroot |]. rewrite Hlocate. exact Hcurrent.
        * split.
          -- intros f k key r d Hget Hroot. rewrite Hids.
             exact (Hgroup f k key r d Hget Hroot).
          -- split; [apply DatabaseUsesFacts.wf_transfer; exact Hmap |].
             split; [exact Hlabels | exact Hrange].
  Qed.


  Lemma database_owned_ok_pop : forall db x db',
    database_owned_ok db -> db_pop_loser db = Some (x, db') ->
    database_owned_ok db'.
  Proof.
    intros db x db' Howned Hpop.
    unfold database_owned_ok in Howned |- *.
    destruct Howned as
      (Hstore & Halign & Hcoherent & Howner & Hshape & Hvalid &
       Hbounded & Hconserved & Hpositive).
    assert (Hhistory : row_history (db_row_store db') =
      row_history (db_row_store db)).
    { unfold db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [|i rest];
        [discriminate |].
      injection Hpop as Hname Hstate. subst db'. reflexivity. }
    assert (Hlinks : row_links (db_row_store db') =
      row_links (db_row_store db)).
    { unfold db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [|i rest];
        [discriminate |].
      injection Hpop as Hname Hstate. subst db'. reflexivity. }
    assert (Hweights : row_weights (db_row_store db') =
      row_weights (db_row_store db)).
    { unfold db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [|i rest];
        [discriminate |].
      injection Hpop as Hname Hstate. subst db'. reflexivity. }
    assert (Hids : ids db' = ids db).
    { destruct (db_pop_loser_layout db x db' Hpop) as [Hslots [Hids _]].
      exact Hids. }
    assert (Hrows : forall f k, row_get f k db' = row_get f k db).
    { intros f k. unfold db_pop_loser in Hpop.
      destruct (runtime_queue (db_runtime db)) as [|i rest];
        [discriminate |].
      injection Hpop as Hname Hstate. subst db'. reflexivity. }
    split; [eapply pop_loser_row_store_ok; eassumption |].
    split; [eapply database_history_alignment_pop; eassumption |].
    split.
    { intros f k o key r Hrow Hentry.
      rewrite Hrows in Hrow. rewrite Hhistory in Hentry.
      rewrite (pop_loser_locate db x db' f k Hpop).
      exact (Hcoherent f k o key r Hrow Hentry). }
    split; [eapply database_history_root_owner_transport;
      [exact Hhistory | exact Hlinks | exact Hids | exact Howner] |].
    split; [eapply database_history_key_shape_transport;
      [exact Hhistory | exact Hlinks | exact Hids | exact Hshape] |].
    split; [eapply database_history_codes_valid_transport;
      [exact Hhistory | exact Hvalid] |].
    split; [eapply database_history_key_ids_bounded_transport;
      [exact Hhistory | rewrite Hids; lia | exact Hbounded] |].
    split; [eapply database_row_weight_conserved_transport;
      [exact Hhistory | exact Hlinks | exact Hweights | exact Hids |
       exact Hconserved] |].
    eapply database_row_weights_positive_transport;
      [exact Hweights | exact Hpositive].
  Qed.

  Lemma forest_ok_pop : forall db x db', forest_ok db ->
    db_pop_loser db = Some (x, db') -> forest_ok db'.
  Proof.
    intros db x db' Hforest Hpop.
    destruct Hforest as
      [Hlocated [Hmetadata [Hpending [Huf [Hcard [Hsame [Hwidth
      [Hstore [Hcounts [Hhistory [Hcore [Hrank [Hnonroot Howned]]]]]]]]]]]]].
    pose proof (database_owned_ok_pop db x db' Howned Hpop) as Howned'.
    pose proof (pop_loser_row_store_ok db x db' Hstore Hpop) as Hstore'.
    assert (Hlocate : forall f k, db_locate f k db' = db_locate f k db).
    { intros f k. eapply pop_loser_locate. exact Hpop. }
    unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest] eqn:Hqueue;
      [discriminate |].
    injection Hpop as Hname Hstate. subst x db'.
    unfold forest_ok. split.
    - intros f k0 k Hcurrent. unfold located in Hcurrent.
      rewrite Hlocate in Hcurrent.
      destruct (Hlocated f k0 k Hcurrent) as [o [Hrow Hkind]].
      exists o. split; [exact Hrow | exact Hkind].
    - split.
      + eapply metadata_snapshot_ok; [reflexivity | exact Hmetadata].
      + split.
        * cbn [database_set_pending database_set_runtime runtime_set_union
            db_npending pending db_runtime runtime_queue].
          unfold pending in Hpending. rewrite Hqueue in Hpending.
          rewrite Hpending. cbn [length]. rewrite Nat2N.inj_succ.
          apply N.pred_succ.
        * split; [exact Huf |].
          split; [exact Hcard |].
          split; [exact Hsame |].
          split; [exact Hwidth |].
          split; [exact Hstore' |].
          split; [exact Hcounts |].
          split; [exact Hhistory |].
          split; [exact Hcore |].
          split; [exact Hrank |].
          split.
          -- intros y Hin. unfold queue in Hin.
             cbn [database_set_pending database_set_runtime runtime_set_union
               db_runtime runtime_queue] in Hin.
             apply Hnonroot. unfold queue. rewrite Hqueue. now right.
          -- exact Howned'.
  Qed.

  Lemma pop_loser_queue : forall db x db',
    db_pop_loser db = Some (x, db') -> queue db = x :: queue db'.
  Proof.
    intros db x db' Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest] eqn:Hqueue;
      [discriminate |].
    injection Hpop as Hname Hstate. subst x db'.
    unfold queue. cbn [db_runtime database_set_pending database_set_runtime
      runtime_set_union runtime_queue]. now rewrite Hqueue.
  Qed.

  Lemma pop_loser_rows : forall db x db', db_pop_loser db = Some (x, db') ->
    rows db' = rows db.
  Proof.
    intros db x db' Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest]; [discriminate |].
    injection Hpop as Hname Hstate. subst x db'. reflexivity.
  Qed.

  Lemma pop_loser_index : forall db x db' s new,
    db_pop_loser db = Some (x, db') -> index s new db' = index s new db.
  Proof.
    intros db x db' s new Hpop. unfold db_pop_loser in Hpop.
    destruct (runtime_queue (db_runtime db)) as [|i rest]; [discriminate |].
    injection Hpop as Hname Hstate. subst x db'. reflexivity.
  Qed.

  Lemma pop_loser_slot_of : forall db x db' s,
    db_pop_loser db = Some (x, db') -> slot_of db' s = slot_of db s.
  Proof.
    intros db x db' s Hpop. unfold slot_of.
    rewrite (proj1 (db_pop_loser_layout db x db' Hpop)). reflexivity.
  Qed.

  Lemma pop_loser_kind_ok : forall db x db' f k o,
    db_pop_loser db = Some (x, db') -> kind_ok db' f k o <-> kind_ok db f k o.
  Proof.
    intros db x db' f k o Hpop.
    destruct (db_pop_loser_preserves db x db' Hpop) as [_ Hview].
    destruct (db_pop_loser_layout db x db' Hpop) as [Hslots [Hids _]].
    unfold kind_ok, allocated, slots_fit. now rewrite Hview, Hslots, Hids.
  Qed.

  (** Located historical keys resolve to stored rows of declared functions. *)
  Lemma F_forest_located : forall db f k0 k, forest_ok db -> located db f k0 = Some k ->
    exists o, In ((f, k), o) (rows db) /\ kind (view db) f <> None.
  Proof.
    intros db f k0 k Hforest Hlocated. exact (proj1 Hforest f k0 k Hlocated).
  Qed.

  (** The repair invariant retains independent cache metadata throughout an active batch. *)
  Lemma forest_metadata : forall db, forest_ok db -> metadata_ok db.
  Proof.
    intros db [_ [Hmetadata _]]. exact Hmetadata.
  Qed.

  (** The repair invariant equates the stored pending count with the queue observation. *)
  Lemma forest_pending_count : forall db, forest_ok db ->
    db_npending db = N.of_nat (pending db).
  Proof.
    intros db [_ [_ [Hpending _]]]. exact Hpending.
  Qed.

  (** Active repair keeps the same well-formed union-find discipline as public states. *)
  Lemma forest_uf_wf : forall db, forest_ok db -> UnionFind.wf (db_forest db).
  Proof.
    intros db [_ [_ [_ [Hforest _]]]]. exact Hforest.
  Qed.

  (** The forest's cardinality agrees with the exact allocation counter. *)
  Lemma forest_cardinality : forall db, forest_ok db ->
    UnionFind.card (db_forest db) = N.to_nat (ids db).
  Proof.
    intros db [_ [_ [_ [_ [Hcard _]]]]]. exact Hcard.
  Qed.

  (** The equality log and forest representatives have the same meaning during repair. *)
  Lemma forest_same_repr : forall db, forest_ok db ->
    forall i j, same (view db) i j <-> repr db i = repr db j.
  Proof.
    intros db Hforest. unfold forest_ok in Hforest. tauto.
  Qed.

  (** Repair retains the key-width bound already required by public well-formedness. *)
  Lemma forest_width_bound : forall db, forest_ok db ->
    UnionFind.width (db_forest db) <= N.size_nat (ids db).
  Proof.
    intros db Hforest. unfold forest_ok in Hforest. tauto.
  Qed.

  Lemma forest_slot_rank : forall db, forest_ok db -> slot_rank_ok db.
  Proof.
    intros db Hforest. unfold forest_ok in Hforest. tauto.
  Qed.

  (** Active entries retain coverage after their loser has left the queue. *)
  Definition inv_on (db : t) (work : list use_entry) : Prop :=
    (forall f k o, In ((f, k), o) (rows db) <-> row (view db) f k o) /\
    NoDup (map fst (rows db)) /\
    (forall f k o i, row (view db) f k o -> row_ids k o i ->
      exists x k0, repr db x = repr db i /\ uses db x (f, k0) /\
        located db f k0 = Some k /\ (x = repr db i \/ In x (queue db))) /\
    (forall f k o i, row (view db) f k o -> row_ids k o i -> repr db i <> i ->
      exists k0, scheduled db work (f, k0) /\ located db f k0 = Some k) /\
    (forall s f perm, slot_of db s = Some (f, perm) ->
      I.wf (length perm) (index s false db) /\
      I.wf (length perm) (index s true db) /\
      (forall u, I.mem (index s false db) u <->
        exists k o, row (view db) f k o /\ u = permute perm (k ++ option_list o)) /\
      (forall u, I.mem (index s true db) u -> I.mem (index s false db) u)) /\
    (forall f k o i, row (view db) f k o -> row_ids k o i ->
      (i < next_id db)%positive) /\
    (forall e, In e work -> exists x, uses db x e) /\
    forest_ok db /\
    (forall f k o, row (view db) f k o -> kind_ok db f k o) /\
    NoDup (queue db) /\ pending db = length (queue db) /\
    (forall x, In x (queue db) -> allocated db x).

  Lemma database_idle_secondary_row_replace : forall db f k previous o,
    database_idle_ok db ->
    (forall i, In (Id i) (k ++ option_list o) -> repr db i = i) ->
    forall g args output i,
      row (view (row_replace f k previous o db)) g args output ->
      row_ids args output i ->
      repr (row_replace f k previous o db) i <> i ->
      exists k0,
        scheduled (row_replace f k previous o db) [] (g, k0) /\
        located (row_replace f k previous o db) g k0 = Some args.
  Proof.
    intros db f k previous o Hidle Hcanonical g args output i Hrow Hid Hnonroot.
    pose proof (database_idle_row_store db Hidle) as Hstore.
    apply row_replace_rows in Hrow as [[Hold Hother] | [-> [-> <-]]].
    - assert (Hnonroot_old : repr db i <> i).
      { unfold repr in Hnonroot |- *. rewrite row_replace_forest in Hnonroot.
        exact Hnonroot. }
      destruct (database_idle_scheduled db Hidle g args output i Hold Hid
        Hnonroot_old) as [k0 [Hscheduled Hlocated]].
      unfold scheduled in Hscheduled. cbn [In] in Hscheduled.
      destruct Hscheduled as [Hempty | [x [Hqueue Huse]]];
        [contradiction |].
      destruct (database_uses_history db x g k0 Hstore Huse)
        as [r Hentry].
      exists k0. split.
      + unfold scheduled. right. exists x. split.
        * rewrite row_replace_queue. exact Hqueue.
        * apply row_replace_uses_old; [| exact Huse].
          unfold row_store_ok, database_row_store_ok in Hstore. tauto.
      + unfold located, locate in *.
        rewrite (row_replace_old_locate db f k previous o g k0 (g, k0) r
          Hstore Hentry). exact Hlocated.
    - exfalso. apply Hnonroot.
      unfold repr. rewrite row_replace_forest.
      exact (Hcanonical i Hid).
  Qed.

  Lemma database_idle_primary_row_replace : forall db f k previous o,
    database_idle_ok db -> database_history_alignment db ->
    (forall i, In (Id i) (k ++ option_list o) -> repr db i = i) ->
    forall g args output i,
      row (view (row_replace f k previous o db)) g args output ->
      row_ids args output i ->
      exists x k0,
        repr (row_replace f k previous o db) x =
          repr (row_replace f k previous o db) i /\
        uses (row_replace f k previous o db) x (g, k0) /\
        located (row_replace f k previous o db) g k0 = Some args /\
        (x = repr (row_replace f k previous o db) i \/
         In x (queue (row_replace f k previous o db))).
  Proof.
    intros db f k previous o Hidle Halign Hcanonical g args output i Hrow Hid.
    pose proof (database_idle_row_store db Hidle) as Hstore.
    assert (Hmap : DatabaseUseMap.wf (row_uses (db_row_store db))).
    { unfold row_store_ok, database_row_store_ok in Hstore. tauto. }
    apply row_replace_rows in Hrow as [[Hold Hother] | [-> [-> <-]]].
    - destruct (database_idle_coverage db Hidle g args output i Hold Hid)
        as [x [k0 [Hrepr [Huse [Hlocated Hactive]]]]].
      destruct (database_uses_history db x g k0 Hstore Huse)
        as [r Hentry].
      exists x, k0. unfold repr.
      rewrite row_replace_forest, row_replace_queue.
      split; [exact Hrepr |].
      split; [apply row_replace_uses_old; assumption |].
      split.
      + unfold located, locate in *.
        rewrite (row_replace_old_locate db f k previous o
          g k0 (g, k0) r Hstore Hentry). exact Hlocated.
      + exact Hactive.
    - exists i, k. unfold repr.
      rewrite row_replace_forest, row_replace_queue.
      assert (Hfixed : repr db i = i) by (apply Hcanonical; exact Hid).
      split; [reflexivity |].
      split; [apply row_replace_uses_new; assumption |].
      split.
      + unfold located, locate. apply row_replace_new_locate_from_alignment;
          [exact Hstore |].
        intros key r Hentry. apply (Halign f k key r Hentry).
        intros j Hin. apply Hcanonical. apply in_or_app. now left.
      + left. symmetry. exact Hfixed.
  Qed.



  Lemma database_idle_located_row_replace : forall db f k previous o,
    database_wf db -> database_idle_ok db -> database_history_alignment db ->
    kind_ok db f k o ->
    (forall i, In (Id i) (k ++ option_list o) -> repr db i = i) ->
    forall g k0 args,
      located (row_replace f k previous o db) g k0 = Some args ->
      exists output,
        In ((g, args), output) (rows (row_replace f k previous o db)) /\
        kind (view (row_replace f k previous o db)) g <> None.
  Proof.
    intros db f k previous o Hbase Hidle Halign Hkind Hcanonical
      g k0 args Hlocated.
    pose proof (database_idle_row_store db Hidle) as Hstore.
    assert (Hmap : RowMap.wf
      (runtime_rows (db_runtime (row_replace f k previous o db)))).
    { rewrite row_replace_map. apply RowMap.wf_set. exact (wf_row_map db Hbase). }
    assert (Hnew : located (row_replace f k previous o db) f k = Some k).
    { unfold located, locate. apply row_replace_new_locate_from_alignment;
        [exact Hstore |].
      intros key r Hentry. apply (Halign f k key r Hentry).
      intros i Hin. apply Hcanonical. apply in_or_app. now left. }
    destruct (RowKeys.eqb_spec (g, k0) (f, k)) as [Hsame | Hother].
    - injection Hsame as -> ->. rewrite Hnew in Hlocated.
      injection Hlocated as <-. exists o. split.
      + unfold rows. rewrite <- RowMap.elements_trie.
        apply row_elements_member; [exact Hmap |].
        apply row_replace_rows. right. repeat split; reflexivity.
      + rewrite row_replace_kind. unfold kind_ok in Hkind.
        destruct Hkind as [_ [_ Hshape]].
        destruct (kind (view db) f) as [decl |]; [discriminate |].
        destruct o as [c |]; [destruct c |]; contradiction.
    - unfold located, locate in Hlocated.
      destruct (PTrieCode.get (db_row_code g k0)
        (row_history (db_row_store db))) as [[key r] |] eqn:Hentry.
      + rewrite (row_replace_old_locate db f k previous o g k0 key r
          Hstore Hentry) in Hlocated.
        destruct (database_idle_located db Hidle g k0 args Hlocated)
          as [output [Hrow Hdeclared]].
        assert (Hold : row (view db) g args output).
        { unfold rows in Hrow. rewrite <- RowMap.elements_trie in Hrow.
          apply row_elements_member in Hrow; [exact Hrow | exact (wf_row_map db Hbase)]. }
        destruct (RowKeys.eqb_spec (g, args) (f, k)) as [Htarget | Hdistinct].
        * injection Htarget as -> ->. exists o. split.
          -- unfold rows. rewrite <- RowMap.elements_trie.
             apply row_elements_member; [exact Hmap |].
             apply row_replace_rows. right. repeat split; reflexivity.
          -- rewrite row_replace_kind. exact Hdeclared.
        * exists output. split.
          -- unfold rows. rewrite <- RowMap.elements_trie.
             apply row_elements_member; [exact Hmap |].
             apply row_replace_rows. left. now split.
          -- rewrite row_replace_kind. exact Hdeclared.
      + unfold db_locate in Hlocated.
        rewrite (row_replace_history_other db f k previous o g k0 Hother)
          in Hlocated.
        rewrite Hentry in Hlocated. discriminate.
  Qed.

  Lemma database_idle_ok_row_replace_canonical : forall db f k previous o,
    database_wf db -> database_idle_ok db -> database_history_alignment db ->
    kind_ok db f k o ->
    (forall i, In (Id i) (k ++ option_list o) -> repr db i = i) ->
    database_idle_ok (row_replace f k previous o db).
  Proof.
    intros db f k previous o Hbase Hidle Halign Hkind Hcanonical.
    set (next := row_replace f k previous o db).
    assert (Hstore : database_row_store_ok next).
    { subst next. apply database_row_store_ok_row_replace.
      exact (database_idle_row_store db Hidle). }
    assert (Hentry : forall x e, uses next x e <->
      In (x, e) (flat_map (fun binding => map (pair (fst binding)) (snd binding))
        (map (fun binding => (fst binding, snd (snd binding)))
          (PTrieCode.elements (row_uses (db_row_store next)))))).
    { intros x e. unfold uses, uses_entries. reflexivity. }
    unfold database_idle_ok. fold next.
    split; [exact Hstore |].
    split.
    { change (NoDup (queue next)). subst next.
      rewrite row_replace_queue. exact (database_idle_queue_distinct db Hidle). }
    split.
    { intros g args output i Hrow Hid.
      destruct (database_idle_primary_row_replace db f k previous o
        Hidle Halign Hcanonical g args output i Hrow Hid)
        as [x [k0 [Hrepr [Huse [Hlocated Hactive]]]]].
      exists x, k0. repeat split; try assumption. }
    split.
    { intros g args output i Hrow Hid Hnonroot.
      destruct (database_idle_secondary_row_replace db f k previous o
        Hidle Hcanonical g args output i Hrow Hid Hnonroot)
        as [k0 [Hscheduled Hlocated]].
      exists k0. split; [| exact Hlocated].
      unfold scheduled in Hscheduled. cbn [In] in Hscheduled.
      destruct Hscheduled as [Hempty | [x [Hqueue Huse]]];
        [contradiction |].
      exists x. split; [exact Hqueue |]. apply Hentry. exact Huse. }
    split.
    { intros g k0 args Hlocated.
      exact (database_idle_located_row_replace db f k previous o
        Hbase Hidle Halign Hkind Hcanonical g k0 args Hlocated). }
    intros x Hqueue. subst next.
    change (In x (queue (row_replace f k previous o db))) in Hqueue.
    rewrite row_replace_queue in Hqueue.
    unfold repr. rewrite row_replace_forest.
    exact (database_idle_queue_nonroot db Hidle x Hqueue).
  Qed.

  Lemma database_idle_ok_frame : forall db db',
    database_idle_ok db -> database_row_store_ok db' ->
    row_uses (db_row_store db') = row_uses (db_row_store db) ->
    runtime_rows (db_runtime db') = runtime_rows (db_runtime db) ->
    runtime_queue (db_runtime db') = runtime_queue (db_runtime db) ->
    kind (view db') = kind (view db) ->
    (forall i, repr db' i = repr db i) ->
    (forall f k, db_locate f k db' = db_locate f k db) ->
    database_idle_ok db'.
  Proof.
    intros db db' Hidle Hstore Huses Hrows Hqueue Hkind Hrepr Hloc.
    unfold database_idle_ok in Hidle |- *.
    destruct Hidle as [Hprior [Hdistinct [Hprimary [Hsecondary
      [Hlocated Hnonroot]]]]].
    rewrite Huses, Hrows, Hqueue.
    split; [exact Hstore |].
    split; [exact Hdistinct |].
    split.
    { intros f k o i Hrow Hid.
      change (row_get f k db' = Some o) in Hrow.
      unfold row_get in Hrow. rewrite Hrows in Hrow.
      change (row (view db) f k o) in Hrow.
      destruct (Hprimary f k o i Hrow Hid)
        as [x [k0 [Heq [Huse [Hfound Hactive]]]]].
      exists x, k0. rewrite !Hrepr, Hloc. repeat split; assumption. }
    split.
    { intros f k o i Hrow Hid Hnonroot'.
      change (row_get f k db' = Some o) in Hrow.
      unfold row_get in Hrow. rewrite Hrows in Hrow.
      change (row (view db) f k o) in Hrow.
      rewrite Hrepr in Hnonroot'.
      destruct (Hsecondary f k o i Hrow Hid Hnonroot')
        as [k0 [Hscheduled Hfound]].
      exists k0. rewrite Hloc. now split. }
    split.
    { intros f k0 k Hfound. rewrite Hloc in Hfound.
      destruct (Hlocated f k0 k Hfound) as [o [Hrow Hdeclared]].
      exists o. split; [exact Hrow | now rewrite Hkind]. }
    intros x Hin. rewrite Hrepr. exact (Hnonroot x Hin).
  Qed.

  Lemma database_idle_ok_allocate_next : forall db,
    database_wf db -> database_idle_ok db ->
    database_idle_ok (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db Hwf Hidle.
    eapply database_idle_ok_frame with (db := db).
    - exact Hidle.
    - apply database_row_store_ok_allocate_next.
      exact (database_idle_row_store db Hidle).
    - reflexivity.
    - reflexivity.
    - reflexivity.
    - rewrite allocate_id_view. reflexivity.
    - apply allocate_next_repr. exact Hwf.
    - intros f k. apply db_locate_ids_mono.
      + exact (database_idle_row_store db Hidle).
      + reflexivity.
      + rewrite allocate_next_ids. lia.
  Qed.

  (** Fresh allocation retains the public base, idle and slot rank facts. *)
  Lemma database_public_ok_allocate_next : forall db,
    database_public_ok db ->
    database_public_ok (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db [Hbase [Hidle Hrank]]. unfold database_public_ok.
    split; [apply wf_allocate_next; exact Hbase |].
    split.
    - apply database_idle_ok_allocate_next; assumption.
    - apply slot_rank_ok_allocate_id. exact Hrank.
  Qed.

  (** Fresh allocation retains the complete public and owned package. *)
  Lemma database_full_ok_allocate_next : forall db,
    database_public_ok db /\ database_owned_ok db ->
    database_public_ok (allocate_id (N.succ_pos (ids db)) db) /\
    database_owned_ok (allocate_id (N.succ_pos (ids db)) db).
  Proof.
    intros db [Hpublic Howned]. split.
    - apply database_public_ok_allocate_next. exact Hpublic.
    - apply database_owned_ok_allocate_next;
        [exact (database_public_base db Hpublic) | exact Howned].
  Qed.

  Lemma database_idle_ok_make : forall db f k,
    database_wf db -> database_idle_ok db -> database_history_alignment db ->
    (forall i, In (Id i) k -> allocated db i) ->
    slots_fit db f (S (length k)) ->
    database_idle_ok (snd (make f k db)).
  Proof.
    intros db f k Hwf Hidle Halign Hargs Hfits. pose proof Hwf as Hbase.
    unfold make. rewrite (normal_key_correct db k Hwf). fold (ids db).
    destruct (row_get f (map (canon db) k) db) as [[[j | v] |] |]
      eqn:Hprevious; cbn [snd]; [exact Hidle | | |].
    all: destruct (kind_get f db) as [[| |m] |] eqn:Hkind; cbn [snd];
      try (apply database_idle_ok_allocate_next; assumption).
    all: apply database_idle_ok_row_replace_canonical.
    all: try (apply wf_allocate_next; exact Hwf).
    all: try (apply database_idle_ok_allocate_next; assumption).
    all: try (apply database_history_alignment_allocate_next;
      [exact Hwf | exact (database_idle_row_store db Hidle) | exact Halign]).
    all: try (apply fresh_constructor_kind_ok; assumption).
    all: apply fresh_constructor_canonical; exact Hwf.
  Qed.

  Lemma forest_ok_public : forall db, database_wf db -> database_idle_ok db ->
    slot_rank_ok db -> database_owned_ok db -> forest_ok db.
  Proof.
    intros db Hbase Hidle Hrank Howned. unfold forest_ok.
    split; [exact (database_idle_located db Hidle) |].
    split; [exact (wf_metadata db Hbase) |].
    split; [exact (wf_pending_count db Hbase) |].
    split; [exact (wf_forest db Hbase) |].
    split.
    { change (N.to_nat (count (db_forest db)) = N.to_nat (ids db)).
      now rewrite (wf_forest_count db Hbase). }
    split; [exact (wf_equalities db Hbase) |].
    split; [exact (wf_forest_width db Hbase) |].
    split; [exact (database_idle_row_store db Hidle) |].
    split; [exact (wf_projection_counts db Hbase) |].
    split; [exact (wf_history db Hbase) |].
    split; [exact (database_wf_core_bridge db Hbase) |].
    split; [exact Hrank |].
    split; [exact (database_idle_queue_nonroot db Hidle) | exact Howned].
  Qed.

  Lemma public_rows_member : forall db f k o, database_wf db ->
    (In ((f, k), o) (rows db) <-> row (view db) f k o).
  Proof.
    intros db f k o Hbase. unfold rows. rewrite <- RowMap.elements_trie.
    apply row_elements_member. exact (wf_row_map db Hbase).
  Qed.

  Lemma public_rows_distinct : forall db, database_wf db ->
    NoDup (map fst (rows db)).
  Proof.
    intros db Hbase. unfold rows. rewrite <- RowMap.elements_trie.
    apply RowMap.elements_nodup. exact (wf_row_map db Hbase).
  Qed.

  Lemma public_slot_inv : forall db, database_wf db -> forall s f perm,
    slot_of db s = Some (f, perm) ->
    I.wf (length perm) (index s false db) /\
    I.wf (length perm) (index s true db) /\
    (forall u, I.mem (index s false db) u <->
      exists k o, row (view db) f k o /\ u = permute perm (k ++ option_list o)) /\
    (forall u, I.mem (index s true db) u -> I.mem (index s false db) u).
  Proof.
    intros db Hbase s f perm Hslot.
    split; [exact (wf_index_arity db Hbase s false f perm Hslot) |].
    split; [exact (wf_index_arity db Hbase s true f perm Hslot) |].
    split.
    - intro u. split.
      + intro Hmem. destruct (wf_index_sound db Hbase s false u Hmem)
          as [owner [layout [k [o [Howner [Hrow Hu]]]]]].
        rewrite Hslot in Howner. injection Howner as <- <-.
        exists k, o. now split.
      + intros [k [o [Hrow ->]]].
        exact (wf_index_complete db Hbase s f perm k o Hslot Hrow).
    - intros u Hmem. destruct (wf_index_sound db Hbase s true u Hmem)
        as [owner [layout [k [o [Howner [Hrow Hu]]]]]].
      rewrite Hslot in Howner. injection Howner as <- <-. subst u.
      exact (wf_index_complete db Hbase s f perm k o Hslot Hrow).
  Qed.

  Lemma public_row_kind_ok : forall db, database_wf db ->
    forall f k o, row (view db) f k o -> kind_ok db f k o.
  Proof.
    intros db Hbase f k o Hrow. unfold kind_ok.
    split; [intros i Hid; exact (wf_row_ids db Hbase f k o i Hrow Hid) |].
    split; [exact (wf_row_slots db Hbase f k o Hrow) |].
    exact (wf_row_kind db Hbase f k o Hrow).
  Qed.

  Lemma public_row_id_bound : forall db, database_wf db ->
    forall f k o i, row (view db) f k o -> row_ids k o i -> (i < next_id db)%positive.
  Proof.
    intros db Hbase f k o i Hrow Hid.
    pose proof (wf_row_ids db Hbase f k o i Hrow Hid) as Hallocated.
    unfold next_id, allocated in *. lia.
  Qed.

  Lemma public_queue_allocated : forall db, database_wf db ->
    forall x, In x (queue db) -> allocated db x.
  Proof.
    intros db Hbase x Hin.
    pose proof (wf_queue_allocated db Hbase) as Hqueue.
    rewrite Forall_forall in Hqueue. exact (Hqueue x Hin).
  Qed.

  Lemma public_inv_forward : forall db, database_wf db -> database_idle_ok db ->
    slot_rank_ok db -> database_owned_ok db -> inv_on db [].
  Proof.
    intros db Hbase Hidle Hrank Howned. unfold inv_on.
    split; [intros f k o; exact (public_rows_member db f k o Hbase) |].
    split; [exact (public_rows_distinct db Hbase) |].
    split.
    { intros f k o i Hrow Hid. eapply database_idle_coverage; eassumption. }
    split.
    { intros f k o i Hrow Hid Hnonroot.
      eapply database_idle_scheduled; eassumption. }
    split.
    { intros s f perm Hslot. exact (public_slot_inv db Hbase s f perm Hslot). }
    split.
    { intros f k o i Hrow Hid. exact (public_row_id_bound db Hbase f k o i Hrow Hid). }
    split; [intros e Hin; contradiction |].
    split; [exact (forest_ok_public db Hbase Hidle Hrank Howned) |].
    split.
    { intros f k o Hrow. exact (public_row_kind_ok db Hbase f k o Hrow). }
    split; [exact (database_idle_queue_distinct db Hidle) |].
    split; [reflexivity |].
    intros x Hin. exact (public_queue_allocated db Hbase x Hin).
  Qed.

  Lemma inv_idle_reverse : forall db, inv_on db [] -> database_idle_ok db.
  Proof.
    intros db Hinv. unfold inv_on in Hinv.
    destruct Hinv as (_ & _ & Hcoverage & Hscheduled & _ & _ & _ & Hforest & _ &
      Hqueue & _).
    unfold database_idle_ok.
    split.
    { unfold forest_ok, row_store_ok in Hforest. tauto. }
    split; [exact Hqueue |].
    split.
    { intros f k o i Hrow Hid. exact (Hcoverage f k o i Hrow Hid). }
    split.
    { intros f k o i Hrow Hid Hnonroot.
      destruct (Hscheduled f k o i Hrow Hid Hnonroot) as [k0 [Hwork Hlocated]].
      unfold scheduled in Hwork. cbn [In] in Hwork.
      destruct Hwork as [Hempty | [x [Hqueued Huse]]]; [contradiction |].
      exists k0. split; [exists x; split; assumption | exact Hlocated]. }
    split.
    - intros f k0 k Hlocated.
      exact (proj1 Hforest f k0 k Hlocated).
    - unfold forest_ok in Hforest. tauto.
  Qed.

  Lemma indexed_slot_exists : forall db s new u, metadata_ok db ->
    I.mem (index s new db) u -> exists f perm, slot_of db s = Some (f, perm).
  Proof.
    intros db s new u Hmetadata Hmem.
    assert (Hbound : runtime_slot_bound (db_runtime db) = N.of_nat (length (slots db))).
    { unfold metadata_ok in Hmetadata. tauto. }
    unfold index in Hmem.
    destruct (N.compare s (runtime_slot_bound (db_runtime db))) eqn:Hcompare;
      try (exfalso; exact (I.mem_empty u Hmem)).
    destruct (slot_of db s) as [[f perm] |] eqn:Hslot.
    - exists f, perm. reflexivity.
    - exfalso. apply N.compare_lt_iff in Hcompare.
      unfold slot_of in Hslot. apply nth_error_None in Hslot.
      assert (Houtside : (runtime_slot_bound (db_runtime db) <= s)%N).
      { rewrite Hbound. lia. }
      apply (N.lt_irrefl s). eapply N.lt_le_trans; eassumption.
  Qed.

  (** Active repair states expose cache metadata directly, without a public wf conversion. *)
  Lemma inv_on_metadata : forall db work, inv_on db work -> metadata_ok db.
  Proof.
    intros db work Hinv. apply forest_metadata. unfold inv_on in Hinv. tauto.
  Qed.

  Lemma inv_index_sound : forall db work, inv_on db work -> forall s new u,
    I.mem (index s new db) u ->
    exists f perm k o, slot_of db s = Some (f, perm) /\ row (view db) f k o /\
      u = permute perm (k ++ option_list o).
  Proof.
    intros db work Hinv s new u Hmem.
    destruct (indexed_slot_exists db s new u (inv_on_metadata db work Hinv) Hmem)
      as [f [perm Hslot]].
    pose proof Hinv as Hfacts. unfold inv_on in Hfacts.
    destruct Hfacts as (_ & _ & _ & _ & Hslots & _).
    destruct (Hslots s f perm Hslot) as [_ [_ [Hfull Hnew]]].
    assert (Hmem_full : I.mem (index s false db) u).
    { destruct new; [exact (Hnew u Hmem) | exact Hmem]. }
    destruct (proj1 (Hfull u) Hmem_full) as [k [o [Hrow Hu]]].
    exists f, perm, k, o. repeat split; assumption.
  Qed.

  Lemma inv_index_complete : forall db work, inv_on db work -> forall s f perm k o,
    slot_of db s = Some (f, perm) -> row (view db) f k o ->
    I.mem (index s false db) (permute perm (k ++ option_list o)).
  Proof.
    intros db work Hinv s f perm k o Hslot Hrow.
    unfold inv_on in Hinv. destruct Hinv as (_ & _ & _ & _ & Hslots & _).
    destruct (Hslots s f perm Hslot) as [_ [_ [Hfull _]]].
    apply (proj2 (Hfull (permute perm (k ++ option_list o)))).
    exists k, o. now split.
  Qed.

  Lemma inv_index_arity : forall db work, inv_on db work -> forall s new f perm,
    slot_of db s = Some (f, perm) -> I.wf (length perm) (index s new db).
  Proof.
    intros db work Hinv s new f perm Hslot.
    unfold inv_on in Hinv. destruct Hinv as (_ & _ & _ & _ & Hslots & _).
    destruct (Hslots s f perm Hslot) as [Hall [Hnew _]].
    destruct new; assumption.
  Qed.

  Lemma inv_base_reverse : forall db, inv_on db [] -> database_wf db.
  Proof.
    intros db Hinv.
    pose proof Hinv as Hfacts. unfold inv_on in Hfacts.
    destruct Hfacts as (_ & _ & _ & Hscheduled & _ & _ & _ & Hforest & Hkind & _ &
      Hpending_length & Hqueue_allocated).
    assert (Hcore : core_bridge db) by (unfold forest_ok in Hforest; tauto).
    destruct Hcore as [Hmembers [Hcount [Hlog [Hrowmap [Hkindbound Hmaxname]]]]].
    assert (Hmetadata : metadata_ok db) by (exact (forest_metadata db Hforest)).
    assert (Hgroups : runtime_function_slots (db_runtime db) =
      database_slot_groups 0 (prepare_slot_layouts (slots db)) PTrieCode.empty).
    { unfold metadata_ok in Hmetadata. tauto. }
    assert (Hslotbound : runtime_slot_bound (db_runtime db) =
      N.of_nat (length (slots db))).
    { unfold metadata_ok in Hmetadata. tauto. }
    assert (Hprojection : projection_counts_ok db).
    { unfold forest_ok in Hforest. tauto. }
    assert (Hhistory : database_history db).
    { unfold forest_ok in Hforest. tauto. }
    unfold database_wf.
    split; [exact (forest_uf_wf db Hforest) |].
    split; [exact Hmembers |].
    split; [exact Hcount |].
    split; [exact (forest_width_bound db Hforest) |].
    split; [exact (forest_same_repr db Hforest) |].
    split; [exact Hlog |].
    split; [exact Hrowmap |].
    split.
    { intros f k o Hrow. exact (proj2 (proj2 (Hkind f k o Hrow))). }
    split.
    { intros f k o i Hrow Hid. exact (proj1 (Hkind f k o Hrow) i Hid). }
    split.
    { intros f k o Hrow. exact (proj1 (proj2 (Hkind f k o Hrow))). }
    split; [exact Hkindbound |].
    split; [exact Hslotbound |].
    split; [exact (forest_pending_count db Hforest) |].
    split.
    { apply Forall_forall. intros x Hin. exact (Hqueue_allocated x Hin). }
    split.
    { intro Hquiet. assert (Hempty : queue db = []).
      { destruct (queue db) as [|x rest]; [reflexivity |].
        cbn [length] in Hpending_length. lia. }
      intros f k o Hrow i Hid.
      destruct (Pos.eq_dec (repr db i) i) as [Hequal | Hnonroot]; [exact Hequal |].
      destruct (Hscheduled f k o i Hrow Hid Hnonroot) as [k0 [Hwork _]].
      unfold scheduled in Hwork. rewrite Hempty in Hwork.
      destruct Hwork as [Hnone | [x [Hnone _]]]; contradiction. }
    split.
    { intros s new u Hmem. exact (inv_index_sound db [] Hinv s new u Hmem). }
    split.
    { intros s f perm k o Hslot Hrow.
      exact (inv_index_complete db [] Hinv s f perm k o Hslot Hrow). }
    split.
    { intros s new f perm Hslot.
      exact (inv_index_arity db [] Hinv s new f perm Hslot). }
    split; [exact Hgroups |].
    split; [exact Hprojection |].
    split; [exact Hmaxname | exact Hhistory].
  Qed.

  Lemma database_public_inv_iff : forall db,
    database_public_ok db /\ database_owned_ok db <-> inv_on db [].
  Proof.
    intro db. split.
    - intros [Hpublic Howned]. apply public_inv_forward.
      + exact (database_public_base db Hpublic).
      + exact (database_public_idle db Hpublic).
      + exact (database_public_rank db Hpublic).
      + exact Howned.
    - intro Hinv. split.
      + unfold database_public_ok. split.
        * exact (inv_base_reverse db Hinv).
        * split; [exact (inv_idle_reverse db Hinv) |].
          unfold slot_rank_ok in *.
          apply forest_slot_rank. unfold inv_on in Hinv. tauto.
      + unfold inv_on, forest_ok in Hinv. tauto.
  Qed.

  Lemma row_delete_counters_incl : forall f k db,
    incl (db_index_counters db) (db_index_counters (row_delete f k db)).
  Proof.
    intros f k db. unfold row_delete.
    destruct (row_get f k db) as [before |]; [| apply incl_refl].
    change (incl (db_index_counters db)
      (db_index_counters (slots_update false f (k ++ option_list before) db))).
    apply slots_update_counters_incl.
  Qed.

  Lemma row_delete_nuses : forall f k db, db_nuses (row_delete f k db) = db_nuses db.
  Proof.
    intros f k db. unfold row_delete.
    destruct (row_get f k db) as [before |]; [| reflexivity].
    change (db_nuses (slots_update false f (k ++ option_list before) db) = db_nuses db).
    apply slots_update_nuses.
  Qed.

  Lemma database_history_alignment_row_delete : forall db f k,
    database_history_alignment db ->
    database_history_alignment (row_delete f k db).
  Proof.
    intros db f k Halign.
    eapply (database_history_alignment_transport db (row_delete f k db)).
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - now rewrite row_delete_row_store.
    - apply row_delete_ids.
    - apply row_delete_forest.
    - exact Halign.
  Qed.

  Lemma database_active_history_coherent_row_delete : forall db f k,
    database_active_history_coherent db ->
    database_active_history_coherent (row_delete f k db).
  Proof.
    intros db f k Hcoherent g args o key r Hrow Hentry.
    change (row (view (row_delete f k db)) g args o) in Hrow.
    apply row_delete_binding in Hrow as [Hrow _].
    rewrite row_delete_row_store in Hentry.
    rewrite (db_locate_same_store_ids db (row_delete f k db) g args)
      by (try apply row_delete_row_store; apply row_delete_ids).
    exact (Hcoherent g args o key r Hrow Hentry).
  Qed.

  Lemma database_row_store_ok_row_delete : forall db f k,
    database_row_store_ok db -> database_row_store_ok (row_delete f k db).
  Proof.
    intros db f k Hstore.
    eapply (database_row_store_ok_transport db (row_delete f k db)).
    - now rewrite row_delete_row_store.
    - apply row_delete_nuses.
    - apply row_delete_ids.
    - apply row_delete_counters_incl.
    - apply row_delete_written.
    - exact Hstore.
  Qed.

  Lemma row_replace_written_incl : forall f k previous o db,
    incl (db_written_cells db) (db_written_cells (row_replace f k previous o db)).
  Proof.
    intros f k [before |] o db c Hin; rewrite row_replace_written;
      apply in_or_app; right; [apply in_or_app; now right | exact Hin].
  Qed.

  Lemma put_written_incl : forall f k o db,
    incl (db_written_cells db) (db_written_cells (put f k o db)).
  Proof.
    intros f k o db. unfold put.
    remember (row_get f (normal_key db k) db) as previous.
    remember (option_map (normal_cell db) o) as co.
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db | _, _ => db end).
    assert (Hnext : db_written_cells next = db_written_cells db).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |]; try reflexivity.
      unfold union. destruct (UnionFindCode.union a b (db_forest db))
        as [[pair |] forest]; [destruct pair |]; reflexivity. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + now rewrite Hnext.
      + rewrite <- Hnext. apply row_replace_written_incl.
    - rewrite <- Hnext. apply row_replace_written_incl.
  Qed.

  (** Normalization preserves the number of cells in a query key. *)
  Lemma normal_key_length : forall db k, length (normal_key db k) = length k.
  Proof.
    intros db k. unfold normal_key. apply length_map.
  Qed.

  Lemma normal_key_shape : forall db k,
    row_key_shape (normal_key db k) = row_key_shape k.
  Proof.
    intros db k. unfold row_key_shape, normal_key.
    induction k as [| cell rest IH]; [reflexivity |].
    destruct cell as [i | v]; cbn [map normal_cell];
      try destruct (N.compare (runtime_allocated (db_runtime db)) (Npos i));
      cbn; now rewrite IH.
  Qed.

  Lemma database_history_alignment_put : forall db f k o,
    UnionFind.wf (db_forest db) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_history_alignment (put f k o db).
  Proof.
    intros db f k o Hforest Hstore Halign.
    unfold put.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hnext_align : database_history_alignment next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try (apply database_history_alignment_union;
          [exact Hforest | exact Halign]); exact Halign. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext_align |].
      apply database_history_alignment_row_replace; assumption.
    - apply database_history_alignment_row_replace; assumption.
  Qed.

  Lemma put_fixed_key_locate : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    (forall i, In (Id i) k -> repr db i = i) ->
    forall key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store (put f k o db))) =
        Some (key, r) ->
      db_locate f k (put f k o db) = Some k.
  Proof.
    intros db f k o Hforest Hmembers Hstore Halign Hfixed.
    unfold put. rewrite (normal_key_of_fixed_forest db k Hforest Hmembers Hfixed).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f k db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hnext_loc : forall key r,
      PTrieCode.get (db_row_code f k) (row_history (db_row_store next)) =
        Some (key, r) -> db_locate f k next = Some k).
    { intros key r Hentry.
      assert (Hsame_store : db_row_store next = db_row_store db).
      { unfold next. destruct previous as [[[a | v] |] |];
          destruct co as [[b | w] |];
          try reflexivity; apply union_row_store_raw. }
      assert (Hsame_ids : ids next = ids db).
      { unfold next. destruct previous as [[[a | v] |] |];
          destruct co as [[b | w] |];
          try reflexivity; apply union_ids. }
      rewrite (db_locate_same_store_ids db next f k Hsame_store Hsame_ids).
      apply (database_history_alignment_entry db Halign f k key r).
      - now rewrite Hsame_store in Hentry.
      - exact Hfixed. }
    destruct previous as [before |].
    - destruct (output_eqb before updated).
      + exact Hnext_loc.
      + intros key r _. apply row_replace_new_locate_from_alignment;
          [exact Hnext_store | exact Hnext_loc].
    - intros key r _. apply row_replace_new_locate_from_alignment;
        [exact Hnext_store | exact Hnext_loc].
  Qed.

  Lemma database_active_history_coherent_put : forall db f k o,
    UnionFind.wf (db_forest db) ->
    (forall i, UnionFind.mem (db_forest db) i <-> allocated db i) ->
    database_row_store_ok db -> database_history_alignment db ->
    database_active_history_coherent db ->
    database_active_history_coherent (put f k o db).
  Proof.
    intros db f k o Hforest Hmembers Hstore Halign Hcoherent. unfold put.
    set (ck := normal_key db k).
    set (co := option_map (normal_cell db) o).
    set (previous := row_get f ck db).
    set (updated := combine_output db f previous co).
    set (next := match previous, co with
      | Some (Some (Id a)), Some (Id b) => union a b db
      | _, _ => db end).
    assert (Hnext_store : database_row_store_ok next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try apply database_row_store_ok_union; exact Hstore. }
    assert (Hnext_coherent : database_active_history_coherent next).
    { unfold next. destruct previous as [[[a | v] |] |];
        destruct co as [[b | w] |];
        try exact Hcoherent.
      unfold union. destruct (UnionFindCode.union a b (db_forest db))
        as [[pair |] forest]; [destruct pair |]; exact Hcoherent. }
    assert (Hnext_loc : forall key r,
      PTrieCode.get (db_row_code f ck) (row_history (db_row_store next)) =
        Some (key, r) -> db_locate f ck next = Some ck).
    { intros key r Hentry.
      assert (Hsame_store : db_row_store next = db_row_store db).
      { unfold next. destruct previous as [[[a | v] |] |];
          destruct co as [[b | w] |];
          try reflexivity; apply union_row_store_raw. }
      assert (Hsame_ids : ids next = ids db).
      { unfold next. destruct previous as [[[a | v] |] |];
          destruct co as [[b | w] |];
          try reflexivity; apply union_ids. }
      rewrite (db_locate_same_store_ids db next f ck Hsame_store Hsame_ids).
      apply (database_history_alignment_entry db Halign f ck key r).
      - now rewrite Hsame_store in Hentry.
      - subst ck. rewrite (normal_key_correct_forest db k Hforest Hmembers).
        intros i Hin. apply in_map_iff in Hin as [c [Hcell _]].
        destruct c as [j | v]; cbn [canon] in Hcell; [| discriminate Hcell].
        injection Hcell as <-. unfold repr.
        apply UnionFind.repr_idem. exact Hforest. }
    destruct previous as [before |].
    - destruct (output_eqb before updated);
        [exact Hnext_coherent |].
      apply database_active_history_coherent_row_replace;
        [exact Hnext_store | exact Hnext_coherent | exact Hnext_loc].
    - apply database_active_history_coherent_row_replace;
        [exact Hnext_store | exact Hnext_coherent | exact Hnext_loc].
  Qed.

  Lemma database_history_root_owner_put : forall db f k o,
    database_row_store_ok db -> database_history_root_owner db ->
    database_history_root_owner (put f k o db).
  Proof.
